  FT["PH-H3963"] = {"id":"PH-H3963","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5125_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订碧瑶市宪章若干条款，为碧瑶市法院增设1名法官，使碧瑶市法院书记官兼任市郡长，并规定其任命方式","en":"An Act Further Amending Certain Sections of the Charter of the City of Baguio, Providing for an Additional Judge for the City Court of Baguio, Making the Clerk of Court of the City of Baguio a City Sheriff, and Prescribing the Manner of His Appointment","orig":"An Act Further Amending Certain Sections of the Charter of the City of Baguio, Providing for an Additional Judge for the City Court of Baguio, Making the Clerk of Court of the City of Baguio a City Sheriff, and Prescribing the Manner of His Appointment","vi":"Đạo luật sửa đổi thêm một số điều của Hiến chương Thành phố Baguio","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกบางมาตราแห่งกฎบัตรเมือง Baguio","id":"Undang-Undang mengubah lagi beberapa pasal Piagam Kota Baguio","ms":"Akta meminda lagi beberapa seksyen Piagam Bandar Baguio"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5125","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5125_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3963-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two thousand five hundred sixty-two of the Revised Administrative Code, as amended, is further amended to read as follows:\n\"Sec. 2562. The city court. — There shall be a city court for the City of Baguio for which three judges shall be appointed. In case of absence, sickness or incapacity of any of the judges of the city court, the Secretary of Justice may designate any assistant attorney of the Department of Justice or provincial fiscal to act as judge of the city court of the City of Baguio, with all the powers of the regular judge of said court; but such acting judge shall not receive any additional compensation during the time he is acting as judge.\""}},{"id":"PH-H3963-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two thousand five hundred sixty two-c of the Revised Administrative Code is amended to read as follows:\n\"Sec. 2562-c. The Clerk of the City Court. — There shall be a clerk of the city court, who shall have the same qualifications as that of a clerk of court of a Court of First Instance and who shall be appointed by the President of the Philippines, with the consent of the Commission on Appointments, but this provision on the manner of appointment shall not apply to the present incumbent. He shall also be the sheriff of the city and shall have the same powers and duties as are now provided by law upon provincial and city sheriffs but the exercise of such powers and duties shall be limited to service of processes and other matters relating to cases pending before, or decided by, the City Court of Baguio. As such sheriff he shall be provided with at least two deputy sheriffs and other employees to be paid by the city and their salaries fixed by ordinance. He shall have the rank of an assistant department head of the city and shall receive, payable from the funds of the city, the same rate of salary of the highest paid assistant department head of the city as now fixed or may hereafter be fixed by any law. The clerk of the city court shall keep its seal and affix it to all orders, judgments, certificates, records and other documents issued by the court. He shall record in a summary manner the name of the defendant, the charge against him, the name of the prosecuting witness, the date of the arrest, the appearance of the defendant, the date of the trial, and the nature of the judgment, together with the fines and costs adjudged or collected in accordance with the judgment. He shall have the power to administer oaths. He shall be an ex-officio notary public.\""}},{"id":"PH-H3963-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Certain Sections of the Charter of the City of Baguio, Providing for an Additional Judge for the City Court of Baguio, Making the Clerk of Court of the City of Baguio a City Sheriff, and Prescribing the Manner of His Appointment","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3964"] = {"id":"PH-H3964","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5126_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第二司法区增设一名法官主持拉乌尼翁初审法院，常设于拉乌尼翁省Bauang市镇，为此修订1948年《司法法》第50条与第52条的法案","en":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, with Permanent Station in the Municipality of Bauang, Province of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","orig":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, with Permanent Station in the Municipality of Bauang, Province of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["labor","judiciary"],"docNumber":"Republic Act No. 5126","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5126_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3964-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The second paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, otherwise known as \"The Judiciary Act of 1948,\" as amended, is further amended to read as follows:\n\"Eighteen judges shall be commissioned for the Second Judicial District. Four judges shall preside over the Court of First Instance of Ilocos Norte; four judges shall preside over the Court of First Instance of Ilocos Sur; one judge shall preside over the Court of First Instance of Abra; two judges shall preside over the Court of First Instance of the City of Baguio and the Sub-province of Benguet; three judges shall preside over the Court of First Instance of Mountain Province with jurisdiction covering the whole of Mountain Province, except the City of Baguio and the Sub-province of Benguet; four judges shall preside over the Court of First Instance of La Union and shall be known as judges of the first, second third and fourth branches thereof, respectively.\""}},{"id":"PH-H3964-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Second Judicial District, three judges shall be stationed in the Municipality of Laoag, Province of Ilocos Norte; one judge shall be stationed in the Municipality of Batac, same province; two judges in the Municipality of Vigan Province of Ilocos Sur; one judge in the Municipality of Narvacan, same province; one judge in the Municipality of Candon, same province; two judges in the City of Baguio; one judge in the Municipality of Bontoc, Subprovince of Bontoc; one judge in the Municipality of Kiangan, subprovince of Ifugao; one judge in the Municipality of Tabuk, Subprovince of Kalinga; one judge in the Municipality of Bangued, Province of Abra; two judges in the Municipality of San Fernando, Province of La Union; one judge in the Municipality of Agoo, same province; and one judge in the Municipality of Bauang, same province.\""}},{"id":"PH-H3964-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, such sum as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3964-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, with Permanent Station in the Municipality of Bauang, Province of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3965"] = {"id":"PH-H3965","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5127_1967.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Contact Philippines，Inc. 在菲律宾境内建设、安装和维护无线电寻呼站的特许经营权法案","en":"An Act Granting Contact Philippines, Inc. a Franchise to Construct, Install and Maintain Radio Paging Stations Within the Philippines","orig":"An Act Granting Contact Philippines, Inc. a Franchise to Construct, Install and Maintain Radio Paging Stations Within the Philippines","vi":"Đạo luật cấp đặc quyền cho Contact Philippines, Inc. để xây dựng, lắp đặt và duy trì trạm nhắn tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Contact Philippines, Inc. ในการก่อสร้าง ติดตั้ง และบำรุงรักษาสถานีวิทยุเรียกตัวในฟิลิปปินส์","id":"Undang-Undang memberikan konsesi kepada Contact Philippines, Inc. untuk membangun, memasang, dan memelihara stasiun panggilan radio di Filipina","ms":"Akta memberikan konsesi kepada Contact Philippines, Inc. untuk membina, memasang dan menyelenggarakan stesen panggilan radio di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5127","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5127_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3965-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law, Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act and their amendments, and other applicable laws not inconsistent with this Act, Contact Philippines, Inc. is hereby granted a franchise to install, construct and maintain radio paging stations for the transmission and reception of signs, signals, radiophoto, facsimile, music, pictures, voice and sound or intelligence or any nature by radio and other electro-magnet systems within the Philippines."}},{"id":"PH-H3965-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the approval of this Act, and is granted upon the express condition that the same shall be void unless the construction of the paging stations be begun within six months from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H3965-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall contribute to the public welfare, shall assist in the function of public information and education, shall conform to the ethics of honest enterprise, and shall not use its station for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3965-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio paging stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave length to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H3965-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio paging stations of the grantee shall be so constructed and operated and the wave length so selected as to avoid interference with existing radio stations and to permit of the expansion of the grantee’s service."}},{"id":"PH-H3965-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3965-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other person or corporations are now or hereafter may be required by law to pay."}},{"id":"PH-H3965-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3965-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privilege granted thereby."}},{"id":"PH-H3965-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3965-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Contact Philippines, Inc. a Franchise to Construct, Install and Maintain Radio Paging Stations Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3966"] = {"id":"PH-H3966","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5128_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将宿务市Cebu师范学校更名为Cebu师范学院的法案","en":"An Act Changing the Name of Cebu Normal School in Cebu City to Cebu Normal College","orig":"An Act Changing the Name of Cebu Normal School in Cebu City to Cebu Normal College","vi":"Đạo luật đổi tên Cebu Normal School in Cebu City thành Cebu Normal College","th":"พระราชบัญญัติเปลี่ยนชื่อ Cebu Normal School in Cebu City เป็น Cebu Normal College","id":"Undang-Undang mengubah nama Cebu Normal School in Cebu City menjadi Cebu Normal College","ms":"Akta menukar nama Cebu Normal School in Cebu City menjadi Cebu Normal College"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5128","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5128_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3966-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Cebu Normal School in Cebu City is hereby changed to Cebu Normal College."}},{"id":"PH-H3966-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Cebu Normal School in Cebu City to Cebu Normal College","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3967"] = {"id":"PH-H3967","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5129_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将邦阿西楠省初审法院两名法官的驻地由Dagupan市迁至邦阿西楠省Santa Barbara与Mangaldan市镇，为此修订《1948年司法法》第52条的法案","en":"An Act Transferring the Stations of the Two Judges of the Court of First Instance of Pangasinan from the City of Dagupan to the Municipalities of Santa Barbara and Mangaldan, Province of Pangasinan, Amending for the Purpose Section Fifty-Two of the Judiciary Act of 1948","orig":"An Act Transferring the Stations of the Two Judges of the Court of First Instance of Pangasinan from the City of Dagupan to the Municipalities of Santa Barbara and Mangaldan, Province of Pangasinan, Amending for the Purpose Section Fifty-Two of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5129","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5129_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3967-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The third subparagraph of the second paragraph of Section fifty-two of Republic Act Numbered Two hundred ninety-six, otherwise known as \"The Judiciary Act of 1948,\" is further amended to read as follows:\n\"For the Third Judicial District, two judges shall be stationed in the Municipality of Lingayen, Province of Pangasinan; one judge shall be stationed in the City of Dagupan; two judges, in the Municipality of Urdaneta, Province of Pangasinan; one judge in the Municipality of Tayug, same province; one judge in the Municipality of Alaminos, same province; one judge in the Municipality of Santa Barbara, same province; and another in the City of San Carlos; the judge of the first branch of the Court of First Instance of Zambales shall be stationed in the Municipality of Olongapo, Province of Zambales, and the judge of the second branch, in the Municipality of Iba, same province.\""}},{"id":"PH-H3967-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Stations of the Two Judges of the Court of First Instance of Pangasinan from the City of Dagupan to the Municipalities of Santa Barbara and Mangaldan, Province of Pangasinan, Amending for the Purpose Section Fifty-Two of the Judiciary Act of 1948","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3968"] = {"id":"PH-H3968","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5131_1967.html","fetchedAt":"2026-10-06","articleCount":90,"structureMode":"ARTICLE","title":{"zh":"设立Tangub市","en":"An Act Creating the City of Tangub","orig":"An Act Creating the City of Tangub","vi":"Đạo luật thành lập Thành phố Tangub","th":"พระราชบัญญัติจัดตั้งเมือง Tangub","id":"Undang-Undang membentuk Kota Tangub","ms":"Akta mewujudkan Bandaraya Tangub"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5131","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 85 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5131_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 90 条，缺 15、73、86、87、88）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3968-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"Article I Title of Act"},"heading":{"en":"Title of Act.— This Act shall be known as \"The Charter of the City of Tangub.\""},"text":{"en":"Section 1. Title of Act.— This Act shall be known as \"The Charter of the City of Tangub.\""}},{"id":"PH-H3968-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"Article II General Provisions"},"heading":{"en":"Territory of the City of Tangub.— The City of Tangub, which is hereby created, shall comprise the present territorial ju"},"text":{"en":"Section 2. Territory of the City of Tangub.— The City of Tangub, which is hereby created, shall comprise the present territorial jurisdiction of the Municipality of Tangub, Province of Misamis Occidental."}},{"id":"PH-H3968-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"Article II General Provisions"},"heading":{"en":"Corporate character of the city.— The City of Tangub constitutes a political body corporate and as such is endowed with"},"text":{"en":"Section 3. Corporate character of the city.— The City of Tangub constitutes a political body corporate and as such is endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this Charter."}},{"id":"PH-H3968-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"Article II General Provisions"},"heading":{"en":"Seal and general powers of the city.— The city shall have a common seal, and may alter the same at pleasure. It may take"},"text":{"en":"Section 4. Seal and general powers of the city.— The city shall have a common seal, and may alter the same at pleasure. It may take purchase, receive, hold, lease, convey, and dispose of real and personal property for the general interests of the city, condemn private property for public use, contract and be contracted with, sue and be sued, prosecute as well as defend to final judgment and execution actions where its interests are involved, and exercise all powers hereinafter conferred."}},{"id":"PH-H3968-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"Article II General Provisions"},"heading":{"en":"City not liable for damages.— The city shall not be liable or held for damages or injuries to persons or property arisin"},"text":{"en":"Section 5. City not liable for damages.— The city shall not be liable or held for damages or injuries to persons or property arising from the failure of the City Mayor, the City Council, or any other city officer or employee, to enforce the provisions of this Charter, or of any other law or ordinance, or from the negligence of said City Mayor, City Council or other city officers or employees while enforcing or attempting to enforce said provisions: Provided, However, That nothing herein contained shall prevent any aggrieved party from filing a personal action in the proper court against any official or employee of the city government for any act or omission in the performance of his duties."}},{"id":"PH-H3968-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"Article II General Provisions"},"heading":{"en":"Jurisdiction of the city.— The jurisdiction of the City of Tangub for police purposes shall be co-extensive with its ter"},"text":{"en":"Section 6. Jurisdiction of the city.— The jurisdiction of the City of Tangub for police purposes shall be co-extensive with its territorial jurisdiction; and shall extend to three miles from the shores of the city; and for the purpose of protecting and insuring the purity of the water supply of the city, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The City Court of the city shall have concurrent jurisdiction with the Municipal Court of the respective municipalities to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters.1avvphi1 The court first taking jurisdiction of such an offense shall thereafter retain exclusive jurisdiction thereof. The police force of the several municipalities concerned shall have concurrent jurisdiction with the police force of the city for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued within said zone, area or spaces shall be granted by the proper authorities of the municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said municipality concerned and not to that of the city."}},{"id":"PH-H3968-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"Article III The City Mayor and the Vice-Mayor"},"heading":{"en":"The City Mayor.— The City Mayor shall be the chief executive of the city. He shall be elected by the qualified voters of"},"text":{"en":"Section 7. The City Mayor.— The City Mayor shall be the chief executive of the city. He shall be elected by the qualified voters of the city and shall hold office for a term of four years, the first elected mayor to begin serving upon the expiration of the term of office of the incumbent municipal mayor. He shall receive a compensation of six thousand pesos per annum, and shall be entitled, in addition to his salary, to a non-commutable allowance of not exceeding two thousand four hundred pesos per annum. No person shall be eligible for election as City Mayor, unless he is not less than thirty years of age, a resident of the city or that of the former Municipality of Tangub for at least two years prior to his election, and a qualified voter therein."}},{"id":"PH-H3968-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"Article III The City Mayor and the Vice-Mayor"},"heading":{"en":"The City Vice-Mayor.— There shall be a City Vice-Mayor who shall be chosen in the same manner as the City Mayor, and sha"},"text":{"en":"Section 8. The City Vice-Mayor.— There shall be a City Vice-Mayor who shall be chosen in the same manner as the City Mayor, and shall possess the same qualifications as that of the City Mayor. He shall perform the duties and exercise the powers of the City Mayor in the event of the death, sickness, absence or other temporary incapacity of the incumbent, or in the event of a permanent vacancy in the position of City Mayor. If, for any reason, the City Vice-Mayor is temporarily incapacitated for the performance of the duties of the City Mayor, or said office of the City Vice-Mayor is vacant, the duties and powers of the City Mayor shall be performed and exercised by the councilor who obtained the highest number of votes during the election for members of the City Council. The City Vice-Mayor shall be the presiding officer of the City Council, with no right to vote except in case of tie, and shall perform such other duties as may be assigned to him by the City Mayor or prescribed by law or ordinance. He shall receive a compensation of four thousand two hundred pesos per annum."}},{"id":"PH-H3968-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"Article III The City Mayor and the Vice-Mayor"},"heading":{"en":"General powers and duties of the City Mayor.— Unless otherwise provided by law, the City Mayor shall have immediate cont"},"text":{"en":"Section 9. General powers and duties of the City Mayor.— Unless otherwise provided by law, the City Mayor shall have immediate control over the executive and administrative functions of the different departments of the city, subject to the authority and supervision of the Office of the President. He shall have the following general powers and duties:\n(a) To comply with and enforce and give the necessary orders for the faithful enforcement and execution of the laws and ordinances in effect within the jurisdiction of the city.\n(b) To safeguard all the lands, buildings, records, moneys, credits, and other properties and rights of the city, and, subject to the provisions of this Charter, have control over all its property.\n(c) To see that all taxes and other revenues of the city are collected, and applied in accordance with the appropriations to the payment of municipal expenses.\n(d) To cause to be instituted judicial proceedings to recover property and funds of the city wherever found, to cause to be defended all suits against the city, and otherwise to protect the interests of the city.\n(e) To see that the executive officers and employees of the city properly discharge their respective duties. The City Mayor may, in the interest of the service and with the approval of the Department Head of the National Government first had, transfer officers and employees not appointed by the President of the Philippines from one section, division, or service to another section, division, or service within the same department without changing the compensation they receive.\n(f) To examine and inspect the books, records, and papers of all officers, agents, and employees of the city over whom he has executive supervision and control at least once a year, and whenever occasion arises. For this purpose he shall be provided by the City Council with such clerical or other assistance as may be necessary.\n(g) To give such information and recommend such measures to the Council as he shall deem advantageous to the city.\n(h) To represent the city in all its business matters and sign in its behalf all its bonds, contracts, and obligations made in accordance with law or ordinance.\n(i) To submit to the City Council at least two months before the beginning of each fiscal year a budget of receipts and expenditures of the city.\n(j) To receive, hear, and decide as he may deem proper the petitions, complaints, and claims of the residents concerning all classes of municipal matters of an administrative or executive character.\n(k) To grant or refuse municipal licenses or permits of all classes and to revoke the same for violation of the conditions upon which they were granted, or if acts prohibited by law or municipal ordinance are being committed under the protection of such license or in the premises in which the business for which the same have been granted is carried on, or for any other good reason of general interest.\n(l) To exempt, with the concurrence of the division superintendent of schools, deserving poor pupils from the payment of school fees or any part thereof.\n(m) To take such emergency measures as may be necessary to avoid fires and floods and mitigate the effects storms and other public calamities.\n(n) To submit an annual report to the Office of the President.\n(o) To perform such other duties and exercise such other executive powers as may be prescribed by law or ordinance."}},{"id":"PH-H3968-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"Article III The City Mayor and the Vice-Mayor"},"heading":{"en":"Secretary to the City Mayor.— The City Mayor shall appoint one secretary who shall hold office at the pleasure of the Ci"},"text":{"en":"Section 10. Secretary to the City Mayor.— The City Mayor shall appoint one secretary who shall hold office at the pleasure of the City Mayor and who shall receive a compensation, to be fixed by ordinance approved by the Office of the President, at not less than one thousand eight hundred pesos per annum.\nThe secretary shall have charge and custody of all records and documents of the city and of any office or department thereof for which provision is not otherwise made; shall keep the corporate seal and affix the same with his signature to all ordinances and resolutions signed by the City Mayor and to all other official documents and papers of the government of the city as may be required by law or ordinance; shall attest all executive orders, proclamations, ordinances, and resolutions signed by the City Mayor; shall, upon request, furnish certified copies of all city records and documents in his charge which are not of a confidential character and shall charge twenty centavos for each one hundred words or fraction thereof, including the certificate, such fees to be paid directly to the city treasurer; and shall perform such other duties as the City Mayor may require of him."}},{"id":"PH-H3968-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"Composition and compensation.— The City Council shall be the legislative body of the city and shall be composed of the C"},"text":{"en":"Section 11. Composition and compensation.— The City Council shall be the legislative body of the city and shall be composed of the City Vice-Mayor, who shall be its presiding officer, and eight councilors who shall be elected at large by the qualified voters of the city during every election for provincial, city and municipal officials in conformity with the provisions of the Revised Election Code. In case of sickness, absence, suspension or any other temporary disability of any member of the Council, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform all the duties of a member of the Council until the return to duty of the regular incumbent.\nIf the City Vice-Mayor or any member of the City Council shall be a candidate for office in any election, he shall be disqualified to act with said body in the performance of the duties thereof relative to such election, and if, for such reason, the number of members should be unduly reduced, the President shall appoint any disinterested voter of the city, belonging to the political party of the disqualified member, to act in his place in such matters.\nThe members of the City Council shall receive a salary of one thousand eight hundred pesos each per annum."}},{"id":"PH-H3968-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"Qualifications, election, suspension and removal of members.— The members of the City Council shall, at the time of thei"},"text":{"en":"Section 12. Qualifications, election, suspension and removal of members.— The members of the City Council shall, at the time of their election, be qualified voters of the city, residents therein for at least two years prior to their election, and not less than twenty-five years of age. Such members may be suspended or removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officials, and the provisions of law governing the suspension or removal of elective provincial officials are hereby made applicable in the suspension or removal of said members.\nElection for members of the Council shall be held on the date of the regular election for provincial, city and municipal officials, and elected members shall assume office on the first day of January immediately following their election, upon qualifying, and shall hold office for four years and until their successors shall have been duly elected and qualified. The eight candidates receiving the greatest number of votes shall be declared elected. A vacancy in the City Council shall be filled in accordance with the provisions of the Revised Election Code."}},{"id":"PH-H3968-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"Secretary of the Council.— The Council shall have a secretary who shall be appointed by it to serve during the term of o"},"text":{"en":"Section 13. Secretary of the Council.— The Council shall have a secretary who shall be appointed by it to serve during the term of office of the members thereof. The compensation of the secretary shall be fixed by ordinance at not less than one thousand eight hundred pesos per annum. A vacancy in the office of the Secretary shall be filled temporarily for the unexpired term in like manner.\nThe secretary shall be in charge of the records of the City Council. He shall keep a complete record of the proceedings of the Council, and file all the documents relating thereto; shall record, in a book kept for that purpose, all ordinances and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Council, with the dates of passage of the same, and of the publication of ordinances; shall keep a seal, circular in form with the inscription \"City Council—City of Tangub,\" in the center of which shall be placed the coat of arms of the city, and affix the same, with his signature, to all ordinances and other official acts of the Council, and shall present the same for signature to the presiding officer; shall cause each ordinance passed to be published as herein provided, shall, upon request, furnish certified copies of all records of public character in his charge under the seal of his office and collect and receive therefor such fees as may be prescribed by resolution of the Council; and shall keep his office and all the records therein which are not of a confidential nature open to public inspection during usual business hours."}},{"id":"PH-H3968-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"Legislative procedure.— The City Council shall hold one regular session for the transaction of business each week on a d"},"text":{"en":"Section 14. Legislative procedure.— The City Council shall hold one regular session for the transaction of business each week on a day which it shall fix by resolution, and such special sessions as may be necessary for the public interest, as may be called by the City Mayor. Its sessions, regular or special, shall be open to the public, unless otherwise ordered by the affirmative vote of a majority of all the members of the Council. It shall keep a record of all the proceedings and determine its rules of procedure not herein set forth. A majority of all the members of the Council shall constitute a quorum for the transaction of business, but a smaller number may adjourn from day to day and may compel the immediate attendance of any number who is absent without good cause by issuing to the police of the city an order for his arrest and attendance at the session under such penalties as shall have been previously prescribed by ordinance. The affirmative vote of a majority of all the members shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority votes of the members present at any session duly called and held. The yeas and nayes shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and, at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the City Council, and recorded in a book kept for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance of the City Hall and in at least two other public places, and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion, or vetoed by the City Mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes unless otherwise stated in the ordinance, resolution or motion.\nEach ordinance and each resolution or motion directing the payment of money or creating liability, enacted or adopted by the Council, shall be forwarded to the City Mayor for his approval. Within ten days after the receipt of the ordinance, resolution or motion, the City Mayor shall return it with his approval or veto. If he does not return it within that time, it shall be deemed to be approved. If he returns it with his veto, his reasons therefor in writing shall accompany it. It may then again be enacted by a two-thirds vote of all the members of the Council.\nThe City Mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of any ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not affect the item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions or motions returned to the Council with his veto; but should an item or items in an appropriation ordinance be disapproved by the City Mayor, the corresponding item or items in the appropriation ordinance of the previous year shall be deemed reenacted."}},{"id":"PH-H3968-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"General powers and duties of the Council.— Except as otherwise provided by law, and subject to the conditions and limita"},"text":{"en":"Section 15. General powers and duties of the Council.— Except as otherwise provided by law, and subject to the conditions and limitations thereof, the City Council shall have the following legislative powers:\n(a) To provide for the levy and collection of taxes for general and specific purposes in accordance with law, including specifically the power to levy real property tax not to exceed one and one-half per centum and valorem: Provided, That the said maximum rate of one and one-half per centum shall not be imposed during, the first five years of the effectivity of this Act.\n(b) To fix with the approval of the department head of the National Government the number and salaries of officials and employees of the city not otherwise provided for in this Act.\n(c) To make all appropriations for the expenses of the government of the City.\n(d) To authorize the free distribution of medicine to the employees and laborers of the city whose salary or wage does not exceed one hundred and twenty pesos per month or four pesos per day, and evaporated or fresh native milk to indigent mothers, residing in the city and of bread and light meals to indigent children ten years or less of age residing in the city, the distribution to be made under the direct supervision and control of the City Mayor.\n(e) To fix the tariff of fees and charges for all services rendered by the city or any of its departments, branches or officials.\n(f) To provide for the erection and maintenance of the rental, in case of need, of the necessary buildings for the use of the city.\n(g) To provide for the establishment and maintenance of public schools; and, except as otherwise provided by law, to fix, with the approval of the Director of Public Schools, reasonable matriculation and/or tuition fees for immediate and secondary instruction therein and to acquire sites for schoolhouses for primary and intermediate classes through purchases or conditional or absolute donation.\n(h) To establish and maintain or aid in the establishment and maintenance of vocational schools and institutions of higher learning conducted by the National Government or any of its subdivisions or agencies; and, with the approval of the Director of Public Schools, to fix reasonable tuition fees for instruction in the vocational schools and in the institutions of higher learning supported by the city.\n(i) To maintain any city court established by law which shall have jurisdiction of all criminal cases under the ordinances of the city, and such further jurisdiction as may be herein or hereafter conferred.\n(j) To provide for and maintain an efficient police force for the maintenance of law and order in the city, and make all necessary police ordinances, with a view to the confinement and reformation of vagrants, disorderly persons, mendicants, prostitutes and persons convicted of violating any of the ordinances of the city.\n(k) To provide for and maintain a city fire department and to establish and maintain engine houses, fire engines hose trucks, hooks and ladders, and other equipment for the prevention and extinguishment of fires, and to regulate the management and use of the same.\n(l) To establish fire zones, determine the kinds of buildings or structures that may be erected within their limits, regulate the manner of constructing and repairing the same, and fix the fees for permits for the construction, repair, or demolition of buildings and other structures.\n(m) To regulate the use of lights in stables, shops, and other buildings and places and to regulate and restrict the issuance of permits for the building of bonfires and rockets, and other pyrotechnic displays, and to fix the fees for such permits.\n(n) To make regulations to protect the public from conflagrations and to prevent and mitigate the effects of famine, floods, storms and other public calamities, and provide relief for victims thereof.\n(o) To tax, regulate and fix the amount of license fees for the following: hawkers, peddlers, hucksters, not including hucksters or peddlers who sell only native vegetables, fruits, or foods, personally carried by the hucksters or peddlers, barbers, collecting agencies, manicurists, hair dressers, tattooers, jugglers, acrobats, wrestlers and boxers; shooting galleries, slot machines, merry-go-rounds and other similar riding devices, and the keeping, preparation, and sale of meat, poultry, fish, game, butter, cheese, lard, vegetable, bread, and other provisions; and to impose a municipal occupation tax, not to exceed fifty pesos per annum, on lawyers, physicians, dentists, architects, civil, electrical, mechanical, chemical or mining engineers, radio engineers or technicians, certified public accountants, opticians and optometrists, veterinarians, land surveyors, insurance agents and sub-agents, business agents and business consultants, professional appraisers or connoisseurs of tobacco or other domestic or foreign, music teachers, piano tuners, nurses and midwives, auctioneers, plumbers, electrical contractors, building contractors, massagists, physical culture instructors, chiropodists, money changers, real estate, commercial and other brokers, and persons engaged in the transportation of passengers or freight by hire, including common carriers and transportation contractors: Provided, That persons exercising their profession or occupation only as salaried employees and not as independent practitioners shall be exempt from the municipal occupation tax herein prescribed.\n(p) To tax, fix the license fee and regulate the business of hotels, restaurants, refreshment places, cafes, lodging houses, brewers, distillers, rectifiers, laundries, dyeing and cleaning establishments, beauty parlors, physical or beauty culture and fashion schools, clubs, livery garages, public warehouses, pawnshops, theaters, cinematographers, and the letting or subletting of lands and buildings, whether used for commercial, industrial or residential purposes; and further to fix the location of, and to tax, fix the license fee on, and regulate the business of livery stables, boarding stables, embalmers, public billiard tables, public poll tables, bowling alleys, dance halls, public dance halls, cabarets, night clubs, circuses and other similar parades, public vehicles, public ferries, cockpits, dealers in second hand materials or merchandise, junk dealers, theatrical performances, boxing contests, public exhibitions, blacksmith shops, foundries, steam boilers, lumber yards, shipyards, the storage and sale of gunpowder, tar, pitch, resin, coal, oil, gasoline, benzine, turpentine, hemp, cotton, nitroglycerin, petroleum or any of the products thereof and of all other highly combustible or explosive materials, and other establishments likely to endanger the public safety or give rise to conflagrations or explosions, and subject to the provisions of ordinances issued by Bureau of Health in accordance with law, tanneries, renderies, tallow, chandleries, bone factories, soap factories: Provided, That no license shall be granted to any theater or cinematograph unless the applicant for said license agrees to exhibit pictures made in the Philippines to the extent of five per centum of their annual exhibitions: And Provided, further, That any violation of this condition shall cause the revocation of said license.\n(q) To tax and fix the license fees on printers or bookbinders or both, manufacturers of rope, paper, leather goods, including shoes, slippers, sandals, harnesses and valises or bags, sporting goods, rubber goods, plastics and celluloid products, hardware, including glassware, cooking utensils, electrical goods, and construction materials, chemical products, including drugs, perfumed, toilets articles, paints, dyes and inks, textiles, shell lamps or lamp shades or both, statuettes or tombstones or both, sacks, furniture of all kinds, including rattan goods, wire, brass beds or both, clothing, hats, eyeglasses or optical goods or both, fertilizes or buttons.\nManufacturers abovementioned shall not be subject to the payment of any municipal tax or license fee as retail dealers of their own products: Provided, That any manufacturing conducted solely by the immediate members of a family at their own home shall not be subject to any tax or license fee.\n(r) To tax and fix the license fee on dealers in general merchandise, including importers and indentors, except those dealers who may be expressly subject to the payment of some other municipal tax under the provisions of this section.\nDealers in general merchandise shall be classified as (a) wholesale dealers and (b) retail dealers. For purposes of the tax on retail dealers, general merchandise shall be classified into four main classes, namely: (1) luxury articles, (2) semi-luxury articles, (3) essential commodities, and (4) miscellaneous articles. A separate commodities of different classes are sold in the same license shall be prescribed for each class but where establishment, it shall not be compulsory for the owner to secure more than one license if he pays the higher or highest rate of tax prescribed by ordinance. Wholesale dealers shall pay the license tax as such, as may be provided by ordinance.\nFor purposes of this section, the term \"general merchandise\" shall include poultry and livestock, agricultural products, fish and other allied products.\n(s) To tax, fix the license fee on and regulate the sale, trading in or disposal of alcoholic and malt beverages, wines, and mixed or fermented liquors, including tuba, basi, tapuy, lambanog, offered for retail sale.\n(t) To impose a tax on all products or commodities manufactured or produced in the city and removed therefrom.\n(u) To impose a sales tax of not exceeding one per centum of the gross value in money of all articles sold, bartered, exchanged or transferred within the city.\n(v) To regulate the method of using steam engines and boilers, and all other motive powers other than marine, or belonging to the government of the Philippines; to provide for the inspection thereof, and fix a reasonable fee for such inspection and to regulate and fix the fees for the licenses of the engineers engaged in operating the same.\n(w) To provide for the prohibition and suppression of riots, affrays, disturbances, and disorderly assemblies; houses of ill-fame and other disorderly houses; gaming houses, gambling and all fraudulent devices for the purpose of obtaining money or property; prostitution, vagrancy, intoxication, fighting, quarreling and all disorderly conduct; and printing, circulation, exhibition, possession or sale of obscene pictures, books, or publication, and for the maintenance and preservation of peace and good morals.\n(x) To prohibit or regulate and fix the license fees for the keeping of dogs, and to authorize their impounding and destruction when running at large contrary to ordinances and to tax and regulate the keeping or training of fighting cocks.\n(y) To establish and maintain municipal pounds; to regulate, restrain and prohibit the running at large of domestic animals, and provide for the distraining, impounding, and sale of the same for the penalty incurred, and the cost of the proceedings; and to impose penalties upon the owners of said animals for the violation of any ordinance in relation thereto.\n(z) To prohibit, and provide for the punishment of, cruelty to animals.\n(aa) To require property owners by ordinance to construct or repair, at their expense, sidewalks along the street or streets adjacent to their lots in accordance with the specifications of the city engineer as to the quality, width and grade, and subject to his supervision and approval, providing that, in case of failure or inability of the property owners to comply with the requirement within a specified period of time after demand, the city engineer shall cause the work to be done and the cost thereof collected as a special assessment from such owners, who may choose to pay the same in full, or in ten equal yearly installments which shall be due and payable to the City of Tangub in the same manner as the annual tax levied on real estate and shall be made subject to the same penalties for delinquency, and enforceable by the same remedies, as such annual tax; and all said sums and amounts shall, from the day in which they are assessed, constitute liens on the property against which the same were assessed and shall take precedence over any and all other liens which may exist upon such property excepting only such as may have been attached as a result of the non-payment of said annual tax.\n(bb) To regulate the inspection, weighing, and measuring of brick, lumber, coal and other articles or merchandise.\n(cc) Subject to the provisions of existing law, to provide for the laying out, construction and improvement, and to regulate the use of streets, avenues, alleys, sidewalks, wharves, piers, parks, cemeteries and other public places; to provide for lighting, cleaning, and sprinkling of streets, and public places; to regulate, fix license fees for and prohibit the use of the same processions, signs, signposts, awnings, awning posts, and the carrying or displaying of banners, placards, advertisements, or hand bills, or the flying of signs, flags or banners whether along, across, over or from buildings along the same; to prohibit the placing, throwing, depositing, or leaving of obstacles of any kind, garbage, refuse, or other offensive matter or matters liable to cause damage in the street and other public places and to provide for the collection and disposition thereof; to provide for the inspection of, fix the license fees for and regulate the openings in the same for the laying of water, sewer and other pipes, the building and repair of tunnels, sewers and drains, and all structures in and under the same and the erecting of poles and the stringing of wires therein; to provide for and regulate crosswalks, curbs and gutters thereon; to name streets without names and provide for and regulate the numbering of houses and lots fronting thereon or in the interior of the blocks; to regulate traffic and sales upon the streets and other public places; to provide for the abatement of nuisances in the same and punish the authors and owners thereof; to provide for the construction and maintenance and regulate the use of bridges, viaducts and culverts; to prohibit and regulate ball playing, hoop rolling, and other amusements which may annoy persons using the streets and public places or frighten horses or other animals; to regulate the speed of horse and other animal driven vehicles within the limits of the city.\n(dd) To provide for the construction and maintenance of, and regulate the navigation on, canals and water courses within the city and provide for the cleansing and purification of the same; unless otherwise provided by law, to provide for the construction and maintenance, and regulate the use of public landing places, wharves, piers, docks, and levees, and those of private ownership; and to provide for or regulate the drainage and filling of private premises when necessary in the enforcement of sanitary rules and regulations issued in accordance with law.\n(ee) Subject to the provisions of the Public Service Law, to fix the charges to be paid by all watercraft landing at or using public wharves, docks, levees, or landing places owned, operated, managed or controlled by the city.\n(ff) Any provision of law to the contrary notwithstanding, to provide for the maintenance of waterworks for the purpose of supplying water to the inhabitants of the city, and for the purification of the source of water supply and the places through which the same passes, and to regulate the consumption and use of water; to fix, subject to the provisions of the Public Service Law, and to provide for the collection of rents therefor and to regulate the construction, repair and use of hydrants, pumps, cisterns and reservoirs.\n(gg) To provide for the establishment and maintenance and regulate the use of public drains, sewers, latrines and cesspools.\n(hh) Subject to the rules and regulations issued by the Director of Health Services in accordance with law, to provide for the establishment, maintenance and to fix the fees for the use of, and regulate public stables, laundries and baths, and public markets by any person, entity, association, or corporation other than the city.\n(ii) To established or authorize the establishment of slaughterhouses, to provide for their veterinary or sanitary inspection, to regulate the use of the same, and to charge reasonable slaughter fees. No fees shall be charged for veterinary or sanitary inspection of meat from large cattle or domestic animals slaughtered outside the city, when such inspection was had at the place where the animals were slaughtered.\n(jj) To regulate, inspect and provide measures preventing any discrimination or the exclusion of any race or races in or from any institution, establishment, or service open to the public within the city limits, or in the sale and supply of gas or electricity, or in the telephone service; to fix and regulate charges therefor where the same has not been fixed by national law, to regulate and provide for the inspection of all gas, electric and telephone conduits, main, meters, and other apparatus, and provide for the condemnation, substitution, or removal of the same when defective or dangerous.\n(kk) To declare, prevent and provide for the abatement of nuisances; to regulate the ringing of bells and the making of loud or unusual noises; to provide that owners, agents, or tenants of building or premises keep and maintain the same in sanitary condition and that, in case of failure to do so within sixty days from the date a written notice is served the city health officer shall cause the same to be kept in a sanitary condition, and the cost thereof to be assessed against the owner to the extent of not to exceed sixty per centum of the assessed value, which cost shall constitute a lien against the property; and to regulate and/or prohibit, or fix the license fees for the use of property on or near public ways, grounds, or places, or elsewhere within the city, for display by electric signs or the erection or maintenance of billboards or structures of whatever materials erected, maintained, or used for the display of posters, signs, or other pictorial or reading matter, except signs displayed at the place or places where the profession or business advertised thereby is in whole or in part conducted.\n(ll) To provide for the enforcement of the rules and regulations issued by the Director of Health Services; and by ordinance to prescribe penalties for violation of such rules and regulations.\n(mm) To extend its ordinances over all waters within the city, and over any boat or other floating structures thereon and for the purpose of protecting and insuring the purity of the water supply of the city, over all territory within the drainage area of such water supply, and within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service.\n(nn) To regulate any other business or occupation being conducted within the city not specifically mentioned in the preceding paragraphs, and to impose a license fee upon all persons engaged in the same or who enjoy privileges in the city.\n(oo) To fix and regulate the size, speed, and operation of motor and other vehicles within the city; to regulate the lights used on such vehicles; to establish bus stops and terminals; and prohibit and regulate the entrance of provincial public utility vehicles into the city, except those passing through the city.\n(pp) To grant fishing and fishery privileges subject to the provisions of the Fisheries Act.\n(qq) To fix the date of the holding of a fiesta in the city and any of its constituent barrios, and limit the holding of the same to once a year only, and to alter, not oftener than once in three years, the date fixed for the celebration thereof.\n(rr) To enact all ordinances it may deem necessary and proper for the sanitation and safety, the furtherance of the prosperity, and the promotion of the morality, peace, good order, comfort, convenience, and general welfare of the city and its inhabitants, and such others as may be necessary to carry into effect and discharge the powers and duties conferred by this Charter; and to fix penalties for the violation of ordinances, which shall not exceed a two hundred pesos fine or six months imprisonment, or both such fines and imprisonment for a single offense.\n(ss) To exercise the power of eminent domain with the approval of the Department Head concerned or the President of the Philippines for the following purposes; the construction or extension of roads, streets, sidewalks, boulevards, seawalls, bridges, ferries, levees, wharves, or piers, airfields, the construction of public buildings including schoolhouses and the making the necessary improvements in connection therewith; the establishment of parks, playgrounds, plazas, market places, artesian wells, or systems for the supply of water, irrigation, canals and dams, and the establishment of nurseries, breeding centers for animals, health centers, hospitals, cemeteries, crematories, drainage systems, cesspools, or sewage systems or abattoirs.\n(tt) To dispose by lease or otherwise all lands of the public domain ceded to it by the National Government pursuant to the provisions of this Charter."}},{"id":"PH-H3968-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"Article IV The City Council"},"heading":{"en":"Restrictive provisions.— No commercial sign, signboard, or billboard shall be erected or displayed on public lands, prem"},"text":{"en":"Section 16. Restrictive provisions.— No commercial sign, signboard, or billboard shall be erected or displayed on public lands, premises or buildings. If, after due investigation, and having given owners an opportunity to be heard, the City Mayor shall decide that any sign, signboard, or billboard displayed or exposed to public view is offensive to the sight or is otherwise a nuisance, he may order the removal of such sign, signboard or billboard, and if same is not removed within ten days after he has issued such order, he may himself cause its removal, and the sign, signboard, or billboard shall thereupon be forfeited to the city and the expenses incident to the removal of the same shall become a lawful charge against any person or property liable for the erection or display thereof."}},{"id":"PH-H3968-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"City Departments.— There shall be the following city departments over which the City Mayor shall have direct control and"},"text":{"en":"Section 17. City Departments.— There shall be the following city departments over which the City Mayor shall have direct control and supervision, any existing law to the contrary notwithstanding: (a) Finance and Assessment Department; (b) Engineering and Public Works Department; (c) Law Department; (d) Health Department; and (e) Police and Fire Department.\nThe City Council may from time to time make such readjustments of the duties of the different departments as the public interest may demand, and, with the approval of the President, may consolidate any department, division or office with any other department, division or office of the city."}},{"id":"PH-H3968-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Powers and duties of heads of department.— Each head of department of the city government shall be in control of such de"},"text":{"en":"Section 18. Powers and duties of heads of department.— Each head of department of the city government shall be in control of such department under the direction of the City Mayor and shall possess such powers as may be prescribed herein or by ordinance. He shall certify to the correctness of all payrolls and vouchers of his department covering the payment of money before payment, except as herein otherwise expressly provided. At least four months before the beginning of each fiscal year, he shall prepare and present to the City Mayor an estimate of the receipts and appropriation necessary for the operation of his department during the ensuing fiscal year, and shall submit therewith such information for purposes of comparison as the City Mayor may desire. He shall submit to the City Mayor as often as required reports covering the operation of his department.\nIn case of absence or sickness, or inability to act for any other reason, of the head of any of the city departments, the officer next in rank of that department, shall act in his place with authority to sign all necessary papers, vouchers, requisitions, and similar documents."}},{"id":"PH-H3968-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Appointment and removal of officials and employees.— The President of the Philippines, with the consent of the Commissio"},"text":{"en":"Section 19. Appointment and removal of officials and employees.— The President of the Philippines, with the consent of the Commission on Appointments, shall appoint the city judge, the city treasurer, the city engineer, the city fiscal, the chief of police, the city health officer, the city assessor, the chief of the fire department, the city superintendent of schools, and other heads of such city departments as may be created. Said officers shall not be suspended nor removed except in the manner and for causes provided by law.\nSubject to the provisions of the Civil Service Law, the City Mayor shall appoint all other officers and employees paid out of city funds, and they shall be suspended or removed in accordance with law."}},{"id":"PH-H3968-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Officers not to engage in certain transactions.— It shall be unlawful for any city officer, individually or as a member"},"text":{"en":"Section 20. Officers not to engage in certain transactions.— It shall be unlawful for any city officer, individually or as a member of a firm, to engage in any business transaction with the city, or with any of its authorized officials, boards, agents or attorneys, whereby money is to be paid, out of the resources of the city to such person or firm; or to purchase any real estate or other property belonging to the city, or which shall be sold for taxes or assessments, or by virtue of legal process at the suit of the city; or to be surety for any person having a contract or doing business with the city, for the performance of which surety may be required; or to be surety on the official bond of any officer of the city; and shall not be financially interested in any transaction or contract in which the National Government or any subdivision or instrumentality thereof is an interested party."}},{"id":"PH-H3968-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"Article VI Relation to Bureaus and other Offices"},"heading":{"en":"The General Auditing Office.— The Auditor General shall receive and audit all accounts of the city in accordance with th"},"text":{"en":"Section 21. The General Auditing Office.— The Auditor General shall receive and audit all accounts of the city in accordance with the provisions of law relating to government accounts and accounting. The provincial auditor of the Province of Misamis Occidental shall at the same time be ex-officio city auditor."}},{"id":"PH-H3968-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"Article VI Relation to Bureaus and other Offices"},"heading":{"en":"The Bureau of Public Schools.— The Director of Public Schools shall exercise the same jurisdiction and powers in the cit"},"text":{"en":"Section 22. The Bureau of Public Schools.— The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines, and the division superintendent of schools of the Province of Misamis Occidental shall at the same time be the ex-officio city superintendent of schools, and shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their division: Provided, That salaries of the supervisors, principals, teachers, and other operational expenses of the primary, intermediate, high school, and other public schools in the city shall be borne by the National Government."}},{"id":"PH-H3968-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"Article VI Relation to Bureaus and other Offices"},"heading":{"en":"The Land Registration Commission.— The Commissioner of the Land Registration Commission shall exercise the same jurisdic"},"text":{"en":"Section 23. The Land Registration Commission.— The Commissioner of the Land Registration Commission shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines, and the register of deeds of the Province of Misamis Occidental shall be the ex-officio register of deeds of the city."}},{"id":"PH-H3968-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"The City Treasurer.— There shall be a City Treasurer who shall have the charge of the finance and assessment department"},"text":{"en":"Section 24. The City Treasurer.— There shall be a City Treasurer who shall have the charge of the finance and assessment department and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary of four thousand two hundred pesos per annum, in accordance with the provisions of the Republic Act Numbered Eight hundred forty. He shall at the same time be the ex-officio city assessor, and shall have the following general powers and duties:\n(a) He shall collect all taxes due the city, all licenses authorized by law or ordinance, all rents due for lands, markets and other properties owned by the city, and all further charges of whatever nature fixed by law or ordinance; shall administer market and slaughterhouses, and shall receive and issue receipts for all costs, fees, fines and forfeitures imposed by the municipal court of the city.\n(b) He shall collect all miscellaneous charges made by the engineering and public works department and by other departments of the city government, and all charges made by the city engineer for inspections, permits, licenses, and the installation, maintenance, and services rendered in the operation of the private privy system.\n(c) Unless otherwise specifically provided by law or resolution, he shall perform in and for the city the duties imposed by law or resolution upon provincial treasurers in general as well as other duties imposed upon him by law.\n(d) He shall purchase and issue all supplies, equipment or other property required by the city, through the purchasing agent, or otherwise, as may be authorized, subject to the general provisions of law relating thereto.\n(e) He shall be accountable for all funds and property of the city and shall render such accounts in connection therewith as may be prescribed by the Auditor General.\n(f) He shall deposit all city funds and collections in any bank duly designated as Government depository in accordance with the existing rules and regulations.\n(g) He shall disburse the funds of the city in accordance with duly authorized appropriations, upon properly executed vouchers bearing the approval of the chief of the department concerned, and on or before the twentieth day of each month he shall furnish the City Mayor and the City Council, for the information, a statement of the appropriation, expenditures, and balances of all funds and accounts as of the day of the month preceding.\n(h) He shall be the custodian of all moneys released for public works for the city from the National Government, and shall disburse the same.\nThe City Treasurer, as ex-officio City Assessor, shall have the following powers and duties:\n(a) The City Assessor and his authorized deputies are empowered to administer any oath authorized to be administered in connection with the valuation of the real estate for the assessment and collection of taxes.\n(b) He shall make a list of the taxable real estate in the city, arranging in the order of the lot and block numbers the names of the owners thereof, with a brief description of the property opposite each such name and the cash value thereof. In making this list, the City Assessor shall take into consideration any sworn statement made by the owners of the property, but shall not be prevented thereby from considering any other evidence on the subject and exercising his own judgment in respect thereto. For the purpose of completing this list, he and his representatives may enter upon the real estate for the purpose of examining and measuring it, and may summon witnesses, administer oaths to them, and subject them to examination concerning the ownership and the amount of real estate and its cost value.\n(c) He may, if necessary, examine the records of the register of deeds of the province and the city showing the ownership of real estate in the city."}},{"id":"PH-H3968-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Real estate exempt from taxation.— The following shall be exempted from taxation:"},"text":{"en":"Section 25. Real estate exempt from taxation.— The following shall be exempted from taxation:\n(a) Lands or buildings owned by the National Government or the City of Tangub, and buying grounds, churches, and adjacent parsonages and convents, and lands or buildings used exclusively for religious, charitable, scientific, or educational purposes, and not for profit.\n(b) Lands and buildings which are the only real property of the owner, and the value of which does not exceed four hundred pesos.\n(c) Machinery, which term shall embrace machines, mechanical contrivances, instruments, appliances, and apparatus attached to real estate, used for industrial, agricultural or manufacturing purposes, during the first two years of the operation of the machinery."}},{"id":"PH-H3968-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Declaration to be made by persons acquiring or improving real estate.— It shall be the duty of each person who, at any t"},"text":{"en":"Section 26. Declaration to be made by persons acquiring or improving real estate.— It shall be the duty of each person who, at any time, acquires real estate in the city, and of each person who constructs or adds to any improvements on real estate owned by him in the city, to prepare and present to the City Assessor within a period of sixty days next following such acquisition, construction or addition, a sworn declaration setting forth the value of the real estate acquired or the improvement constructed or addition made by him and description of such property sufficient to enable the city assessor readily to identify the same. Any person having acquired real estate who fails to make and present the declaration herein required within the said period of sixty days shall be deemed to have waived his right to notice of the assessment of such property, and the assessment of the same in the name of its former owner shall, in all such cases, be valid and binding on all persons interested, and for all purposes, as though the same has been assessed in the name of its present owner."}},{"id":"PH-H3968-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Action when owner makes no returns or is unknown, or ownership is in dispute or in doubt, or when land and improvements"},"text":{"en":"Section 27. Action when owner makes no returns or is unknown, or ownership is in dispute or in doubt, or when land and improvements are separately owned.— If the owner of any parcel of real estate shall fail to make a return thereof, or if the city assessor is unable to discover the owner of any real estate, he shall nevertheless list the same for taxation, and charge the tax against the true owner, if known, and if unknown then as against an unknown owner. In case of doubt or dispute as to ownership of real estate, the taxes shall be levied against the possessor or possessors thereof. When it shall appear that there are separate owners of the land and the improvements thereon, a separate assessment of the property of each shall be made."}},{"id":"PH-H3968-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Action in case estate has escaped taxation.— If it shall come to the knowledge of the city assessor that any taxable rea"},"text":{"en":"Section 28. Action in case estate has escaped taxation.— If it shall come to the knowledge of the city assessor that any taxable real estate in the city has escaped listing, it shall be his duty to list and value the same at the time and in the manner provided in the succeeding section and to charge against the owner thereof the taxes due for the current year and the last preceding one year, and the taxes thus assessed shall be legal and collectible by all the remedies herein provided, and if the failure of the city assessor to assess such taxes at the time when they should have been assessed was due to any fault or negligence on the part of the owner of such property, the penalties shall be added to such back taxes as though they had been assessed at the time when they should have been assessed."}},{"id":"PH-H3968-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"When assessment may be increased or reduced.— The City Assessor shall, during the first fifteen days of January of each"},"text":{"en":"Section 29. When assessment may be increased or reduced.— The City Assessor shall, during the first fifteen days of January of each year, add to his list of taxable real estate in the city the value of the improvements placed upon such property during the preceding year, and any property which is taxable and which has theretofore escaped taxation. He may, during the same period, revise and correct the assessed value of any or all parcels of real estate in the city which are not assessed at their true money value, by reducing or increasing the existing assessment, as the case may be."}},{"id":"PH-H3968-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Publication of complete list and proceedings thereon.— The city assessor shall, after the list have been completed, info"},"text":{"en":"Section 30. Publication of complete list and proceedings thereon.— The city assessor shall, after the list have been completed, inform the public by notice published for seven days in a newspaper of general circulation in the city, if any, and by notice posted for seven days at the main entrance of the City Hall, that the list is on file in his office and may be examined by any person interested therein, and that upon the date fixed in the notice, which shall not be later than the tenth day of February, the city assessor will be in his office in the purpose of hearing complaints as to the accuracy of the listing of the property and the assessed value thereof. He shall further notify in writing to each person the amount of whose tax will be changed by such proposed revision, by delivering or mailing at least thirty days in advance of the date fixed in the notice such notification to such person or his authorized agent at the last known address of the said owner or agent in the Philippines, sometime in the month of January. It shall be his duty carefully to preserve and record in his office copies of said notice. On the day fixed in the notice, and for five days thereafter, he shall be present in his office to hear all complaints filed within the period by persons against whom taxes have been assessed as owners of real estate, and he shall make his decision forthwith and enter the same in a well-bound book, to be kept by him for that purpose, and if he shall determine that injustice had been done or errors have been committed he is authorized to amend the list in accordance with his findings."}},{"id":"PH-H3968-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"City assessor to authenticate list of real estate assessed.— City assessor has to authenticate each list of real estate"},"text":{"en":"Section 31. City assessor to authenticate list of real estate assessed.— City assessor has to authenticate each list of real estate valued and assessed by him as soon as the same is completed, by signing the following certificate at the foot thereof:\n\"I hereby certify that the foregoing list contains a true statement of the piece or pieces of taxable real estate belonging to each person named in the list, and its true cash value, and that no real estate taxable by law in the City of Tangub has been omitted from the list, according to the best of my knowledge and belief.\n____________________\n(Signature) City Assessor\""}},{"id":"PH-H3968-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Time and manner of appealing to Board of Tax Appeals.— In case any owner of real estate, or his authorized agent, shall"},"text":{"en":"Section 32. Time and manner of appealing to Board of Tax Appeals.— In case any owner of real estate, or his authorized agent, shall feel aggrieved by any decision of the city assessor under the preceding sections of this Article, such owner or agent may, within thirty days after the entry of such decision, appeal to the Board of Tax Appeals. The appeal shall be perfected by filing a written notice of the same with the city assessor and it shall be the duty of that officer forthwith to transmit the appeal to the Board of Tax Appeals with all the written evidence in his possession relating to such assessment and valuation."}},{"id":"PH-H3968-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Constitution and compensation of Board of Tax Appeals.— There shall be a Board of Tax Appeals which shall be composed of"},"text":{"en":"Section 33. Constitution and compensation of Board of Tax Appeals.— There shall be a Board of Tax Appeals which shall be composed of five members to be appointed by the President of the Philippines with the consent of the Commission on Appointments. Three members of the Board shall be selected from among government officials in the city other than those in charge of assessment and they shall serve without additional compensation. The two other members shall be selected from among property owners in the city and they shall each receive a compensation of ten pesos for each day of session actually attended. The chairman of the Board shall be designated in the appointment and shall have the power to designate any city official or employee to serve as the secretary of the Board without additional compensation.\nThe members of the Board of Tax Appeals shall hold office for a term of two years unless sooner removed by the President of the Philippines."}},{"id":"PH-H3968-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Oath to be taken by members of the Board of Tax Appeals.— Before organizing as such, the members of the Board of Tax App"},"text":{"en":"Section 34. Oath to be taken by members of the Board of Tax Appeals.— Before organizing as such, the members of the Board of Tax Appeals shall take the following oath before the municipal judge or some other officer authorized to administer oaths:\n\"I do solemnly swear (or affirm) that I will hear and determine well and truly all matters and issues between taxpayers and the city assessor submitted for my decision. So help me God. (In case of affirmation the last four words are to be stricken out.)\n____________________\n(Signature)\n\"Member of the Board of Tax Appeals\"\n\"Subscribed and sworn to (or affirmed) before me this _______ day of ______________, 19_______\n____________________\n(Signature and title of officer administering)"}},{"id":"PH-H3968-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Proceedings before Board \"the oath\" Tax Appeals and the Department Head.— The Board of Tax Appeals shall hold such numbe"},"text":{"en":"Section 35. Proceedings before Board \"the oath\" Tax Appeals and the Department Head.— The Board of Tax Appeals shall hold such number of sessions as may be authorized by the Secretary of Finance, shall hear all appeals only transmitted to it and shall decide the same forthwith. It shall have authority to cause to be amended the listing and valuation of the property in respect to which any appeal has been perfected by order signed by the board or a majority thereof, and transmit it to the city assessor who shall amend the tax list in conformity with said order. It shall also have the power to revise and correct, with the approval of the Department Head first had, any and all erroneous or unjust assessments and valuations for taxation, and make a correct and just assessment and state the true valuation in each case when it decides that the assessment previously made is erroneous or unjust. The assessment when so corrected shall be as lawful and valid for all purposes as though the assessment has been made within the time herein prescribed. Such reassessment and revaluation shall be made on due notice to the individual concerned who shall be entitled to be heard by the Board of Tax Appeals before any reassessment or revaluation has been made. The decision of the Board of Tax Appeals shall be final unless the Department Head declares the decision reopened for review by him in which case he may make such revision or revaluation as in his opinion the circumstances justify. Such revision when approved by the President of the Philippines shall be final."}},{"id":"PH-H3968-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Taxes on real estate—Extension and remission of the tax.— A tax, the rate of which shall not exceed two per centum ad va"},"text":{"en":"Section 36. Taxes on real estate—Extension and remission of the tax.— A tax, the rate of which shall not exceed two per centum ad valorem to be determined by the City Council, shall be levied annually on or before the second Monday of January on the assessed value of all real estate in the city subject to taxation; all taxes for any year shall be due and payable annually on the first day of June and from this date such taxes together with all penalties accruing thereto shall constitute a lien on the property subject to such taxation.\nSuch lien shall be superior to all other liens, mortgages or encumbrances of any kind whatsoever; and shall be enforceable against the property whether in the position of the delinquent or any subsequent owner, and can only be removed by the payment of the tax and penalty.\nAt the option of the taxpayer, the tax for any year may be paid in two installments to be fixed annually by the City Council simultaneously with the rate per centum ad valorem taxation: Provided, That the time limit for the first and second installment shall be set at not later than the thirty-first of May and the thirtieth day of October of each year, respectively.\nAny person, who on the last day set for the payment of real estate tax as provided in the preceding paragraphs, shall be within the premises of the City Hall willing and ready to pay the tax but is unable to effect it on account of the large number of taxpayers therein present, shall be furnished a properly prescribed card which will entitle him to pay the tax without penalty on the following day.\nThe words \"paid under protest\" shall be written upon the face of the real estate tax receipt upon the request of any person willing to pay the tax under protest. Confirmation in writing of an oral protest shall be made within thirty days.\nAt the expiration of the time for the payment of the real estate tax without penalty, the taxpayer shall be subject, from the first day of delinquency, to the payment of a penalty at the rate of two per centum for each full month of delinquency that has expired, on the amount of original tax due, until the tax shall have been paid in full or until the property shall have been forfeited to the city as provided in this Act: Provided, That in no case shall the total penalty exceed twenty-four per centum of the original tax due. In the event that the crop is extensively damaged or that a great lowering of the prices of products is registered in any year, or that a similar disaster extends throughout the province, or for other good and sufficient reason, the City Council may, be resolution passed on or before the thirty-first day of December of each year, extend the time for the collection of the tax real estate in the City of Tangub for a period not to exceed three months, or remit wholly or in part the payment of the tax or penalty for the ensuing year, but such resolution shall have to specify clearly the grounds for such extension or remission and shall not take effect until it shall have been approved by the Department Head.\nThe President of the Philippines may, in his discretion, remit or reduce the real estate taxes for any year in the city if he deems this to be in the public interest."}},{"id":"PH-H3968-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Seizure of the personal property for delinquency in payment of the tax.— After a property shall have become delinquent i"},"text":{"en":"Section 37. Seizure of the personal property for delinquency in payment of the tax.— After a property shall have become delinquent in the payment of taxes and said taxes and corresponding penalties shall remain unpaid ninety days after the payment thereof shall have become due, the city treasurer, or his deputy, if he desires to compel payment through seizure of any personal property of any delinquent person or persons, shall issue a duly authenticated certificate, based on the records of his office, showing the fact of delinquency and the amount of the tax and penalty due from said delinquent person or persons or from each of them. Such certificate shall be sufficient warrant for the seizure of the personal property belonging to the delinquent person or persons in question not exempt form seizure; and these proceedings may be carried out by the city treasurer, his deputy, or any other officer, authorized to carry out legal proceedings."}},{"id":"PH-H3968-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Personal property exempt from seizure and sale for delinquency.— The following personal property shall be exempt form se"},"text":{"en":"Section 38. Personal property exempt from seizure and sale for delinquency.— The following personal property shall be exempt form seizure, sale and execution for delinquency in the payment of the real estate tax:\n(a) Tools and implements necessarily used by the delinquent in his trade or employment.\n(b) One horse, cow or carabao, or other beast of burden, such as the delinquent may select, and necessarily used by him in his ordinary occupation.\n(c) His necessary clothing and that of his family.\n(d) Household furniture and utensils necessary for housekeeping and used for that purpose by the delinquent, such as he may select of a value not exceeding one hundred pesos:\n(e) Provisions for individual or family use sufficient for four months.\n(f) The professional libraries of lawyers, judges, clergymen, physicians, engineers, schoolteachers, and music teachers, not exceeding five hundred pesos in value.\n(g) The fishing boat and net, not exceeding the total value of one hundred pesos, the property of any fisherman, by the lawful use of which he earns a livelihood.\n(h) Any article or material which forms part of a home or of any improvement on any real estate."}},{"id":"PH-H3968-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"The owner may redeem personal property before sale.— The owner of the personal property seized may redeem the same from"},"text":{"en":"Section 39. The owner may redeem personal property before sale.— The owner of the personal property seized may redeem the same from the collecting officer at any time after seizure and before sale by tendering to him the amount of the tax, the penalty, and the cost incurred up to the time of tender. The costs to be charged in making such seizure and sale shall only embrace the actual expenses of seizure and preservation of the property pending the sale, and no charge shall be imposed for the services of the collecting officer or his deputy."}},{"id":"PH-H3968-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Sale of seized personal property.— Unless redeemed as hereinbelow provided, the property seized through proceedings unde"},"text":{"en":"Section 40. Sale of seized personal property.— Unless redeemed as hereinbelow provided, the property seized through proceedings under Section thirty-seven hereof, shall after due advertisement, be exhibited for sale at public auction and so much of the same shall satisfy the tax, penalty, and cost of seizure and same shall be sold to the highest bidder. The purchaser at such sale shall acquire an indefeasible title to the property sold. The advertisement shall state the time, place and cause of sale, and be posted for ten days prior to the date of the auction, at the main entrance of the City Hall and at a public conspicuous place in the district where the property was seized.\nThe sale shall take place, at the discretion of the city treasurer or his deputy, either at the main entrance of the City Hall or at the district where such property was seized. If no satisfactory bid is offered in the aforementioned districts, another auction shall be had, upon notice published anew."}},{"id":"PH-H3968-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Return of Owner—Disposal of surplus.— The officer directing the sale under the preceding section shall forthwith make re"},"text":{"en":"Section 41. Return of Owner—Disposal of surplus.— The officer directing the sale under the preceding section shall forthwith make return of his proceedings, and note thereof shall be made by the city treasurer upon his records. Any surplus resulting from the sale, over and above the tax penalty and cost, and any property remaining in the possession of the officer, shall be returned to the taxpayer on account of whose delinquency the sale has been made."}},{"id":"PH-H3968-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Vesting title to real estate in city government.— Upon the expiration of one year from date on which the taxpayer became"},"text":{"en":"Section 42. Vesting title to real estate in city government.— Upon the expiration of one year from date on which the taxpayer became delinquent, and in the event of continued default in the payment of the tax and penalty, all private rights, titles and interest in and to the real estate on which said tax is delinquent, shall be indefeasibly vested in the city government, subject only to the rights of redemption and repurchase provided for hereinbelow: Provided, That the title acquired by said city government to real estate shall not be superior to the title thereto of the original owner prior to the seizure thereof."}},{"id":"PH-H3968-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Redemption of real estate before seizure.— At any time after the delinquency shall have been occurred, but not after the"},"text":{"en":"Section 43. Redemption of real estate before seizure.— At any time after the delinquency shall have been occurred, but not after the expiration of ninety days from the date of the publication of the advertisement provided for in the next succeeding section, the owner or his lawful representative, or any person having any lien, right, or any other legal or equitable interest in said property, may pay the taxes and penalties accrued and thus redeem the property. Such redemption shall operate to divest the city government of its title to the property in question and to revert the same to the Original Owner; but when such redemption shall be made by a person other than the owner, the payment shall constitute a lien on the property, and the person making such payment shall be entitled to recover the same from the original owner, or if he be a lessee, he may return the amount of said payment from the proceeds of such property: Provided, That the person exercising the right of redemption shall not acquire a title to said property better than that of the regular owner prior to the seizure."}},{"id":"PH-H3968-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Notice of seizure of real estate.— Notice of the seizure of the real estate shall be made by posting notices at the main"},"text":{"en":"Section 44. Notice of seizure of real estate.— Notice of the seizure of the real estate shall be made by posting notices at the main entrance of the City Hall, the provincial capitol building and all the municipal buildings in the Province of Misamis Occidental, in English and Spanish and in the dialect commonly used in the locality, and a copy of said notice shall be sent by registered mail to the owner of the property. A copy of said notice shall also be posted on the property subject to seizure. Such notices shall estate the name of the delinquent persons, the date on which such delinquency commenced, the amount of the taxes and penalties then due from each, and shall state that unless such taxes and penalties are paid within ninety days from the date of the publication of such notice, the forfeiture of the delinquent real estate to the city government shall become absolute."}},{"id":"PH-H3968-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Ejectment of occupants of seized property.— After the expiration of ninety days from the date of the publication of the"},"text":{"en":"Section 45. Ejectment of occupants of seized property.— After the expiration of ninety days from the date of the publication of the notice of delinquency provided for in the next preceding section, the city treasurer, or his deputy, may issue to the Mayor or to other officers authorized by law to execute and enforce the laws a certificate describing the parcel of real estate on which the taxes have been declared delinquent, stating the amount of taxes due, and the penalties and costs accrued by reason of the delinquency, and requesting him to eject from said property all the tenants and occupants thereof. Upon receiving such certificate, the Mayor or any other officer authorized to enforce the law shall forthwith have all the tenants and occupants who refuse to recognize the title to the city expelled from the property in question, and to that end he may use the police force: Provided, However, That if the property so seized is or includes, a residential home, the occupant thereof shall be given a sufficient time, not exceeding ten days from the date of the notice of ejectment to vacate the premises."}},{"id":"PH-H3968-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Redemption of real property before sale.— After the title to the property shall have become vested in the city governmen"},"text":{"en":"Section 46. Redemption of real property before sale.— After the title to the property shall have become vested in the city government in the manner provided for in Section forty-two and forty-four hereof, and at any time prior to the sale or execution of the contract of sale by the city treasurer to a third party, the original owner or his legal representatives or any person having any lien, right, or legal interest or equity in said property, shall have the right to redeem the entire question by paying the full amount of taxes and penalties due thereon at the time of the seizure, and if the city treasurer shall have entered into a lease of property, the redemption shall be made subject to said lease: Provided, That the payment of the price of sale may, at the discretion of the purchaser, be made in installments, extending over a period not exceeding twelve months, but the initial payment, which must be made on the date of the filing of the application for redemption, and every subsequent payment, shall not be less than twenty-five per centum of the sum due, and shall in no case be less than two pesos, unless the total or the balance of the amount due on all seized property in the name of the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment, and the usual taxes on the property shall be payable in the year after that in which the application for redemption was approved. Any failure of the purchaser to pay any installment of the date it is due shall have the effect of a forfeiture to the city government of any partial payment made by said purchaser, and in case he has taken possession of the property, he shall forthwith surrender the same to the city government. In case the purchaser shall fail to relinquish possession of said property, the city treasurer or his deputy shall forthwith adopt measures to eject therefrom all the tenants and occupants thereof as provided for in this Act: Provided, However, That the original owner of any real estate seized prior to the approval of this Act, who redeems the same within six months subsequent to its approval, is hereby released from any obligation he may have to the Government for rent for the use of such property: Provided, finally, That the provisions of this section shall apply to redemption of real estate seized for delinquency in the payment of taxes thereon and not redeemed up to the date of the approval of this Act."}},{"id":"PH-H3968-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Notice of sale of real estate at public auction.— At any time after the forfeiture of any real estate shall have become"},"text":{"en":"Section 47. Notice of sale of real estate at public auction.— At any time after the forfeiture of any real estate shall have become absolute, the treasurer, pursuant to the rules of procedure to be promulgated by the Department Head, may announce the sale of the real estate seized on account of delinquency in the payment of taxes thereon, for the redemption of which no application has been filed. Such announcement shall be made by posting a notice for three consecutive weeks at the main entrance of the City Hall and of all the municipal buildings of the province, in either English or Spanish, and in the dialect commonly used in the locality and by publishing the same once a week during three consecutive weeks in a newspaper of general circulation in the city. Copies of such notice shall be sent immediately by registered mail to the delinquent taxpayer at the latter’s home address, if known. The notice shall state the amount of the taxes and penalties so due, the time and place of such sale, the name of the taxpayer against whom the taxes are levied, and the approximate area, the lot number and the location by district and street and the street number and district or barrio where the real estate to be sold is located."}},{"id":"PH-H3968-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Sale of real estate—Conditions.— At any time during the sale or prior thereto, the taxpayer may stay the proceedings by"},"text":{"en":"Section 48. Sale of real estate—Conditions.— At any time during the sale or prior thereto, the taxpayer may stay the proceedings by paying the taxes and penalties to the city treasurer or his deputy. Otherwise, the sale shall proceed and shall be held either at the main entrance of the City Hall or on the premises of the real estate to be sold as the city treasurer or his deputy may determine.\nThe payment of the sale price may, at the option of the purchaser, be made on installments covering a period not exceeding twelve months, but the initial payment shall be made at the time of the sale, and each subsequent payment shall not be less than twenty-five per centum of the sale price, and shall in no case be less than two pesos unless the total or balance of the amounts due on all seized property in the name of the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment, and the usual taxes on the property shall be payable in the year following that in which the sale took place. Any failure of the purchaser to pay the total price of the sale within twelve months from the date thereof, shall be sufficient ground for its cancellation, and any part payment made shall revert to the city government and if the purchaser has taken possession of the property he shall forthwith surrender the same to the city government. In case the purchaser should fail to relinquish possession of the property, the city treasurer or his deputy shall immediately take steps to eject the tenants or occupants of the property, in accordance with the procedure prescribed in Section forty-five of this Act. The city treasurer or his deputy shall make a report of the sale to the City Council within five days after the sale and shall make the same appear on its records. The purchaser at this sale shall receive from the city treasurer or his deputy a certificate showing the proceedings of the sale, describing the property sold, stating the name of the purchaser, the sale price, the condition of payment, the amount paid, and the exact amount of the taxes and penalties."}},{"id":"PH-H3968-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Redemption of real estate after sale.— Within one year from and after the date of sale, the delinquent taxpayer or any o"},"text":{"en":"Section 49. Redemption of real estate after sale.— Within one year from and after the date of sale, the delinquent taxpayer or any other person in his behalf, shall have the right to redeem the property sold by paying to the city treasurer or his deputy the amount of the taxes, penalties, costs and interest at the rate of twelve per centum per annum of the purchase price, if paid in whole, or of any portion thereof as may have been paid by the purchaser, and such payment shall invalidate the certificate of sale issued to the purchaser, if any, and shall entitle the person making such payment to a certificate to be issued by the city treasurer or his deputy, stating that he has thus redeemed the property, and the city treasurer or his deputy upon the return by the purchaser of the certificate of sale previously issued to him, shall forthwith refund to the purchaser the entire sum paid by him with interest at twelve per centum per annum, as provided for herein, and such property shall thereafter be free from the lien of such taxes and penalties."}},{"id":"PH-H3968-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Execution of deed of final sale.— In case the delinquent taxpayer shall not redeem the property sold as herein provided"},"text":{"en":"Section 50. Execution of deed of final sale.— In case the delinquent taxpayer shall not redeem the property sold as herein provided within one year from the date of the sale, and the purchaser shall then have paid the total purchase price, the city treasurer, as grantor, shall execute a deed in form and effect sufficient to convey to the purchaser so much of the real estate against which the taxes have been assessed as has been sold, free from all the liens or encumbrances of any kind whatsoever, and said deed shall succinctly recite all the proceedings upon which the validity of the sale depends. Any balance remaining from the proceeds of the sale after deducting the amount of the taxes and penalties due, and the costs, if any, shall be returned to the original owner or his representatives."}},{"id":"PH-H3968-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Taxes and penalties which shall be paid upon redemption or repurchase.— The taxes and penalties to be paid by way of red"},"text":{"en":"Section 51. Taxes and penalties which shall be paid upon redemption or repurchase.— The taxes and penalties to be paid by way of redemption or repurchase, shall comprise in all cases only the original tax by virtue of the failure to pay which the seizure was made, and its incidental penalties, up to the date of the forfeiture of the real estate to the government."}},{"id":"PH-H3968-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"Article VII Finance and Assessment Department"},"heading":{"en":"Taxes—Legal procedure.—"},"text":{"en":"Section 52. Taxes—Legal procedure.—\n(a) The assessment of a tax shall constitute a lawful indebtedness of the taxpayer to the city which may be enforced by a civil action in any court of competent jurisdiction, and this remedy shall be in addition to all remedies provided by law.\n(b) No court shall entertain any suit assailing the validity of a tax assessed under this Chapter until the taxpayer shall have paid, under protests, the taxes assessed against him, nor shall any court declare any tax invalid by reason or irregularities or informalities in the proceedings of the officers charged with the assessment or collection of the taxes or of a failure to perform their duties within the time specified for their performance, unless such irregularities, informalities, or failure shall have impaired the substantial rights of the taxpayer.\n(c) No court shall entertain any suit assailing the validity of the tax sale of land under this Chapter until the taxpayer shall have paid into the court the amount for which the land was sold, together with interest at the rate of fifteen per centum per annum upon sum from the date of sale to the time of instituting the suit. The money so paid into the court shall belong and shall be delivered to the purchaser at the tax sale, if the deed is declared invalid, and shall be returned to the depositor, should he fail in his action.\n(d) No court shall declare any such sale invalid by reason of any irregularities or informalities in the proceedings of the officers charged with the duty of making the sale, or by reason of failure by him to perform his duties within the time herein specified for their performance, unless such irregularities, informalities, or failure shall have impaired the substantial rights of the taxpayer."}},{"id":"PH-H3968-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Allotment of internal revenue and other taxes.— Of the internal revenue accruing to the National Treasury under Chapter"},"text":{"en":"Section 53. Allotment of internal revenue and other taxes.— Of the internal revenue accruing to the National Treasury under Chapter II, Title XII of Commonwealth Act Numbered Four hundred and sixty-six, and other taxes collected by the National Government and allotted to the various provinces, as well as the national aid for schools, the City of Tangub shall receive a share equal to what it would receive if it were a regularly organized province."}},{"id":"PH-H3968-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Power to levy special assessment for certain purposes.— The City Counsel may, by ordinance, provide for the levying and"},"text":{"en":"Section 54. Power to levy special assessment for certain purposes.— The City Counsel may, by ordinance, provide for the levying and collection, by special assessment of the lands comprised within the district or section of the city specially benefited, or a part not to exceed sixty per centum of the cost of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, deepening, or otherwise establishing, repairing, enlarging, or improving public avenues, roads, streets, alleys, sidewalks, parks, plazas, bridges, landing places, wharves, piers, docks, levees, reservoirs, waterworks, water mains, water courses, esteros, canals, drains, and sewers, including the cost of acquiring the necessary land and public improvements thereon, as hereinafter provided.\nIn case of national public works, the City Council as an agent of the National Government shall, when the President of the Philippines so direct it, provide for the levying and collection by special assessment of the lands within the section or district of the city specially benefited of the cost or part thereof to be determined by the President, of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, or deepening or otherwise, repairing, enlarging, or improving national roads and other national public works within the city, including the cost of acquiring the necessary land and improvements therein."}},{"id":"PH-H3968-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Property subject to special assessment.— All lands comprised within the district, or section benefited, except those own"},"text":{"en":"Section 55. Property subject to special assessment.— All lands comprised within the district, or section benefited, except those owned by the Republic of the Philippines shall be subject to the payment of the special assessment."}},{"id":"PH-H3968-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Basis of apportionment.— The amount of the special assessment shall be apportioned and computed according to the assesse"},"text":{"en":"Section 56. Basis of apportionment.— The amount of the special assessment shall be apportioned and computed according to the assessed valuations of such lands as shown in the books of the city assessor. If the property has not been declared for taxation purposes, the city assessor shall immediately declare it for the owner and assess its value, and such value shall be the basis of the apportionment and computation of the special assessment due thereon."}},{"id":"PH-H3968-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Ordinance levying special assessment.— The ordinance providing for the levying and collection of a special assessment sh"},"text":{"en":"Section 57. Ordinance levying special assessment.— The ordinance providing for the levying and collection of a special assessment shall describe with reasonable accuracy the nature, extent, and location of the work to be undertaken; the probable cost of the work; the percentage of the cost to be defrayed by special assessment; the district or section which shall be subject to the payment of the special assessment the limits whereof shall be stated by metes and bounds if practicable, and by other reasonably or accurate means if otherwise, and the period, which shall not be less than five nor more than ten years, in which said special assessment shall be payable without interest. One uniform rate per centum for all lands in the entire district or section subject to the payment of all the special assessment need not be established; but different rates for different parts or sections of the city according as said property will derive greater or less benefit from the proposed work, may be fixed. It shall be the duty of the city engineer to make the plans, specifications, and estimates of the public works contemplated to be undertaken."}},{"id":"PH-H3968-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Publication of proposed ordinance levying special assessment.— The proposed special assessment ordinance shall be publis"},"text":{"en":"Section 58. Publication of proposed ordinance levying special assessment.— The proposed special assessment ordinance shall be published, with a list of the owners of the lands affected thereby, once a week for four consecutive weeks in any newspaper published in the city, one in English, one in Spanish, and one in the local dialect if there be any, and in default of such local paper, in any newspaper of general circulation in the city. The said ordinance in English, Spanish, and the local dialect shall also be posted in places where public notices are generally posted in the city and also in the district or section where the public improvement is constructed or contemplated to be constructed.\nThe Secretary of the City Council shall, on application, furnish a copy of the proposed ordinance to each landowner affected, or his agent, and shall, if possible, send to all of them copies of said proposed ordinance by ordinary mail or otherwise."}},{"id":"PH-H3968-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Protest against special assessment.— Not later than ten days after the last publication of the ordinance and list of lan"},"text":{"en":"Section 59. Protest against special assessment.— Not later than ten days after the last publication of the ordinance and list of landowners, as provided in the preceding section, the landowners affected, if they compose of majority and represent more than one-half of the total assessed value of said lands, may file with the City Council a protest against the enactment of the ordinance. The protest shall be duly signed by them and shall set forth the addresses of the signers and the arguments in support of their objection or protest against the special assessment established in the ordinance. If no protest is filed within the time and under the condition above specified, the ordinance shall be considered approved as published."}},{"id":"PH-H3968-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Hearing of a protest.— The City Council shall designate a date and place for the hearing of the protest filed in accorda"},"text":{"en":"Section 60. Hearing of a protest.— The City Council shall designate a date and place for the hearing of the protest filed in accordance with the next preceding section and shall give reasonable time to all the protestants who have given their addresses and to all landowners affected by any protest or protests, and shall order the publication once a week, during two consecutive weeks, of a notice of the place and date of the hearing in the same manner herein provided for the publication of the proposed special assessment ordinance. All pertinent arguments and evidence presented by the landowners interested or their attorney shall be attached to the proper records. After the hearing, the City Council shall either modify its ordinance or approve it in toto and send notice of its decision to all interested parties who have given their addresses, and shall order the publication of the ordinance as approved finally together with a list of the owners of the parcels of land affected by the special assessment, three times weekly, for two consecutive weeks, in the same manner hereinabove prescribed. The ordinance finally passed by said body shall be sent to the Mayor with all the papers pertaining thereto, for his approval or veto as in the case of other city ordinances. If the Mayor approves it, the ordinance shall be published as above provided, but if he vetoes it, the procedure in similar cases provided in this Act shall be observed."}},{"id":"PH-H3968-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"When ordinance is to take effect.— Upon the expiration of thirty days from the date of the last publication of the ordin"},"text":{"en":"Section 61. When ordinance is to take effect.— Upon the expiration of thirty days from the date of the last publication of the ordinance as finally approved, the same shall be effective in all respects, if no appeal therefrom is taken to the proper authorities in the manner hereinafter prescribed."}},{"id":"PH-H3968-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Appeals.— Any time before the ordinance providing for the levying and collection of special assessment becomes effective"},"text":{"en":"Section 62. Appeals.— Any time before the ordinance providing for the levying and collection of special assessment becomes effective in accordance with the preceding section, appeals from such special assessment may be filed with the President of the Philippines, in the case of public works undertaken or contemplated to be undertaken by the National Government, and the Secretary of Finance in the case of public works undertaken or contemplated to be undertaken by the city. In all cases, the appeal shall be in writing and signed by at least a majority of the owners of the lands situated in the special assessment zone representing more than one-half of the total assessed value of the lands affected. The appellant or appellants shall immediately give the Board a written notice of appeal, and the secretary of said Board shall, within ten days after receipt of the notice of appeal, forward to the officer who has jurisdiction to decide the appeal an excerpt from the minutes of the Board relative to the proposed special assessment and all the documents in connection therewith."}},{"id":"PH-H3968-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Declaration of the Appeal.— Only appeals made within the time and in the manner prescribed in this Act shall be entertai"},"text":{"en":"Section 63. Declaration of the Appeal.— Only appeals made within the time and in the manner prescribed in this Act shall be entertained, and the officer to whom the appeal is made may call for further hearing or decide the same in accordance with its merits as shown in the papers or documents submitted to him. All appeals shall be decided within sixty days after receipt by the appellate officer of the docket of the case, and such decision shall be final."}},{"id":"PH-H3968-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Fixing of amount of special assessment.— As soon as the ordinance is in full force and effect, the city treasurer shall"},"text":{"en":"Section 64. Fixing of amount of special assessment.— As soon as the ordinance is in full force and effect, the city treasurer shall determine the amount of the special assessment which the owner of each parcel of land comprised within the zone described in the ordinance levying the same is to pay each year during the prescribed period, and shall send to each of such landowners a written notice thereof by ordinary mail. If upon completion of the public works it should appear that the actual cost thereof is smaller or greater than the estimated cost, the city treasurer shall without delay proceed to correct the assessment by increasing or decreasing, as the case may be, the amount of the unpaid annual installments which are still to be collected from each landowner affected, and, in all cases, he shall give notice of such rectifications to the parties interested."}},{"id":"PH-H3968-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Payment of special assessment.— All sums due from any landowner or owners as the result of any action taken pursuant to"},"text":{"en":"Section 65. Payment of special assessment.— All sums due from any landowner or owners as the result of any action taken pursuant to this Act shall be payable to the city treasurer in the same manner as the annual ordinary tax levied upon real property, and shall be subject to the same penalties for delinquency and be enforced by the same means as said annual ordinary tax; and all said sums together with any of said penalties shall, from the dates on which they are assessed, constitute special lien on said land, with the sole exception of the lien for the non-payment of the ordinary real property tax. If, upon recomputation of the amount of special assessment in accordance with the next preceding section, it appears that the landowner has paid more than what is correctly due from him, the amount paid in excess shall be refunded to him immediately upon demand; in the other case, the landowner shall have one year within which to pay without penalty the amount still due from him. Said period shall be counted from the date the landowner receive the proper notice."}},{"id":"PH-H3968-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"Article VIII Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Disposition of proceeds.— The proceeds of the special assessment and penalties thereon shall be applied exclusively to t"},"text":{"en":"Section 66. Disposition of proceeds.— The proceeds of the special assessment and penalties thereon shall be applied exclusively to the purpose or purposes for which the assessments were levied. It shall be the duty of the city treasurer to turn over to the National Treasury all collections made by him from special assessment levies from national public works."}},{"id":"PH-H3968-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"Article IX City Budget"},"heading":{"en":"Annual budget.— At least four months before the beginning of each fiscal year, the city treasurer shall present to the M"},"text":{"en":"Section 67. Annual budget.— At least four months before the beginning of each fiscal year, the city treasurer shall present to the Mayor a certified detailed statement by a department of all receipts and expenditures of the city pertaining to the preceding fiscal year, and to the first seven months of the current fiscal year together with an estimate of the receipts and expenditures of the remainder of the current fiscal year; and he shall submit with this statement a detailed estimate of the revenues and receipts of the city from all sources for the ensuing fiscal year. Upon the receipt of this statement and estimate and the estimates of department heads as required by Section eighteen of this Act, the Mayor shall formulate and submit to the City Council at least two and a half months before the beginning of the ensuing fiscal year, a detailed budget covering the estimated necessary expenditure for the said ensuing fiscal year, which shall be the basis of the annual appropriation ordinance: Provided, However, That in no case shall the aggregate amount of such appropriation exceed the estimate of revenues and receipts submitted by the city treasurer as provided above."}},{"id":"PH-H3968-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"Article IX City Budget"},"heading":{"en":"Supplemental budget.— Supplemental budget formulated in the same manner may be adopted when special or unforeseen circum"},"text":{"en":"Section 68. Supplemental budget.— Supplemental budget formulated in the same manner may be adopted when special or unforeseen circumstances make such action necessary."}},{"id":"PH-H3968-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"Article IX City Budget"},"heading":{"en":"Failure to enact an appropriation ordinance.— Whenever the Council fails to enact the appropriation ordinance for any fi"},"text":{"en":"Section 69. Failure to enact an appropriation ordinance.— Whenever the Council fails to enact the appropriation ordinance for any fiscal year before the end of the previous fiscal year, the several sums appropriated in the last appropriation ordinance for the objects and purposes therein specified, so far as they may be done, shall be deemed to be reappropriated for the several objects and purposes specified in said last appropriation ordinance, and shall go into effect on the first day of the new fiscal year as the appropriation ordinance for that year, until a new appropriation ordinance is duly enacted."}},{"id":"PH-H3968-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"Article X Engineering and Public Works Department"},"heading":{"en":"The City Engineer.— There shall be a City Engineer who shall have charge of the engineering and public works department."},"text":{"en":"Section 70. The City Engineer.— There shall be a City Engineer who shall have charge of the engineering and public works department. He shall receive a salary of four thousand two hundred pesos per annum, in accordance with the provisions of Republic Act Numbered Eight hundred forty. He shall have the following powers and duties:\n(a) He shall have charge of all the surveying and engineering work of the city, and shall perform such service in connection with public improvement, or any work entered upon or proposed by the city, or any department thereof, as may require the skill and experience of a civil engineer.\n(b) He shall ascertain, record, and establish monuments of the survey and from thence extend the survey of the city, and locate, establish, and survey all city and district property, and also private property abutting on the same, whenever directed by the City Mayor.\n(c) He shall prepare and submit plans, maps, specifications, and estimates for buildings, streets, bridges, docks, and other public works, and supervise the construction and repair of the same.\n(d) He shall make such tests and inspection of engineering materials used in construction and repair as may be necessary to protect the city from the use of materials of a poor or dangerous quality.\n(e) He shall have the care of all public buildings, when erected, including markets and slaughterhouses and all buildings rented for city purposes, and of any system now or hereafter established by the city for lighting of streets, public places, or public buildings.\n(f) He shall have the care of all public streets, parks and bridges, and shall maintain and regulate the use of the same for all purposes provided for by ordinance or law; shall collect and dispose of all garbage, refuse, the contents of closets, vaults and cesspools, and all other offensive and dangerous substance within the city and, in the event the disposal and collection of such garbage, refuse and other offensive substances has been awarded to a private contractor, the disposal and collection thereof shall be under the supervision of the city engineer.\n(g) He shall have the care and custody of all public docks, wharves, piers, levees, and landing places owned by the city.\n(h) He shall prevent the encroachment of private buildings and fences on the streets and public places of the city.\n(i) He shall have the general supervision and inspection of all private docks, wharves, piers, levees, and landing places, and other property bordering on the harbor, river, esteros, and waterways of the city, and shall issue permits for the construction, repair and removal of the same, and enforce all ordinances relating to the same.\n(j) He shall have the care and custody of the public systems of waterways and sewers, and all sources of water supply, and shall control, maintain, and regulate the use of the same, in accordance with the ordinance relating thereto; shall inspect and regulate the use of all private systems for supplying water to the city and his inhabitants, and all private sewers and their connections with the public sewers system.\n(k) He shall supervise the laying of mains and connections for the purpose of supplying gas to the inhabitants of the city.\n(l) He shall inspect and report upon the conditions of the public property and public works whenever required by the City Mayor or the Secretary of Public Works and Communications.\n(m) He shall supervise and regulate the location and use of engines, boilers, forges, and other manufacturing and heating appliances in accordance with law and ordinance relating thereto. He is authorized to charge fees, at rates to be fixed by the City Council, for the sanitation and transportation services and supplies furnished by his department.\n(n) He shall inspect and supervise the construction, repair, removal, and safety of private buildings, and regulate and enforce the numbering of houses in accordance with the ordinances of the city.\n(o) With the previous approval of the City Mayor in each case, he shall order the removal of buildings and structures erected in violation of the ordinances; shall order the removal of materials employed in the construction or repair of any building or structure made in violation of said ordinances; and shall cause buildings and structures dangerous to the public to be made secure or torn down.\n(p) He shall file and preserve all maps, plans, notes, surveys and other papers and documents pertaining to his office."}},{"id":"PH-H3968-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"Article X Engineering and Public Works Department"},"heading":{"en":"Execution of authorized public works and improvements.— All repair or construction of any work or public improvements, e"},"text":{"en":"Section 71. Execution of authorized public works and improvements.— All repair or construction of any work or public improvements, except parks, boulevards, streets or alleys, involving an estimated cost of three thousand pesos or more shall be awarded by the City Mayor upon the recommendation of the city engineer to the lowest responsible bidder after public advertisement by posting notices of the call for bids in conspicuous places in the City Hall and by publication in the Official Gazette, both for not less than ten days: Provided, However, That the city engineer may, with the approval of the President of the Philippines of the Philippines, upon the recommendation of the Secretary of Public Works and Communications, execute by administration any such public work costing three thousand pesos or more.\nIn case of public works involving an expenditures of less than three thousand pesos, it shall be discretionary with the city engineer either to proceed with the work himself or to let the contract to the lowest bidder after such publication and notice as shall be deemed appropriate or as may be, by regulations, prescribed."}},{"id":"PH-H3968-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"Article XI Law Department"},"heading":{"en":"The City Fiscal.— There shall be a City Fiscal who shall discharge his duties under the general supervision of the Secre"},"text":{"en":"Section 72. The City Fiscal.— There shall be a City Fiscal who shall discharge his duties under the general supervision of the Secretary of Justice. The City Fiscal shall receive a salary of four thousand two hundred pesos per annum, in accordance with the provisions of Republic Act Numbered Eight hundred and forty. The City Fiscal shall be the legal adviser of the city and all offices and departments thereof. He shall have the following powers and duties:\n(a) He shall, personally or through any assistant, represent the city in all civil cases wherein the city or any officer thereof, in his official capacity, is a party, and shall prosecute and defend all civil actions related to or connected with any office or interest.\n(b) He shall, when directed by the City Mayor, institute and prosecute in the city’s interest a suit on any bond or contract, and upon any breach and violation thereof.\n(c) He shall, when requested, attend meetings of the Council, draw ordinances, contracts, bonds, leases, and other instruments involving only interest of the city and inspect and pass upon any such instruments already drawn.\n(d) He shall give his opinion in writing, when requested by the City Mayor or the Council or any of the heads of the city departments, upon any question relating to the city or the rights, or duties of any city officer thereof.\n(e) He shall, whenever it is brought to his knowledge that any city officer or employee is guilty of neglect or misconduct in office, or that any person, firm, or corporation holding or exercising any franchise or public privilege from the city, has failed to comply with any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, investigate or cause to be investigated the same and report to the City Mayor.\n(f) He shall have charge of the prosecution of all crimes and violations of the city ordinances, in the city court of the city or the Court of First Instance and shall discharge all the duties in respect to criminal prosecution as are enjoined by law upon provincial fiscals.\n(g) The city fiscal shall cause to be investigated all charges of crimes, misdemeanors, and violations of laws and ordinances and have the necessary informations or complaints prepared or made against the accused. He or any of his assistants may conduct such investigations by taking oral evidence of reputed witnesses, and for this purpose may issue subpoena to summon witnesses to appear and testify under oath before him and subpoena duces tecum for the production of documents and other evidence. The attendance of an absent or recalcitrant witness may be enforced by application for a warrant of arrest to the municipal court or to the Court of First Instance.\n(h) The City Fiscal shall also cause to be investigated the cause of sudden deaths which have not been satisfactorily explained and when there is suspicion that the cause arose from the unlawful acts or omissions of other persons, or from foul play. For that purpose, he may cause autopsies to be made in case it is deemed necessary and shall be entitled to demand and receive for the purpose of such investigations or autopsies the aid of the city health officer.\n(i) He shall at all times render such official services as the City Mayor or the City Council may require, and shall have such powers and perform such duties as may be prescribed by law or ordinance."}},{"id":"PH-H3968-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"Article XII Health Department"},"heading":{"en":"The City Health Officer.— There shall be a City Health Officer who shall have charge of the health department and shall"},"text":{"en":"Section 73. The City Health Officer.— There shall be a City Health Officer who shall have charge of the health department and shall receive a salary of four thousand two hundred pesos per annum, in accordance with the provisions of Republic Act Numbered Eight hundred forty, one-half of which shall be paid by the National Government. He shall have the following powers and duties:\n(a) He shall have general supervision over the health and sanitary conditions of the city, including the cleaning of crematories, cemeteries, stockyards, slaughterhouses, and markets.\n(b) He shall execute and enforce all laws, ordinances and regulations relating to the public health.\n(c) He shall recommend to the City Council the passage of such ordinance as he may deem necessary for the preservation of the public health.\n(d) He shall cause to be prosecuted all violations of sanitary laws, ordinances, or regulations.\n(e) He shall make sanitary inspections and may be aided therein by such members of the police force of the city or the national police as shall be designated as sanitary police by the chief of police or proper national police officer and such sanitary inspectors as may be authorized by law.\n(f) He shall keep a civil register for the city and shall record therein all births, marriages and deaths with their respective dates.\n(g) He shall have control and supervision over puericulture centers and social services of the city.\n(h) He shall perform such other duties, not repugnant to law or ordinance, with reference to the health and sanitation of the city as the Director of Health Services shall direct. In case of epidemic or when the inhabitants of the city are menaced by any infectious or contagious diseases, the Director of Health Services shall assume full control of the health and sanitation services of the city until such condition shall have ceased to exist."}},{"id":"PH-H3968-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"Article XIII Police Department"},"heading":{"en":"The Chief of Police.— There shall be a Chief of Police who shall have charge of the police department and shall receive"},"text":{"en":"Section 74. The Chief of Police.— There shall be a Chief of Police who shall have charge of the police department and shall receive a salary of three thousand seven hundred pesos per annum, in accordance with the provisions of the Republic Act Numbered Eight hundred forty. No person shall be appointed as Chief of Police unless he is or has been a regular or reserve officer of the Armed Forces of the Philippines with a minimum rank of captain, or possessing the corresponding civil service eligibility for said position. He shall at the same time be the ex-officio Chief of Fire Department and shall have the following powers and duties:\n(a) He may issue supplementary regulations not incompatible with law or general regulations promulgated by the proper department head of the National Government, in accordance with law, for the government of the city police and detective force.\n(b) He shall quell riots, disorders, disturbances of the peace, and shall arrest and prosecute through the city fiscal, violators of law or ordinance; shall exercise exclusive police supervision over all land and water within the police jurisdiction of the city; shall be charged with the protection of the rights of persons and property whenever found within the jurisdiction of the city, and shall arrest, when necessary to prevent the escape of, offenders and violators of any law or ordinance, and all who obstruct or interfere with him in the discharge of his duty; shall have charge of the city prison; and shall be responsible for the safekeeping of all prisoners until they shall be released from custody, in accordance with law, or delivered to the warden of the proper prison or penitentiary.\n(c) He may take good and sufficient bail for the appearance before the judge of the city court of any person arrested for violation of any city ordinance: Provided, However, That he shall not exercise this power in cases of violations of any penal law, except when the fiscal of the city shall so recommend and fix the bail to be required of the person arrested.\n(d) He shall have authority, within the police limits of the city, to serve and execute criminal processes of any court.\n(e) He shall be the deputy sheriff of the city, and as such he shall, personally or by representative, attend the sessions of the city court, and shall execute promptly and faithfully, all writs and processes of said court.\n(f) He shall exercise supervision over the police training school established in accordance with the rules and regulations of the police department.\n(g) He shall have such further powers and perform such further duties as may be prescribed by law or ordinance."}},{"id":"PH-H3968-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"Article XIII Police Department"},"heading":{"en":"Secret service.— The Chief of Police shall be ex-officio chief of the secret service. He shall take charge of the detect"},"text":{"en":"Section 75. Secret service.— The Chief of Police shall be ex-officio chief of the secret service. He shall take charge of the detective work of the department and of the detective force of the city, and shall perform such other duties as may be assigned to him by law or ordinance."}},{"id":"PH-H3968-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"Article XIII Police Department"},"heading":{"en":"Peace officers—Their powers and duties.— The City Mayor, The Chief of Police, and all officers and members of the city p"},"text":{"en":"Section 76. Peace officers—Their powers and duties.— The City Mayor, The Chief of Police, and all officers and members of the city police and detective force shall be the peace officers of the City. Such peace officers are authorized to serve and execute all processes of the city court and criminal processes of all other courts to whomsoever directed within the jurisdictional limits of the city or within the police limits as hereinbefore defined; within the same territory, to pursue and arrest, without warrant, any person found in suspicious places or under suspicious circumstances reasonably tending to show that such person has committed, or is about to commit, a crime or breach of the peace; to arrest or cause to be arrested, without warrant, any offender when the offense is committed in the presence of a peace officer or within his view; and, in such pursuit or arrest, to enter any building, ship, boat, or vessel or take into custody any person therein suspected of being concerned in such crime or breach of the peace, and any property suspected or having been stolen; and to exercise such other powers and perform such other duties as may be prescribed by any law or ordinance. They shall detain an arrested person only in accordance with the provisions of existing laws relative to such detention. Whenever the City Mayor shall deem it necessary to avert danger or to protect life and property, in case of riot, disturbance, or public calamity, or when he has reason to fear any serious violation of law and order, he may call upon the provincial commander or other members of the Armed Forces of the Philippines. Except upon the occurrence of any such conditions, police jurisdiction and supervision and the preservation of peace and order shall pertain exclusively to the peace officers herein mentioned, existing law to the contrary notwithstanding."}},{"id":"PH-H3968-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"Article XIII Police Department"},"heading":{"en":"Powers and duties of the Chief of Police in his capacity as ex-officio chief of fire department.— The Chief of Police, i"},"text":{"en":"Section 77. Powers and duties of the Chief of Police in his capacity as ex-officio chief of fire department.— The Chief of Police, in his capacity as ex-officio chief of the fire department shall have the following powers and duties:\n(a) He shall issue supplementary regulations not incompatible with law or general regulations issued by the proper department head of the National Government in accordance with law, for the governance of the fire force.\n(b) He shall have charge of the fire-engine houses, the fire engines, hose trucks, hooks and ladders, trucks and other fire apparatus.\n(c) He shall have the full police powers in the vicinity of the fires.\n(d) He shall have authority to remove or demolish any building or other property whenever it shall become necessary to prevent the spreading of fire or to protect adjacent property.\n(e) He shall investigate and report to the City Mayor upon the origin and cause of all fires occurring within the city.\n(f) He shall inspect all buildings erected or under construction or repair within the city, and determine whether they provide sufficient protection against fire and comply with the ordinances relating thereto.\n(g) He shall have charge of the city telegraph, telephone, and fire alarm service.\n(h) He shall have exclusive power, notwithstanding any provision of law to the contrary, to supervise and regulate the stringing, grounding, and installation of wires for all electrical connections with a view to avoiding conflagrations, interference with public traffic or safety or the necessary operation of the fire department.\n(i) He shall condemn all defective electrical installations, and shall take the necessary steps to effect immediate corrective actions, informing the City Mayor of the action thus taken.\n(j) He shall supervise the manufacture, storage, and use of petroleum, gas, acetylene, gunpowder, and other highly combustible matter and explosives.\n(k) No permit for the construction or repair of buildings within the city shall be granted unless the plans relative thereto have been approved by the chief of the fire department. He shall have the power to alter or disapprove such plans as do not provide for adequate protection against the occurrence of fires.\n(l) He shall have such powers and perform such duties as may further be prescribed by law or ordinance."}},{"id":"PH-H3968-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Regular auxiliary and acting judges of city courts.— There shall be a city court for the City of Tangub for which there"},"text":{"en":"Section 78. Regular auxiliary and acting judges of city courts.— There shall be a city court for the City of Tangub for which there shall be appointed a city judge and an auxiliary city judge.\nThe city judge may, upon proper applications, be allowed a vacation of not more than thirty days every year with salary. The auxiliary city judge shall discharge the duties of the city judge in case of absence, incapacity or inability of the latter until he assumes his post, or until a new judge shall have been appointed. During his incumbency, the auxiliary city judge shall enjoy the powers, emoluments and privileges of the city judge who shall not receive any remuneration therefor except the salary to which he is entitled by reason of his vacation provided for in this Act.\nIn case of absence, incapacity or inability of both the city judge and the auxiliary city judge, the Secretary of Justice shall designate the municipal judge of any of the adjoining municipalities to preside over the city court, and he shall hold office temporarily until the regular incumbent or the auxiliary judge thereof shall have summoned office or until another judge shall have been appointed in accordance with the provisions of this Act. The municipal judge so designated shall receive his salary as municipal judge plus seventy per cent of the salary of the city judge whose office he has temporarily assumed.\nThe city judge shall receive a salary of not exceeding five thousand four hundred pesos per annum to be paid by the National Government."}},{"id":"PH-H3968-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"The clerk and employees of the city court.— There shall be a clerk of the city court who shall be appointed by the city"},"text":{"en":"Section 79. The clerk and employees of the city court.— There shall be a clerk of the city court who shall be appointed by the city judge in accordance with Civil Service Law, rules and regulations, and who shall receive a compensation to be fixed by ordinance, approved by the Secretary of Justice at not exceeding one thousand eight hundred pesos per annum. He shall keep the seal of the court and fix it to all orders, judgments, certificates, records, and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with the judgment. He shall have the power to administer oaths."}},{"id":"PH-H3968-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Jurisdiction of city court.— The city court shall have the same jurisdiction in civil and criminal cases and the same in"},"text":{"en":"Section 80. Jurisdiction of city court.— The city court shall have the same jurisdiction in civil and criminal cases and the same incidental powers as are at present conferred upon them by law. It shall have concurrent jurisdiction with the Court of First Instance over all criminal cases arising under the laws relating to gambling and management of lotteries, to assaults where the intent to kill is not charged or evident upon the trial, to larceny, embezzlement and estafa where the amount of money or property stolen, embezzled or otherwise involved, does not exceed the sum or value of two hundred pesos, to the sale of intoxicating liquors, to falsely impersonating an officer, to malicious mischief, to trespass on Government or private property, and to threatening to take human life. It may also conduct a preliminary investigation for any offense, without regard to the limits of punishment, and may release, or commit and bind over any person charged with such offense to secure his appearance before the proper court."}},{"id":"PH-H3968-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Incidental powers of city court.— The city court shall have the power to administer oaths and to give certificates there"},"text":{"en":"Section 81. Incidental powers of city court.— The city court shall have the power to administer oaths and to give certificates thereof; to issue summonses, writs, warrants, executions, and all other processes necessary to enforce its orders and judgments, to compel the attendance of witnesses; to punish contempt of court by fine or imprisonment, or both, within the limitations imposed by law; and to require of any person arrested a bond for good behavior or to keep the peace, or for the further appearance of such person before a court of competent jurisdiction. But no such bond shall be accepted unless it be executed by the person in whose behalf it is made with sufficient surety or sureties to be approved by said court."}},{"id":"PH-H3968-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Procedure in city court in prosecution for violations of law and ordinances.— In a prosecution for the violation of any"},"text":{"en":"Section 82. Procedure in city court in prosecution for violations of law and ordinances.— In a prosecution for the violation of any ordinance, the first process shall be a summons; except that a warrant for the arrest of the offender may be issued in the first instance upon the affidavit of any person that such ordinance has been violated, and that the person making the complaint has reasonable grounds to believe that the party charged is guilty thereof, which warrant shall conclude: \"Against the ordinances of the city in such cases made and provided.\" All proceedings and prosecution for offenses against the laws of the Philippines shall conform to the rules relating to process, pleadings, practice, and procedure for the judiciary of the Philippines, and such rules shall govern the city court and its officers in all cases insofar as the same may be applicable."}},{"id":"PH-H3968-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Costs, fees, fines and forfeitures in city court.— There shall be taxed against and collected from the defendant, in cas"},"text":{"en":"Section 83. Costs, fees, fines and forfeitures in city court.— There shall be taxed against and collected from the defendant, in case of his conviction in the city court, such costs and fees as may be prescribed by law in criminal cases in municipal courts. All costs, fees, fines and forfeitures shall be collected by the clerk of the court, who shall keep a docket of those imposed and of those collected, and shall pay collections of the same to the city treasurer, for the benefit of the city, on the next business day after the same are collected, and take receipts therefor. The city judge shall examine said docket each day, compare the same with the amount receipted for by the city treasurer and satisfy himself that all such costs, fees, fines, and forfeitures have been duly accounted for."}},{"id":"PH-H3968-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"No person sentenced by city court to be confined without commitment.— No person shall be confined in prison by sentence"},"text":{"en":"Section 84. No person sentenced by city court to be confined without commitment.— No person shall be confined in prison by sentence of the city court until the warden or officer in charge of the prison shall receive a written commitment showing the offense for which the prisoner was tried, the date of the trial, the exact terms of the judgment or sentence, and the date of the order of the commitment. The clerk shall, under seal of the court, issue such a commitment in each case of sentence to imprisonment."}},{"id":"PH-H3968-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"Article XIV The City Court"},"heading":{"en":"Procedure on appeal from city court to Court of First Instance.— An appeal shall lie to the Court of First Instance in a"},"text":{"en":"Section 85. Procedure on appeal from city court to Court of First Instance.— An appeal shall lie to the Court of First Instance in all cases where fine or imprisonment, or both, is imposed by the city court. The party desiring to appeal shall, before six o’clock post meridian of the fifteenth day after the rendition and entry of the judgment by the city court, file with the clerk of court a written statement that he appeals to the Court of First Instance. The filing of such statement shall perfect the appeal. The judge of the court from whose decision appeal is taken shall, within five days after the appeal is taken, transmit to the clerk of the Court of First Instance a certified copy of the record of proceedings and all the original papers and processes in the case. A perfected appeal shall operate to vacate the judgment of the city court, and the action, when duly entered in the Court of First Instance, shall stand for trial de novo upon its merits as though the same has never been tried. Pending an appeal, the defendant shall remain in custody unless released in the discretion of the judge of the city court or of the judge of the Court of First Instance, upon sufficient bail in accordance with the procedure in force, to await the judgment of the appellate court.\nAppeals in civil cases shall be governed by the ordinary procedure established by law."}},{"id":"PH-H3968-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"Article XV Transitory Provisions"},"heading":{"en":"Change of status.— The city government provided for in this Charter shall be organized upon the approval of this Act. Th"},"text":{"en":"Section 86. Change of status.— The city government provided for in this Charter shall be organized upon the approval of this Act. The incumbent municipal mayor, vice-mayor, and the members of the municipal council of the Municipality of Tangub shall continue in office until the expiration of their present term of office."}},{"id":"PH-H3968-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"Article XV Transitory Provisions"},"heading":{"en":"Participation in election of provincial officials.— The qualified voters of the City of Tangub shall be qualified and be"},"text":{"en":"Section 87. Participation in election of provincial officials.— The qualified voters of the City of Tangub shall be qualified and be entitled to vote in the election of Provincial Governor, Provincial Vice-Governor, and Members of the Provincial Board of the Province of Misamis Occidental."}},{"id":"PH-H3968-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"Article XV Transitory Provisions"},"heading":{"en":"Congressional District.— Until otherwise provided by law, the City of Tangub shall continue as part of the lone congress"},"text":{"en":"Section 88. Congressional District.— Until otherwise provided by law, the City of Tangub shall continue as part of the lone congressional district of the Province of Misamis Occidental."}},{"id":"PH-H3968-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"Article XV Transitory Provisions"},"heading":{"en":"Repealing clause.— All Acts, executive orders, administrative orders and proclamations of parts thereof inconsistent wit"},"text":{"en":"Section 89. Repealing clause.— All Acts, executive orders, administrative orders and proclamations of parts thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H3968-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"Article XV Transitory Provisions"},"heading":{"en":"Effectivity.— This Act shall take effect upon its approval."},"text":{"en":"Section 90. Effectivity.— This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra1967/ra_5131_1967.html 重抓，90 → 90 条"};
  FT["PH-H3969"] = {"id":"PH-H3969","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5132_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为奎松省增设两名助理省检察官职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Providing Two Additional Positions for Assistant Provincial Fiscals for the Province of Quezon, Amending for the Purpose of Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Providing Two Additional Positions for Assistant Provincial Fiscals for the Province of Quezon, Amending for the Purpose of Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5132","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5132_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3969-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Quezon, is further amended to read as follows:\n\"Quezon, nine assistant provincial fiscals.\""}},{"id":"PH-H3969-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Two Additional Positions for Assistant Provincial Fiscals for the Province of Quezon, Amending for the Purpose of Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3970"] = {"id":"PH-H3970","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5167_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对《公司法》的修改","en":"Corporation Law","orig":"An Act to Amend Act Numbered Fourteen Hundred Fifty-Nine, Otherwise Known as the \"Corporation Law\" by Amending Subparagraph Five and Adding a New Subparagraph Five-A, Therein","vi":"Luật Công ty","th":"กฎหมายบริษัท","id":"Undang-Undang Perseroan","ms":"Undang-Undang Syarikat"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5167","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5167_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3970-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraph five, Section thirteen of Act Numbered Fourteen hundred fifty-nine, as amended, is further amended to read as follows:\n\"(5) To purchase, hold, convey, sell, lease, let, mortgage, encumber, and otherwise deal with such real and personal property as the purposes for which the corporation was formed may permit, and the transaction of the lawful business of the corporation may reasonably and necessarily require unless otherwise prescribed in this Act: Provided, That no corporation shall be authorized to conduct the business of buying and selling public lands or be permitted to hold or own real estate except such as may be reasonably necessary to enable it to carry out the purposes for which it is created, and every corporation authorized to engage in agriculture shall be restricted to the ownership and control of not to exceed one thousand and twenty-four hectares of land; and it shall be unlawful for any corporation organized for the purpose of engaging in agriculture to be in anywise interested in any other corporation organized for the purpose of engaging in agriculture; it shall be unlawful for any person owning stock in more than one corporation organized for the purpose of engaging in agriculture to own more than fifteen per centum of the capital stock then outstanding and entitled to vote of each of such corporations; it shall be unlawful for any corporation to own in excess of fifteen per centum of the capital stock then outstanding and entitled to vote of any corporation organized for the purpose of engaging in agriculture; any stockholder of more than one corporation organized for the purpose of engaging in agriculture may hold his stock in such corporations solely for investment and not for the purpose of bringing about or attempting to bring about a combination to exercise control of such corporations, or to directly or indirectly violate any of the provisions of the Public Land Law, and any corporation holding stock in any corporation organized for the purpose of engaging in agriculture may hold such stock solely for investment, and not for the purpose of bringing about or attempting to bring about a combination to effect control of such corporation, or to directly or indirectly violate any of the provisions of the Public Land Law. Corporations, however, may loan funds upon real estate security and purchase real estate when necessary for the collection of loans but they shall dispose of real estate so obtained within five years after receiving the title.\""}},{"id":"PH-H3970-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subparagraph five Section thirteen of Act Numbered Fourteen hundred fifty-nine, as amended, is hereby further amended by adding a new subparagraph 5-A to read as follows:\n\"(5-A) Any domestic or foreign corporation, and its stockholders organized for the purpose of engaging in mining may acquire and hold not more than forty per centum of the capital stock then outstanding and entitled to vote of only one other corporation organized for the purpose of engaging in mining in the Philippines: Provided, That it shall likewise be unlawful for said latter corporation to be in any wise interested in any other corporation organized for the purpose of engaging in mining: Provided, further, That the acquisition of up to forty per centum of the outstanding capital stock in a mining corporation already in commercial production shall be as follows: not more than fifteen per centum of the outstanding capital stock and twenty-five per centum through subscription to unissued shares.\n\"Any domestic or foreign corporation organized for any purpose other than mining may acquire and hold not more than thirty per centum of the capital stock then outstanding and entitled to vote of each of not more than three corporations organized for the purpose of engaging in mining in the Philippines: Provided, That it shall be unlawful for any stockholder of such corporation organized for any purpose other than mining to be a stockholder of any of the said three corporations organized for the purpose of engaging in mining. It shall be unlawful for any person owning a stock in more than one corporation organized for the purpose of engaging in mining to own more than fifteen per centum, of the capital stock then outstanding and entitled to vote of each corporation. Any stockholder of more than one corporation organized for the purpose of engaging in mining may hold his stock in such corporation solely for investment and not for the purpose of bringing about or attempting to bring about a combination to exercise control of such corporation, or to directly or indirectly violate any of the provisions of the mining and the public land laws. Any corporation holding stock in any corporation organized for the purpose of engaging in mining may hold such stock solely for investment, and not for the purpose of bringing about or attempting to bring about a combination to exercise control of such corporation, or directly or indirectly violate any of the provisions of the mining and public land laws. Any corporation not engaged in mining, who before the approval of this amendatory Act had investments of not more than fifteen per centum in each of more than three mining corporations shall be allowed to keep such holding.\""}},{"id":"PH-H3970-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56"};
  FT["PH-H3971"] = {"id":"PH-H3971","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5168_1967.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"统一公立学校教师薪金并授权为此拨款的法案","en":"An Act to Standardize the Salaries of Public School Teachers and Authorizing the Appropriation of Funds Therefor","orig":"An Act to Standardize the Salaries of Public School Teachers and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5168","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5168_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3971-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the \"Public School Teachers Salary Standardization Act of 1967.\""}},{"id":"PH-H3971-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The term \"public school teachers\" as used in this Act and as herein otherwise provided, shall be limited to persons actually engaged in classroom teaching and those performing administrative and/or supervisory functions over particular phases of instruction or subject areas, or of particular schools or districts in the Bureau of Public Schools and the Bureau of Vocational Education.\nThe term \"public school teachers\" shall likewise include officials and employees in the Bureau of Private Schools performing supervisory functions over schools or over particular phases of instruction or subject areas whose salaries are paid from national funds."}},{"id":"PH-H3971-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The minimum to maximum rates of compensation of officials and employees covered under this Act are hereby fixed in accordance with schedule \"B\" hereto attached as an integral part of this Act."}},{"id":"PH-H3971-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Salary Schedule. — The position classification and the corresponding salary ranges are fixed as follows:\nGroup I\nGeneral Education Supervisor III\nRange 56 - ₱9,288 (min.)–₱11,328 (max.) General Secondary School Principal III Group II Division Academic Supervisor Range 54 - ₱8,400 (min.)–₱10,260 (max.) General Education Supervisor II Curriculum Coordinator II Vocational Education Supervisor Community Adult Education Supervisor II Private Schools Vocational Education Supervisor Private Schools Curriculum Coordinator II School of Arts and Trades Department Head (college) Agriculture School Department Head (college) Fisheries School Department Head (college) Supervisor of Student Teaching Home Industries Training Supervisor Trade School Principal III Group III Dean of Students I Range 53 - ₱7992 (min.)–₱9,756 (max.) Group IV General Education Supervisor I Range 51 - ₱7,236 (min.)–₱8,832 (max.) Grade Supervisor Community And Adult Education Supervisor I General Secondary Principal II Special School Principal Vocational Placement Coordinator Curriculum Coordinator I Private Schools Area Supervisor Private Schools Curriculum Coordinator I Test Constructor Educational Researcher Supervising Librarian Senior Librarian Private Schools Supervising Librarian I Teacher Credentials Evaluator Fisheries School Principal II Secondary Agricultural School Principal II Trade School Principal II Vocational Instruction Supervisor II-3 Group V Public School District Supervisor Range 50 - ₱6,888 (min.)–₱8,400 (max.) Instructor III Vocational Instruction Supervisor III-2 College Librarian 3 Group VI General Secondary Principal I Range 49 - ₱6,552 (min.)–₱7,992 (max.) Secondary Agriculture Principal I Fisheries Secondary Principal I Trade School Principal I Secondary School Head Teacher III-4 Elementary School Principal III Assistant Supervisor of Student Teaching Assistant General Secondary Principal II Vocational Instruction Supervisor II-1 Group VII Instructor II Range 48 - ₱6,240 (min.)–₱7,608 (max.) Assistant General Secondary Principal I College Librarian 2 Secondary School Head Teacher III-3 Group VIII Elementary School Principal II Range 47 - ₱5,928 (min.)–₱7,236 (max.) Assistant Special School Principal Supervising Home Economics Demonstrator Assistant Curriculum Coordinator Secondary School Head Teacher II-5 Junior College Instructor 5 Crafts Demonstrator II Secondary School Head Teacher III-2 Group IX Instructor I Range 45 - ₱5,376 (min.)–₱6,552 (max.) Secondary School Head Teacher II-4 Junior College Instructor 4 College Librarian I Group X Elementary School Principal I Range 44 - ₱5,112 (min.)–₱6,240 (max.) Secondary School Head Teacher II-3 Junior College Instructor 3 Secondary School Head Teacher I-5 Special Education Teacher 5 Guidance Coordinator 5 Elementary School Head Teacher 5 School Farming Coordinator 5 Secondary School Head Teacher III-1 Group XI Assistant Instructor Range 42 - ₱4,632 (min.)–₱5,640 (max.) Secondary School Department Head I Special Education Teacher 4 Guidance Coordinator 4 Secondary School Head Teacher I-4 Elementary School Head Teacher 4 School Farming Coordinator 4 Group XII Secondary School Teacher 5 Range 41 - ₱4,404 (min.)–₱5,376 (max.) Elementary Grades Teacher 5 Special Education Teacher 3 Guidance Coordinator 3 Elementary School Head Teacher 3 School Librarian 5 Guidance Counselor 5 Kindergarten Teacher 5 Secondary School Head Teacher II-2 Junior College Instructor 2 Secondary School Head Teacher I-3 School Farming Coordinator 3 Group XIII Secondary School Teacher 4 Range 40 - ₱4,188 (min.)–₱5,112 (max.) Elementary Grades Teacher 4 School Librarian 4 Guidance Counselor 4 Kindergarten Teacher 4 Group XIV Secondary School Teacher 3 Range 38 - ₱3,792 (min.)–₱4,632 (max.) Elementary Grades Teacher 3 Special Education Teacher 2 Guidance Coordinator 2 Elementary School Head Teacher 2 Secondary School Head Teacher I-2 School Librarian 3 Guidance Counselor 3 Kindergarten Teacher 3 School Farming Coordinator 2 Crafts Demonstrator I Group XV Secondary School Head Teacher II-1 Range 37 - ₱3,612 (min.)–₱4,404 (max.) Junior College Instructor I Group XVI Secondary School Teacher 2 Range 36 - ₱3,432 (min.)–₱4,188 (max.) Elementary Grades Teacher 2 School Librarian 2 Guidance Counselor 2 Kindergarten Teacher 2 Group XVII Special Education Teacher I Range 35 - ₱3,264 (min.)–₱3,984 (max.) Guidance Coordinator I Elementary School Head Teacher I Secondary School Head Teacher I-1 School Farming Coordinator Group XVIII Secondary School Teacher 1 Range 32 - ₱2,808 (min.)–₱3,432 (max.) Elementary Grades Teacher 1 School Librarian 1 Guidance Counselor 1 Kindergarten Teacher 1"}},{"id":"PH-H3971-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Salary Adjustment to the Minimum Rates. — The salary adjustment from existing rates to the minimum as provided under this new salary schedule shall cover a period of five years, starting with the existing minimum rate of the range of the position to the minimum rate under the new schedule as indicated in Schedule \"A\" hereto attached and made a portion of this Act: Provided, That the length of the period or the number of years for any official or employee to reach the minimum as herein provided will depend on the step to which his existing salary may properly be classified: Provided, further, That should the existing salary rate be between authorized rates in the five-year pre-minimum schedule, the same shall be adjusted to the rate of the proper step without the official or employee suffering a reduction in salary thereby."}},{"id":"PH-H3971-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Salary Progression from Minimum to Maximum. — The salary progression from minimum to maximum shall consist of four steps, each succeeding step to be granted automatically after three years of service: Provided, That the progression from minimum to the maximum of the salary scale shall not extend beyond a period of ten years subject to the provisions of Section 8 of this Act."}},{"id":"PH-H3971-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"New Appointments. — The rate of salary of new appointees and those promoted to new positions shall not be lower than the rates fixed for officials and employees holding such positions on the date of effectivity of this Act."}},{"id":"PH-H3971-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceleration of Automatic Increases. — The three-year period required for automatic increase in salary from one step to the next as provided in Section six of this Act may, upon the approval of the Secretary of Education, be accelerated to no sooner than two years in favor of deserving officials and employees in recognition of outstanding services in accordance with such rules as the Secretary of Education may prescribe."}},{"id":"PH-H3971-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All incumbent officials and employees covered by this Act shall be entitled to salary adjustments as herein provided without the necessity of a new appointment. Special orders relative to salary adjustments under this Act shall, however, be furnished to all offices concerned by the Secretary of Education."}},{"id":"PH-H3971-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The rate of salary of any official or employee occupying an existing position or one which may be created after the approval of this Act which is not included or specified in Section four of this Act shall be determined by the Secretary of Education upon the recommendation of the respective Bureau head concerned as to the proper classification, of such positions in accordance with the WAPCO classification and pay plan."}},{"id":"PH-H3971-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Appropriation. — There is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of Twenty Million Pesos (₱20,000,000.00) annually for five consecutive fiscal years, starting with the fiscal year 1969-1970, to effect the initial adjustment of salaries of all officials and employees covered by this Act to the minimum rates as herein provided: Provided, That to cover any deficiency in the annual national appropriations for said purpose, there shall be set aside from the aggregate savings of the Bureaus concerned the sum of not less than Five Million Pesos (₱5,000,000.00) annually for the corresponding five-year period."}},{"id":"PH-H3971-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"To provide funds for the implementation of the ten year program of salary progression from the minimum to maximum rates as provided in Section six hereof, there shall be appropriated in the annual General Appropriations Act the sum of Five Million Pesos (₱5,000,000.00) annually, for ten consecutive fiscal years, starting with the fiscal year immediately following the full adjustment of salaries to the minimum rates, which shall be used exclusively to meet the automatic step increases in salary from minimum to maximum during the ten-year period as provided herein: Provided, That any deficiency in said fund during the ten-year period of implementation of the progression from minimum to maximum as herein provided, shall be covered from the aggregate savings of the bureaus concerned."}},{"id":"PH-H3971-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All Acts or parts of Acts contrary to or inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H3971-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nSchedule A\nSalary Adjustment"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Standardize the Salaries of Public School Teachers and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3972"] = {"id":"PH-H3972","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5169_1967.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾总统出售政府财产以筹资支付政府对菲律宾土地银行的认购款并资助农业信贷署","en":"An Act Empowering the President of the Philippines to Sell Government Properties for the Purpose of Raising Funds to Pay for the Government's Subscription to the Land Bank of the Philippines and to Finance the Agricultural Credit Administration","orig":"An Act Empowering the President of the Philippines to Sell Government Properties for the Purpose of Raising Funds to Pay for the Government's Subscription to the Land Bank of the Philippines and to Finance the Agricultural Credit Administration"},"level":"law","status":"active","topics":["tax","environment"],"docNumber":"Republic Act No. 5169","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5169_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3972-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"For the purpose of raising funds to pay for the Government’s subscription to the Land Bank of the Philippines and to finance the Agricultural Credit Administration, the President of the Philippines, without prejudice to private rights previously acquired, is hereby empowered to sell in accordance with this Act, the properties of the National Government enumerated in Schedule \"A\"."}},{"id":"PH-H3972-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any sale that may be made pursuant to this Act shall be conducted through public bidding: Provided, That the appraised market value of the property shall be stated in the invitation to bid and no bid below the same shall be accepted: Provided, further, That the details of the procedure in public bidding shall be formulated and carried out by a Committee created for the purpose which shall be composed of the Secretary of Finance, as Chairman, the Auditor General, the Secretary of General Services, the Chairman of the National Land Reform Council and a representative of the minority party receiving the second largest number of votes in the last Presidential election who shall be appointed by the President exclusively from a list of three recommendees of such minority party: Provided, further, That the Committee shall not be considered fully constituted and ready to function until after the member representing the minority party has been appointed and has qualified: Provided, furthermore, That the minority part shall submit its recommendation to the President within sixty days from the approval of this Act, or from the last Presidential election, as the case may be, in the absence of which the committee shall be deemed to be so constituted even without such member from the minority party: Provided, furthermore, that the minority representative shall receive a per diem of fifty pesos for each day he attends a meeting of the committee: Provided, furthermore, That any contract, deed or instrument disposing such properties of the government executed by the Committee, thru its chairman before it becomes valid and binding must first be approved by the President: Provided, furthermore, That in the disposition of lands, no bid shall be entertained, except from individuals, corporations or associations qualified under existing laws to acquire or hold lands of the public domain in the Philippines: and Provided, finally, That no bid shall be entertained from the Central Bank of the Philippines."}},{"id":"PH-H3972-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The appraised market value of the real property to be sold thru public bidding shall be determined by a Board, consisting of three real property appraisers to be constituted by the Committee created under Section two hereof from a list of recommendees submitted by the Philippine Association of Real Estate Appraisers."}},{"id":"PH-H3972-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Seventy-five per centum of the proceeds accruing from the sale of government properties pursuant to this Act shall be delivered to the Land Bank and credited as government subscription to the capital of said Bank pursuant to Section eighty-one, Republic Act Numbered Three thousand eight hundred forty-four, otherwise known as the \"Agricultural Land Reform Code\". The balance of twenty-five per centum shall be delivered to the Agricultural Credit Administration to carry out the loaning activities of said Administration under Chapter V of Republic Act Numbered thirty-eight hundred forty-four."}},{"id":"PH-H3972-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"It shall be the duty of the President to report to Congress, from time to time, the details of sales consummated in accordance with the provisions of this Act."}},{"id":"PH-H3972-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Empowering the President of the Philippines to Sell Government Properties for the Purpose of Raising Funds to Pay for the Government's Subscription to the Land Bank of the Philippines and to Finance the Agricultural Credit Administration","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3973"] = {"id":"PH-H3973","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5170_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Sixty-Seven to June Thirtieth, Nineteen Hundred and Sixty-Eight and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Sixty-Seven to June Thirtieth, Nineteen Hundred and Sixty-Eight and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5170","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5170_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3973-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of funds. — The following sums or so much thereof as may be necessary, are appropriated out of any funds in the Philippine Treasury not otherwise appropriated for the operation of the government of the Republic of the Philippines during the period from July first, nineteen hundred and sixty-seven to June thirtieth, nineteen hundred and sixty-eight except where otherwise specifically provided:"}},{"id":"PH-H3973-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Effective date. — This Act shall take effect on July first, nineteen hundred and sixty-seven, unless otherwise provided.\nApproved: August 4, 1967."}}],"pack":"ph-p56"};
  FT["PH-H3974"] = {"id":"PH-H3974","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5171_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"便利外国国籍国际贸易商与投资者入境菲律宾，为此修订第613号联邦法（即1940年菲律宾移民法，经第503号共和国法修正）第9条第（d）项","en":"An Act to Facilitate the Entry into the Philippines of International Traders and Investors of Foreign Nationality, Amending for the Purpose Subparagraph (d) of Section Nine of Commonwealth Act Numbered Six Hundred Thirteen, Otherwise Known as the Philippine Immigration Act of 1940, as Amended by Republic Act Numbered Five Hundred and Three","orig":"An Act to Facilitate the Entry into the Philippines of International Traders and Investors of Foreign Nationality, Amending for the Purpose Subparagraph (d) of Section Nine of Commonwealth Act Numbered Six Hundred Thirteen, Otherwise Known as the Philippine Immigration Act of 1940, as Amended by Republic Act Numbered Five Hundred and Three"},"level":"law","status":"active","topics":["investment","administrative"],"docNumber":"Republic Act No. 5171","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5171_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3974-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraph (d) of the first paragraph of Section nine of Commonwealth Act Numbered Six hundred thirteen, otherwise known as the Philippine Immigration Act of 1940, as amended, is hereby further amended so as to read as follows:\n\"(d) An alien entitled to enter the Philippines under and in pursuance of the provisions of a treaty of commerce and navigation (1) solely to carry on substantial trade principally between the Philippines and the foreign state of which he is a national or (2) solely to develop and direct the operations of an enterprise in which, in accordance with the Constitution and the laws of the Philippines he has invested or of an enterprise in which he is actively in the process of investing, a substantial amount of capital; and his wife, and his unmarried children under twenty-one years of age, if accompanying or following to join him, subject to the condition that citizens of the Philippines are accorded like privileges in the foreign state of which such alien is a national.\""}},{"id":"PH-H3974-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The provisions of Republic Act Numbered One thousand three hundred and ninety-three and other laws, part of laws or rules and regulations inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H3974-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Facilitate the Entry into the Philippines of International Traders and Investors of Foreign Nationality, Amending for the Purpose Subparagraph (d) of Section Nine of Commonwealth Act Numbered Six Hundred Thirteen, Otherwise Known as the Philippine Immigration Act of 1940, as Amended by Republic Act Numbered Five Hundred and Three","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3975"] = {"id":"PH-H3975","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5172_1967.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予天主教福利组织在菲律宾建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the Catholic Welfare Organization a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Catholic Welfare Organization a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","vi":"Đạo luật cấp quyền khai thác cho Catholic Welfare Organization để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Catholic Welfare Organization เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Catholic Welfare Organization untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Catholic Welfare Organization untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5172","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5172_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3975-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, the Catholic Welfare Organization is hereby granted a franchise, which shall continue in force during the time that the Government has not established similar service at the places selected by the grantee, but not exceeding twenty-five years, to construct, maintain and operate, for religious, educational, cultural and commercial purposes and in the public interest, radio broadcasting and television stations in the Philippines: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station or one television station be begun within two years from the date of approval of this Act, and be completed within four years form said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting and television stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H3975-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provision of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable, to the television stations referred to in Section one."}},{"id":"PH-H3975-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"As a condition to the granting of this franchise the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations during the first three years of the life of this franchise. If, after four years from the date of approval of this franchise, the grantee shall have fulfilled said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H3975-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H3975-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said individual, partnership or corporation."}},{"id":"PH-H3975-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"(a) Unless exempted there from, the grantee shall be liable for taxes on its real estate, buildings and personal property, used in the operation of its radio broadcasting and television stations, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. (b) The grantee shall pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3975-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H3975-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3975-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3975-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, or other national emergency, when public safety requires, to cause the closing of said stations or to authorize the use and operation thereof by any department of the Government without compensation to the grantee for the use of said stations during continuance of the national emergency."}},{"id":"PH-H3975-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral. Willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H3975-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, sell or assign this franchise or the rights and privileges acquired there under, to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned, shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3975-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Whenever in this franchise the term \"grantee\" is used, it shall be held and understood to mean the \"Catholic Welfare Organization\", its representatives, successors or assigns, unless the context indicate otherwise."}},{"id":"PH-H3975-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3975-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Catholic Welfare Organization a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3976"] = {"id":"PH-H3976","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5173_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾海岸警卫队、规定其权力与职能、拨付必要经费并为其他目的法案","en":"An Act Creating a Philippine Coast Guard, Prescribing its Powers and Functions, Appropriating the Necessary Funds Therefor, and for Other Purposes","orig":"An Act Creating a Philippine Coast Guard, Prescribing its Powers and Functions, Appropriating the Necessary Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5173","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5173_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3976-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Coast Guards; Objectives. There is hereby created in the Philippine Navy a major unit to be known as Philippine Coast Guard which shall have the following general objectives:\n(a) To enforce or assist in the enforcement of all applicable laws upon the high seas and waters subject to the jurisdiction of the Republic of the Philippines;\n(b) To enforce laws, promulgate and administer regulations for the promotion of safety of life and property within the maritime jurisdiction of the Philippines; and\n(c) To develop, establish, maintain and operate, with due regard to the requirements of national defense, aids to maritime navigation and rescue facilities for the promotion of safety on and over the high seas and waters, subject to the jurisdiction of the Philippines."}},{"id":"PH-H3976-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Board of Visitors. A Board of Visitors is created which shall have visitorial and policy-making powers to be composed of the Flag Officer-in-Command of the Philippine Navy, the Commissioner of the Bureau of Customs, the Secretary of the Department of Foreign Affairs, the Commissioner of the Bureau of Immigration, the President of the Filipino Shipowners Association, and the Commandant of the Philippine Coast Guard who will act as ex-officio member."}},{"id":"PH-H3976-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Specific Functions. The Philippine Coast Guard shall perform the following functions:\n(a) To prevent and suppress illegal entry, smuggling, other customs frauds and violations of other maritime laws that may be committed within the waters subject to the jurisdiction of the Republic of the Philippines, and for the purpose surveillance by the Philippine Coast Guard may be made on vessels entering and/or leaving the Philippine territory;\n(b) To assist in the suppression of fishing by means of dynamite, explosives or toxic substances or other methods as may be declared destructive by proper authorities;\n(c) To promulgate and enforce rules for lights, signals, speed, steering, sailing, passing, anchorage, movement and towlines of vessels and lights and signals on bridges;\n(d) To approve plans for the construction, repair, or alteration of vessels; approve materials, equipment and appliances of vessels; approved the classification of vessels; inspect vessels and their equipment and appliances; register all types of motorized watercraft plying in Philippine waters; issue certificates of inspection and of permits indicating the approval of vessels for operation; issue certificates of Philippine registry of vessels; administer load line requirements; promulgate and enforce other provisions for the safety of life and property on vessels; and determine the numbering of undocumented vessels: Provided , That certification and approval of any plans, equipment and any vessel by internationally known classification societies which are recognized by the Philippine Government shall be deemed to have complied with this section;\n(e) To issue licenses and certificates to officers, pilots, major and minor patrons and seamen, as well as suspend and revoke such licenses and certificates;\n(f) To investigate marine casualties and disasters including those arising from marine protests filed with the Bureau of Customs relative to the liability of shipowners and officers;\n(g) To enforce laws, rules and regulations governing manning, citizenship and mustering and drilling of crews requirements, control of logbooks, shipment, discharge, protection, and welfare merchant seamen;\n(h) To enforce laws requiring the performance of duties of shipowners and officers after accidents;\n(i) To prescribe and enforce regulations for outfitting and operation of motorboats and the licensing of motorboat operators;\n(j) To regulate regattas and marine parades;\n(k) To render aid to distressed persons or vessels on the high seas and on waters subject to the jurisdiction of the Philippines, and, in this connection, the Philippine Coast Guard may perform any and all acts necessary to rescue and aid persons; furnish clothing, food, lodging, medicine and other necessary supplies and services to persons succored; protect, save, and take charge of all property saved from marine disasters until such property is delivered to persons authorized to receive it or is otherwise disposed of in accordance with law or applicable regulations; and collect and take charge of bodies of those who may perish in such disasters;\n(l) To develop, establish, maintain, and operate aids to maritime navigation. In the performance of these functions, the Philippine Coast Guard is authorized to destroy or tow in port sunken of floating dangers to navigation;\n(m) To supervise nautical schools with reference to activities relative to navigation, seamanship, marine engineering and other allied matters, in coordination with the Department of Education;\n(n) To perform functions pertaining to maritime communications which are not specifically delegated to some other office or department; and\n(o) To assist, within its capabilities and upon request of the appropriate authorities, other Government agencies in the performance of their functions, within the waters subject to the jurisdiction of the Philippines, relating to matters and activities not specifically mentioned in this section: Provided , That in the exercise of these functions, personnel of the Philippine Coast Guard shall be deemed to be acting as agents of the particular departments, bureau, office, agency or instrumentality charged with the enforcement and administration of the particular law. Members of the Philippine Coast Guard are peace officers for all purposes of this Act and shall be, and shall act, as law enforcement agents of the Bureau of Customs, and the Bureau of Immigration, the Bureau of Internal Revenue, the Fisheries Commission, and such other departments, bureaus or offices in the enforcement of pertinent laws, rules and regulations."}},{"id":"PH-H3976-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Organization; Administration. The Philippine Coast Guard shall be headed by a Commandant who shall be a Flag Officer. Subject to the approval of the Secretary of National Defense, the Flag Officer-in-Command, Philippine Navy, shall organize the Philippine Coast Guard into operational units or subordinate commands and equip the same as may be necessary for effective exercise of the functions and duties vested upon it by law, and shall promulgate rules and regulations necessary for its administration. The Philippine Coast Guard shall be administered and maintained as a separate unit of the Philippine Navy and it shall be specially trained and equipped for the effective discharge of police and duties at sea.\nThe Marine Safety Division, including the Naval Architecture and Engineering Section, the Maritime Safety Inspection Section, the Registration and Licensing Section and the functions of the Hulls and Boilers Division, the Marine Board of Inquiry as existing in the Bureau of Customs, and all other agencies or instrumentalities of the Government presently performing any of the function provided for in subparagraphs (c) to (n), inclusive of Section three of this Act, are hereby transferred with their personnel, records, files, supplies, equipment, furnitures, funds and other properties to the Philippine Coast Guard: Provided , That no person shall be deprived of his office employment or rank, or suffer any diminution of his salary by operation of this Act. The Lighthouse Service of the Philippine Navy is, likewise, transferred to the Philippine Coast Guard. Personnel transferred to the Philippine Coast Guard shall continue to be governed by the Civil Service Law and other existing laws relating to their individual status, rights, emoluments and benefits."}},{"id":"PH-H3976-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Unauthorized Aids to Maritime Navigation. The person, association or corporation shall establish, erect, or maintain any aid to maritime navigation without first obtaining authorization from the Philippine Coast Guard in accordance with applicable regulations."}},{"id":"PH-H3976-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Interference with Aids to Navigation. It shall be unlawful for any person, association or corporation, to remove, change the location of, obstruct, willfully damage, make fast to, or interfere with any aid to maritime navigation."}},{"id":"PH-H3976-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Penal Provisions. Any person, association or corporation who violate any provision of this Act, or the rules and regulations made thereunder, shall upon conviction, be punished with a fine of not less than one hundred pesos nor more than five hundred pesos or by imprisonment of not less than thirty days nor more than six months or both: Provided, finally , That, in case the violation is committed by an association or corporation, the penalty herein prescribed shall be imposed on the responsible officers or directors thereof: Provided, finally , That, nothing in this Act shall prevent the Philippine Coast Guard from providing administrative penalties for violation of any regulation that it promulgates."}},{"id":"PH-H3976-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"To carry out the purposes of this Act, there is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of fifteen million three hundred twenty-seven thousand five hundred pesos for the purchase of watercraft, personnel services, requirement for maintenance and other operating expenses: Provided , That sixty thousand pesos shall be used exclusively for the updating of the Philippine merchant maritime regulations. To enable the Philippine Coast Guard to acquire the necessary vessel-requirement to accomplish effectively its mission, the sum of nine million pesos each year for the first two years after the passage of this Act and thirteen million pesos each for the succeeding three years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3976-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All laws, executive orders, rules and regulations and parts thereof inconsistent with this Act are hereby repealed."}},{"id":"PH-H3976-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a Philippine Coast Guard, Prescribing its Powers and Functions, Appropriating the Necessary Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3977"] = {"id":"PH-H3977","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5174_1967.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在菲律宾大学设立社会工作与社区发展研究所，为其建筑物、设备、设施与营运费用提供经费并为其他目的","en":"An Act Establishing the Institute of Social Work and Community Development in the University of the Philippines, Providing Funds for Building, Equipment, Facilities and Operating Expenses Thereof, and for Other Purposes","orig":"An Act Establishing the Institute of Social Work and Community Development in the University of the Philippines, Providing Funds for Building, Equipment, Facilities and Operating Expenses Thereof, and for Other Purposes","vi":"Đạo luật thành lập Đại học Institute of Social Work and Community Development in Philippines, và cho các mục đích khác","th":"พระราชบัญญัติจัดตั้งมหาวิทยาลัย Institute of Social Work and Community Development in Philippines และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang membentuk Universitas Institute of Social Work and Community Development in Philippines, dan untuk tujuan lain","ms":"Akta menubuhkan Universiti Institute of Social Work and Community Development in Philippines, dan untuk tujuan lain"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5174","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5174_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3977-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established an Institute of Social Work and Community Development in the University of the Philippines which shall provide professional and advanced training, research and extension services to foster and inculcate the importance and relevance of social work and community development."}},{"id":"PH-H3977-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Institute of Social Work and Community Development may, for the purpose of this Act, obtain the services of professional or technical personnel from any agency of the Philippine Government or from the private sector to provide instruction, perform research, and such other activities as may be necessary. Such personnel will be given honorarium at rates fixed by Board of Regents of the University of the Philippines, any law to the contrary notwithstanding."}},{"id":"PH-H3977-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In pursuance of its projects and activities in teaching, research and extension services, the Institute may avail itself of the other services, facilities, equipment and research materials of any government and/or private agencies or offices. The Institute may likewise undertake joint or cooperative research and extension projects with other government and private agencies."}},{"id":"PH-H3977-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of one million five hundred thousand pesos for necessary building and other facilities and equipment of the Institute of Social Work and Community Development of the University of The Philippines: Provided, that the sum of three hundred thousand pesos is appropriated for the operating expenses of the Institute for fiscal year nineteen hundred sixty-seven and nineteen hundred sixty-eight: Provided, further, That at least the amount of three hundred thousand pesos shall be appropriated every year thereafter, beginning with the next succeeding fiscal year, out of funds in the National Treasury not otherwise appropriated for the continued support of the Institute."}},{"id":"PH-H3977-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing the Institute of Social Work and Community Development in the University of the Philippines, Providing Funds for Building, Equipment, Facilities and Operating Expenses Thereof, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3978"] = {"id":"PH-H3978","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5175_1967.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"修订第 4373 号共和国法（即《规范菲律宾社会工作执业与社会工作机构运营并为其他目的法案》）的法案","en":"An Act to Amend Republic Act Numbered Four Thousand Three Hundred Seventy-Three, Entitled \"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes\"","orig":"An Act to Amend Republic Act Numbered Four Thousand Three Hundred Seventy-Three, Entitled \"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 4373, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 4373 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Undang-Undang Republik No. 4373, dan untuk tujuan lain","ms":"Akta meminda Akta Republik No. 4373, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5175","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5175_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3978-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraph (a) of Section one of Republic Act Numbered Forty three hundred seventy three is hereby amended to read as follows:\n\"Sec. 1. As used in this Act:\n\"(a) Social work is the profession which is primarily concerned with organized social service activity, aimed to facilitate and strengthen basic social relationships and the mutual adjustment between individuals and their social environment for the good of the individual and of society by the use of social work methods.\""}},{"id":"PH-H3978-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subparagraph (c) of Section two of the same Act is hereby amended to read as follows:\n\"(c) Possess a Master’s Degree in Social Work (M.S.S.W., M.S.S., M.A.S.W., or its equivalent) conferred by a reputable school, college or university duly recognized by the government, and also by a duly accredited school, college or university abroad.\""}},{"id":"PH-H3978-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section ten of the same Act is hereby amended to read as follows:\n\"Sec. 10. Practice of social work and appointment as social workers. — Unless exempt from registration, no person shall practice or offer to practice social work in the Philippines as defined in this Act, or be appointed as a social worker or to any position calling for social worker in any social worker agency whether private or government without holding a valid certificate of registration as a social worker issued by the Board of Examiners for Social Workers: Provided, That registration shall not be required of recognized social workers or authorities on social work who are residents and/or citizens of other countries called in for consultations in any agency working with the United Nations and/or similar international social agencies: Provided, further, That no provision of this Act shall be construed to prejudice permanently appointed social workers who are employed in private or government social work agencies at the date of approval of this Act, who shall continue to enjoy rights to promotion and salary increases, retirement benefits and other previously acquired rights: Provided, Furthermore, That those who at the time of the effectivity of this Act, possess the qualifications enumerated in Section twelve and are actually engaged in the practice of social work for a period of five years in a social work agency recognized by the Community Chest, Council of Welfare Agencies, Philippine Youth Welfare Coordinating Council, or Social Welfare Administration, shall be exempted from taking the examination as provided herein if they register as social workers within a period of one year after the approval of this Act: Provided, still further, That those who before the effectivity of this Act are holding regular appointment to social work positions in the government service on a provisional status for lack of the educational qualifications required under this Act for the purpose of taking the board examination and have rendered five years or more of continuous and satisfactory service in social work shall, within a period of ten years but not later than December thirty-first, nineteen hundred seventy-eight, be allowed to retain their positions in order to qualify as registered social workers under the provisions hereof: And Provided, finally, That any person who at the time of the effectivity of this amendatory Act possesses the qualifications enumerated in Section twelve hereof except that which is specified in subparagraph (d) of Section two hereof and who has been openly performing the functions of, or practicing as, a social worker as defined in this Act for at least a total of ten years prior to the effectivity of this amendatory Act, shall be allowed to continue performing such functions or such practice in the same office or agency until he or she retires without the necessity of examination for registration provided that an affidavit affirming the circumstances of such continuous practice or a certification by the Civil Service to the same effect is filed with the Board.\""}},{"id":"PH-H3978-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twelve of the same Act is hereby amended to read as follows:\n\"Sec. 12. Qualification of applicants. — In order to be admitted to take the social work examination, an applicant must, at the time of filing his or her application therefor, establish to the satisfaction of the Board that:\n\"(a) He or she is a citizen of the Philippines;\n\"(b) He or she is at least twenty-one years of age;\n\"(c) He or she is in good health and is of good moral character;\n\"(d) He or she has received a diploma as holder of a bachelor’s degree or master’s degree or its equivalent in social work from an institution, college or university duly accredited and legally constituted: Provided, That the provisions of Republic Act Numbered Twenty-two hundred and sixty insofar as cultural minorities are concerned be applied; and \"(e) He or she has completed a minimum period of one thousand case hours of practical training in an established social work agency under the direct supervision of a fully trained and qualified social worker.\""}},{"id":"PH-H3978-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subparagraph (h) of Section twenty-six of the same Act is hereby repealed."}},{"id":"PH-H3978-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Subparagraph (i) of Section twenty-six of the same Act is hereby re-designated as subparagraph (h)."}},{"id":"PH-H3978-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Four Thousand Three Hundred Seventy-Three, Entitled \"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3979"] = {"id":"PH-H3979","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5176_1967.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"依第 333 号共和国法加快国家政府机关迁往首都并为其他目的法案","en":"An Act Expediting the Transfer of National Government Offices to the Capital City Pursuant to Republic Act Numbered Three Hundred Thirty-Three and for Other Purposes","orig":"An Act Expediting the Transfer of National Government Offices to the Capital City Pursuant to Republic Act Numbered Three Hundred Thirty-Three and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5176","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-08-04","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5176_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3979-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Pursuant to the provisions of Republic Act Numbered Three hundred thirty-three, the Department of General Services, hereinafter referred to as the Department, is hereby directed to expedite the transfer of national government offices to the Capital City and create thereat a government center."}},{"id":"PH-H3979-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To finance the construction of the buildings that will house said offices in the Capital City and/or the acquisition or purchase of land to be occupied by them, there is hereby created a building fund account in the department: Provided, That the executive, the Judiciary and the two Houses of Congress shall each form and constitute a committee of their own choice which shall be in consultation from time to time with the architect and the builder to the end that the needs and requirements of their respective departments are considered and taken into account, consistent with the demands of harmony and reflective of the art, culture and history of the Philippines: Provided further, That in the event of any disagreement between the aforesaid committee and the architect and the builder, said disagreement shall be resolved by the office of the President of the Philippines."}},{"id":"PH-H3979-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The following shall constitute the building fund account:\n(a) Proceeds from the sale, and rentals from the lease of government properties as provided under Section five hereof; and\n(b) All amounts for the rental of office space by any agency or instrumentality of the national government that may no longer spend or pay for such rental."}},{"id":"PH-H3979-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No amount in the building fund account can be used for any purpose other than to pay the amortization of any loan obtained under Section six hereof and/or to finance the construction of the buildings not exceeding the corresponding appropriation made by law, including the acquisition and/or purchase of the corresponding sites as provided under Section two hereof."}},{"id":"PH-H3979-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subject to existing rules and regulations, the Department upon recommendation of the Bureau of Building and Real Property Management is empowered to sell or lease through public biddings, such real property within its jurisdiction and/or administration that are not actually allocated for permanent use by the government or any of its agency or instrumentality including government-owned or controlled corporations. In the case of sale of land and/or improvements thereon under this section or purchase of lots under section two hereof, the party vendor or the party vendee shall, as the case may be, be the Republic of the Philippines, represented by the Department."}},{"id":"PH-H3979-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Subject to approval of the President of the Philippines and to the supervision of the Secretary of Finance, the Department is authorized to borrow funds from any local or foreign financial institution payable for a period not exceeding twenty years, to finance the construction of buildings including the purchase and/or acquisition of site as provided in Section 4 hereof: Provided, That the building project has been authorized by Congress: and Provided, further, That the total loan which may be obtained by virtue of this Section shall not exceed three hundred million pesos.\nAll loans obtained under this Section shall be fully guaranteed by the Republic of the Philippines as to amortization. In the event the Department shall be unable to pay said amortization, the Secretary of Finance shall pay the amount thereof which is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated and thereupon, the amounts so paid shall be reimbursed by the Department from whatever amount as may be available in the building fund account.\nSuch sums as are reimbursed to the Secretary of Finance shall automatically accrue to the general fund of the government."}},{"id":"PH-H3979-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The design and construction of the buildings herein provided shall be undertaken under the supervision of the Bureau of Public Works in coordination with the Bureau of Building and Real Property Management."}},{"id":"PH-H3979-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All laws, executive orders, rules and regulations, or a part thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H3979-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 4, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expediting the Transfer of National Government Offices to the Capital City Pursuant to Republic Act Numbered Three Hundred Thirty-Three and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3980"] = {"id":"PH-H3980","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5177_1967.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予 Manila Electric Company 在甲米地省 Bacoor 与 Imus 市镇范围内建设、维护和运营电灯、供热与动力系统以发电供电并为其他目的法案","en":"An Act Granting to the Manila Electric Company a Franchise to Construct, Maintain, and Operate an Electric Light, Heat, and Power System for the Purpose of Generating and Distributing Electric Light, Heat, and Power, for Sale Within the Limits of the Municipalities of Bacoor and Imus, Province of Cavite, and for Other Purposes","orig":"An Act Granting to the Manila Electric Company a Franchise to Construct, Maintain, and Operate an Electric Light, Heat, and Power System for the Purpose of Generating and Distributing Electric Light, Heat, and Power, for Sale Within the Limits of the Municipalities of Bacoor and Imus, Province of Cavite, and for Other Purposes","vi":"Đạo luật cấp quyền khai thác cho Manila Electric Company để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Bacoor và Imus, tỉnh Cavite","th":"พระราชบัญญัติให้สัมปทานแก่ Manila Electric Company เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Bacoor และ Imus, จังหวัด Cavite","id":"Undang-Undang memberikan waralaba kepada Manila Electric Company untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Bacoor dan Imus, Provinsi Cavite","ms":"Akta memberikan francais kepada Manila Electric Company untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Bacoor dan Imus, Wilayah Cavite"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5177","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-07","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5177_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3980-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act, there is hereby granted to the Manila Electric Company hereinafter known as the grantee, a corporation duly organized under the laws of the Philippines and domiciled in the City of Manila, Philippines, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain, and operate an electric light, heat, and power system for the purpose of generating and distributing electric light, heat, and power, for sale within the limits of the municipalities of Bacoor, and Imus, Province of Cavite, Philippines. The grantee shall further have the right and privilege to install, lay, and maintain in, along, under, and over public property of the municipalities, including the public streets and highways, provincial roads, bridges, and public squares within said municipalities all necessary apparatus and appurtenances for the transmission and distribution of electric current, and to supply, sell, and furnish such current to any individual, co-partnership, private, public or quasi-public association, corporation or joint-stock company, within the limits of said municipalities for national, provincial, municipal, domestic, or manufacturing uses or for any other use to which electricity may be put, and to charge and collect a schedule of prices and rates for the use of electric current so furnished, which schedule of prices and rates shall at all times be subject to regulation by the Public Service Commission or its legal successor."}},{"id":"PH-H3980-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Said grantee shall supply electric power, and/or heat, and/or light to any applicant for the same within fifteen days after the date of his application, in the order of the date of the application up to the limit of the capacity of the plant of said grantee, said limit to be determined by the Public Service Commission or its legal successor in such certificate or certificates of public necessity and convenience as may be issued by it as prescribed by Section eight of this Act; and should the demand for electric power, and/or heat, and/or light at any time increase beyond the capacity of the plant of said grantee to supply the same, the capacity of said plant shall be increased by said grantee to such reasonable extent and within such reasonable time as may be fixed by the Public Service Commission or its legal successor. If, however, the point at which the electric power, and/or heat, and/or light is to be supplied is more than thirty meters from the lines operated by said grantee, the latter should not be obligated to furnish said service, except upon the receipt of such additional prices and rates as the Commission, or its legal successor, may determine to be just and reasonable."}},{"id":"PH-H3980-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee hereby agrees to compensate the municipalities for any damage to their properties by reason of the construction under this franchise or of any neglect or omission to keep the said poles, wires and other property in a safe condition, and to be responsible for any damage to individuals, co-partnerships, private, or quasi-public associations, or joint-stock companies, arising out of such fault, neglect, or negligence."}},{"id":"PH-H3980-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All apparatus and appurtenances used by the grantee shall be modern, safe, and first class in every respect (all wires shall be carefully connected, fastened, and insulated) and the grantee shall, whenever the Public Service Commission or its legal successor shall determine that the public interest reasonably requires it, place said wires in the underground pipes or conduits at its own expense, and without any cost or prejudice to the municipalities. The poles erected by the grantee shall be of such height as to maintain the wires stretched on the same at distance of at least twenty feet above the level of the ground, and shall be of such appearance as not to disfigure the streets, and shall be placed with due regard for the public safety, in accordance with a plan previously approved by the Public Service Commission after hearing the municipal authorities concerned."}},{"id":"PH-H3980-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Whenever it shall, in the opinion of the Public Service Commission or its legal successor, become necessary in the public interest or convenience, to change the location of the grantee’s poles, underground pipes or conduits, such change shall be made without delay by the grantee, its successors or assigns, at the grantee’s expense, and the same shall be placed where directed by the Public Service Commission after hearing the proper municipal authorities."}},{"id":"PH-H3980-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Whenever it shall be necessary in the erection of said poles, or in the placing of said wires in underground pipes or conduits, to take up any portion of the sidewalks or dig up the ground near the sidewalks or corners of the public streets or thoroughfares, the grantee shall, after said poles or underground pipes or conduits are constructed, replace without delay said sidewalks and other property in a proper manner, removing from the same all rubbish, dirt, refuse, or other material which may have been placed there, taken up or dug up in the erection of said poles, underground pipes or conduits, leaving all property in as good condition as before the work was done."}},{"id":"PH-H3980-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Whenever any individual, co-partnership, private, public or quasi-public association, corporation or joint-stock company has lawfully obtained permission to use any of the public property of said municipalities, including the public streets and highways, provincial roads, bridges, and public squares, for any cause whatsoever, making it necessary to raise or remove any of said poles and/or electric wires and/or pipes, which may hinder or obstruct the prosecution of said work, the said grantee, upon written notice by the municipal council of said municipality, served upon the grantee in person or upon its duly authorized agent at least forty-eight hours in advance, shall raise or remove any of its poles and/or electric wires and/or conduits and/or pipes which might hinder or obstruct the prosecution of said work so as to allow the free and unobstructed prosecution of said work. The notice shall be in the form of a duly adopted resolution of the municipal court concerned, served upon the grantee or its duly authorized agent by a person competent to testify in a civil action. The individual, co-partnership, private, public or quasi-public association, corporation, or joint-stock company at whose request the raising or removing of said poles and/or electric wires and/or conduits and/or pipes has been done shall pay one-half of the actual cost thereof to the grantee, and also one-half of the actual cost of the replacement. In the case of their refusal or failure of the grantee to comply with such notice, the Public Service Commission after hearing the municipal authorities concerned, shall order such poles and/or electric wires and/or conduits and/or pipes raised or removed at the sole expense of the grantee."}},{"id":"PH-H3980-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall not exercise any rights or privileges under this franchise, nor commence any construction thereunder, unless and until the grantee shall first file with the Public Service Commission within one hundred twenty days from the date of the approval of this Act:\n(1) Its written acceptance of the terms and provisions of this Act;\n(2) Its written acceptance of the terms and conditions of the first certificate or certificates of necessity and convenience required by law for the granting of this franchise and issued by the Public Service Commission, of the form and character provided for in Act Numbered Thirty-one hundred and eight, as amended:\n(3) A document or documents evidencing receipt by the Treasurer of the Philippines, of the deposit or deposits required by law, of not less than one thousand pesos, Philippine currency, or negotiable bonds approved by the Public Service Commission for each certificate of public necessity and convenience as an earnest of good faith, and a guarantee that the grantee will complete the work within the period fixed by the Commission.\nIf the grantee shall not commence the furnishing of electric current in any municipalities referred to in any certificate or certificates of public convenience and necessity, obtained and filed as herein provided within such period as the Public Service Commission or its legal successor shall have fixed, unless prevented by an act of God or force majeure, usurped or military power, martial law, riot, civil commotion or other cause beyond its control, said Commission or its legal successor may in its discretion, declare such certificate or certificates to be null and void, and the deposit or deposits made by the grantee forfeited to such municipality as liquidated damages and not as a penalty."}},{"id":"PH-H3980-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"After compliance with the requirements of the next preceding section, the Public Service Commission or its legal successor, by proper order or writ, shall authorize the construction of necessary work for the purposes of this franchise, within a reasonable time to be determined by the said Commission.\nUpon determination by the Public Service Commission or its legal successor after a hearing upon reasonable written notice to the grantee that the grantee has violated any of the provisions of this Section as to the commencement and/or completion of the work authorized by a certificate or certificates of the Public Service Commission or its legal successor, the said Commission or its legal successor shall declare the bond or bonds forfeited as liquidated damages and not as a penalty to the municipality in which the failure to perform occurred. If the failure occurred in more than one municipality, the Public Service Commission or its legal successor shall determine the portion which each municipality shall receive. The Public Service Commission or its legal successor shall order the return of the deposit required by Section eight hereof, as amended, together with any interests or dividends thereon received by the Treasurer of the Philippines, to the grantee upon the satisfactory completion of any work authorized by its certificate or certificates of public necessity, in accordance with the terms and conditions of the certificate or certificates obtained, and the Treasurer of the Philippines, shall return said deposit to the grantee together with said interests and/or dividends immediately upon presentation to him of a certified copy of such order of the Public Service Commission or its legal successor."}},{"id":"PH-H3980-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall pay the same taxes as are now or may hereafter be required by law from other individuals, co-partnerships, private, public or quasi-public associations, corporations, or joint-stock companies, on its real estate, buildings, plants, machinery, and other personal property, except property declared exempt in this section. In consideration of the franchise and rights hereby granted, the grantee shall pay into the municipal treasury of each municipality in which it is supplying electric current to the public under its franchise, a tax equal to two per centum of the gross earnings from electric current sold or supplied under this franchise in each said municipality. Said tax shall be due and payable quarterly and shall be in lieu of any and all taxes of any kind, nature, or description levied, established, or collected by any authority whatsoever, municipal, provincial, or national, now or in the future, on its poles, wires, insulators, switches, transformers and structures, installations, conductors, and accessories, placed in and over and under all public property, including public streets and highways, provincial roads, bridges and public squares, and on its franchise, rights, privileges, receipts, revenues and profits, from which taxes the grantee is hereby expressly exempted."}},{"id":"PH-H3980-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The municipalities shall have the privilege, without compensation, for and during the time the wires of the grantee are maintained on poles of using the said poles of the grantee for the purpose of installing, maintaining, and operating a police telephone and fire alarm system, but the wires of such police telephone or fire alarm system shall be placed and stretched in such manner as to cause no interference with or damage to the wires of the electric service of the grantee. Any of the municipalities above specified which make use of the aforesaid privilege shall be liable to the grantee for any damage or liability arising from the installation, maintenance or operation of said police telephone or fire alarm system."}},{"id":"PH-H3980-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This franchise is granted subject to the provisions of Act Numbered Thirty-one hundred and eight, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines, and that it shall be subject in all respects to the limitations upon corporations and the granting of franchises contained in the Constitution of the Philippines, and also subject to the provisions of Act Numbered Fourteen hundred and fifty-nine of the Philippine Legislature, as amended."}},{"id":"PH-H3980-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All lands or right of use or occupation of lands hereby granted by the national, provincial, or municipal governments shall upon the termination, revocation or repeal of this franchise, revert to the respective national, provincial or municipal governments which were the owners thereof or from which said lands or rights were derived."}},{"id":"PH-H3980-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the provincial treasurer or his authorized representative, and it shall be the duty of the grantee to submit to the provincial treasurer quarterly reports in duplicate showing the gross receipts for the quarter past, one of which shall be forwarded by the provincial treasurer to the Auditor General who shall keep the same on file."}},{"id":"PH-H3980-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee, with the approval of the Congress of the Philippines first had, may sell, lease, grant, convey, assign, give in usufruct or transfer this franchise and all property and rights acquired thereunder to any individual, co-partnership, private, public or quasi-public association, corporation, or joint-stock company competent to operate the business hereby authorized, but transfer of title to the franchise or any right of ownership or interest acquired under such sale lease, grant, conveyance, assignment, gift in usufruct, or transfer shall not be effective even after such approval shall have been obtained until there shall have been filed in the office of the Public Service Commission or its legal successor an agreement in writing by which the individual, co-partnership, private, public or quasi-public association, corporation, or joint-stock company in whose favor such sale, lease, grant, conveyance, assignment, gift in usufruct, or transfer in made, shall be firmly bound to comply with all the terms and conditions imposed upon the grantee by this franchise and by any and all certificates of public necessity and convenience theretofore issued by the Public Service Commission or its legal successor, and to accept the same subject to all existing terms and conditions."}},{"id":"PH-H3980-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Public Service Commission or its legal successor shall have the power, after a reasonable written notice to the grantee and a hearing of the interested parties, to declare the forfeiture of this franchise and all rights inherent in the same for failure on the part of the grantee to comply with any of the terms and conditions thereof, unless such failure shall have been directly and primarily caused by the act of God, force majeure, usurped right, uprising or other cause beyond the grantee’s control. Against such declaration of forfeiture by the Public Service Commission or its legal successor, the grantee may apply for the remedies provided in sections twenty-eight and thirty-five of Act Numbered Thirty-one hundred and eight, as amended. The remedy provided herein shall not be a bar to any other remedy provided by existing laws for the forfeiture of this franchise."}},{"id":"PH-H3980-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving either a franchise or permission from the Government of the Philippines or from any province, city or municipality thereof, to conduct a similar business in all or any substantial portion of the territory covered by this franchise to that of the grantee, in which franchise or permission there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporations."}},{"id":"PH-H3980-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Upon the approval of this Act the grantee may acquire by purchase all serviceable equipment of the electric operators in the municipalities of Bacoor and Imus. In the acquisition by the grantee of equipment belonging to the Communications and Electricity Development Authority, the chief of the Mechanical-Electrical Division of the Bureau of Public Works, the Chief of the Investigation and Planning Division of the National Power Corporation, or their authorized representatives, and an electrical engineer to be designated by the Public Service Commission, shall constitute the appraisal committee. The acquisition cost to be fixed by the appraisal committee shall be subject to the approval of the Public Service Commission sitting en banc."}},{"id":"PH-H3980-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 7, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to the Manila Electric Company a Franchise to Construct, Maintain, and Operate an Electric Light, Heat, and Power System for the Purpose of Generating and Distributing Electric Light, Heat, and Power, for Sale Within the Limits of the Municipalities of Bacoor and Imus, Province of Cavite, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3981"] = {"id":"PH-H3981","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5178_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"便利第3588号共和国法（经修正）关于仅1967年选民登记的实施，延长选民登记及相关程序的期限，增设登记委员会，并授予选举委员会附加权力，并为其他目的法案","en":"An Act to Facilitate Implementation of Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, as Amended, on the Registration of Voters for Nineteen Hundred Sixty-Seven Only, Extending the Periods for Registration of Voters and Related Proceedings Thereunder, Providing for Additional Registration Boards, and Granting Additional Powers to the Commission on Elections, and for Other Purposes","orig":"An Act to Facilitate Implementation of Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, as Amended, on the Registration of Voters for Nineteen Hundred Sixty-Seven Only, Extending the Periods for Registration of Voters and Related Proceedings Thereunder, Providing for Additional Registration Boards, and Granting Additional Powers to the Commission on Elections, and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5178","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5178_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3981-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of Republic Act Numbered Thirty-five hundred eighty-eight, as amended by Republic Act Numbered Forty-seven hundred thirty, and of any other law to the contrary notwithstanding, and for purposes of the registration of voters in nineteen hundred sixty-seven only, it is hereby provided:\n(a) Any qualified voter may register on any date not later than October fifteen, nineteen hundred sixty-seven: Provided , That if, for any reason, the representatives of the two political parties in any election registration board shall jointly request the Commission on Elections, or if, after verification, the latter shall find that more than ten percent of the number of voters who voted in the nineteen hundred sixty-five elections were not able to apply for registration as of October fifteen, nineteen hundred sixty-seven in any precinct or precincts, the Commission on Elections shall extend the period of registration, in said precinct or precincts only, up to October twenty-seven, nineteen hundred sixty-seven;\n(b) Validation of approved applications for registration shall continue until October twenty-seven, nineteen hundred sixty-seven;\n(c) Voters who, for any reason whatsoever, have not been allowed to apply for registration or to register or whose applications shall have been disapproved on or before September fifteen, nineteen hundred sixty-seven shall have until September thirty, nineteen hundred sixty-seven within which to file their petitions for inclusion provided for in Section ten of Republic Act Numbered Thirty-five hundred eighty-eight as amended; those after September fifteen, nineteen hundred sixty-seven shall have a period of not more than ten days from notice of disapproval within which to do so; in all cases, the petition shall be decided within two (2) days. The decisions of the Municipal Court shall be appealable to the Court of First Instance within two (2) days from receipt of notice by the parties and the decisions of the City Court and the Court of First Instance shall be immediately executory and shall be final as to questions of fact.\n(d) Petitions for exclusion of voters whose applications for registration were validated or approved on or before September fifteen nineteen hundred sixty-seven may be filed as provided by Section eighteen of Republic Act Numbered Thirty-five hundred eighty-eight, as amended, on or before September thirty, nineteen hundred sixty-seven; and in order to facilitate the filing of these petitions, each election registration board shall prepare complete lists of: (a) all the voters whose applications for registration have been validated and (b) all newly registered voters as of September fifteen, nineteen hundred sixty-seven, which lists shall be furnished the local representatives of the two major political parties, and published in the bulletin board, not later than September eighteen, nineteen hundred sixty-seven; petitions for exclusion of voters whose applications were validated or approved after September fifteen, nineteen hundred sixty-seven may be filed within a period of not more than ten (10) days from the date the validation or approval is published in the bulletin board but not later than October thirty, nineteen hundred sixty-seven; in all cases, the petition shall be decided within seven (7) days. The decisions of the Municipal Court shall be appealable to the Court of First Instance within five (5) days from receipt of notice by the parties and the decisions of the City Court and the Court of First Instance shall be immediately executory and shall be final as to questions of fact.\n(e) Petitions for inclusion and exclusion shall be sworn to and shall be accompanied by proof of notice on the registration board and, in petitions of exclusion, also on the challenged voter; and the procedure prescribed by Sec. 123 of the Revised Election Code shall be followed, except that the notice required by said section shall be made to the registration board instead of the board of inspectors, and the period fixed in this Act, instead of those fixed in said section, shall be observed;\n(f) All precinct books of voters shall be sealed on October thirty, nineteen hundred sixty-seven and, thereafter, shall not be available for examination by the public;\n(g) Publications of the precinct list of voters as required by Section Twenty-three of Republic Act Numbered Thirty-five hundred eighty-eight, as amended, shall be made on October thirty, nineteen hundred and sixty-seven;\n(h) The election registrar and the members of the election registration board may hold office as a board in any district, barrio or sitio within their jurisdiction and shall be allowed transportation expenses, subject to the rules and regulations of the Commission of Elections, for the purpose of taking photographs of voters whose registration are subject of validation and to facilitate the filing of new applications for registration.\n(i) The Commission on Elections is hereby authorized, for purposes of the nineteen hundred and sixty-seven elections, to appoint and to fix the salaries of as many additional election registrars, and to constitute their corresponding election registration boards, as may be necessary in any city or municipality where, upon approval of this Act, the number of voters still to be registered exceeds one thousand voters, at the rate of not more than one election registrar for every one thousand unregistered voters: Provided , That the party representatives in these election registration boards shall be proposed by the respective political parties within three days from notification thereof, otherwise, the Commission on Elections, shall appoint such members until replaced by the political party concerned: Provided, further , That if there are no qualified persons for appointment as additional election registrars, the Commission on Elections may appoint qualified voters who are at least high school graduates. For the purpose of determining the number of unregistered voters on the date of approval of this Act, the basis shall be the total number of voters who actually voted in the nineteen hundred and sixty-five elections minus the number of voters whose registration have been validated by the election registration board;\n(j) The election registrar, his clerk, or any member of the election registration board shall, upon request of the applicant, assist any applicant for registration in the accomplishment of his application, but may not fill out or write any of the data required by law to be written by the applicant himself;\n(k) The city or municipal treasurer shall perform the duties and exercise the powers of the election registrar in case the latter is temporarily absent or unable for any reason to perform his duties, or in the event of a permanent vacancy, pending appointment of the regular incumbent: Provided , That if both the election registrar and the Municipal or city treasurer are absent or incapacitated, the election clerk shall act as substitute election registrar: Provided, further , That the election clerk shall immediately report to the election registrar or to the Municipal or city treasurer, in case the latter is acting as election registrar, all actions performed by him; and\n(l) The procedures and periods provided for in Republic Act Numbered Thirty-five hundred eighty-eight, as amended by Republic Act Numbered Forty-seven hundred thirty, shall be followed, except as hereinabove provided: Provided , That the Commission on Elections may, upon notice and hearing, by general resolution, modify or waive the requirements for affixing of photographs to applications and identification cards in order to prevent disenfranchisement of qualified voters whose applications are not or may not be validated or approved with in the periods herein fixed solely due to the absence of such photograph, but the photographs must be affixed as soon as possible after the 1967 election."}},{"id":"PH-H3981-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, September 8, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Facilitate Implementation of Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, as Amended, on the Registration of Voters for Nineteen Hundred Sixty-Seven Only, Extending the Periods for Registration of Voters and Related Proceedings Thereunder, Providing for Additional Registration Boards, and Granting Additional Powers to the Commission on Elections, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3982"] = {"id":"PH-H3982","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5179_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"设立巡回刑事法院审理和裁决特定刑事案件并为其他目的法案","en":"An Act Creating Circuit Criminal Courts to Try and Decide Certain Criminal Cases and for Other Purposes","orig":"An Act Creating Circuit Criminal Courts to Try and Decide Certain Criminal Cases and for Other Purposes"},"level":"law","status":"active","topics":["criminal","judiciary"],"docNumber":"Republic Act No. 5179","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5179_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3982-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In each of the sixteen judicial districts for the Courts of First Instance as presently constituted, there is hereby created a Circuit Criminal Court with limited jurisdiction, concurrent with the regular court of first instance, to try and decide the following criminal cases falling under the original and exclusive jurisdiction of the latter:\n(a) Crimes committed by public officers, crimes against persons and crimes against property as defined and penalized under the Revised Penal Code, whether simple or complexed with other crimes;\n(b) Violations of Republic Act No. 3019, otherwise known as the Anti-Graft and Corrupt Practices Act, and Republic Act No. 1379; and\n(c) Violations of sections 3601, 3602, and 3604 of the Tariff and Customs Code and sections 174, 175 and 345 of the National Internal Revenue Code."}},{"id":"PH-H3982-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The judges of the Circuit Criminal Courts herein created shall be appointed by the President with the consent of the Commission on Appointments, and shall have the same qualifications, rank, compensation and privileges, and shall be subject to the same restrictions or disabilities, as the judges of the Courts of First Instance. They shall hold office during good behavior and may be suspended or removed only in the manner and upon the same grounds as the judges of the Courts of First Instance."}},{"id":"PH-H3982-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of all laws and the Rules of Court relative to the judges of the Courts of First Instance and the trial, disposition and appeal of criminal cases therein shall be applicable to the circuit judge and the cases cognizable by them insofar as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H3982-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Circuit Criminal Courts may hold sessions anywhere within their respective districts: Provided, however , That cases shall be heard within the province where the crime subject of the offense was committed: And provided, further , That when the interest of justice so demands, with prior approval of the Supreme Court, cases may be heard in a neighboring province within the district. The provincial governments concerned shall provide the Circuit Criminal Courts with adequate office space."}},{"id":"PH-H3982-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Justice shall designate from among the personnel of the Courts of First Instance of the province where any of the circuit criminal courts is holding session those who shall act as personnel of the latter court and, as such, shall be subject to the order of the Circuit Judge: Provided, however , That nothing in this section shall preclude the Secretary of Justice from appointing such permanent personnel of each circuit criminal court as may be necessary."}},{"id":"PH-H3982-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Criminal cases cognizable by the Circuit Criminal Courts herein created which are pending in, and have been partly tried by, the Courts of First Instance as of the date of the approval of this Act shall continue to be tried and decided by the latter. As far as practicable, the trial of cases in the Circuit Criminal Courts, once commenced, shall be continuous until terminated and the judgment shall be rendered within thirty days from the time the case is submitted for decision.\nUnless inconsistent with the provisions of this Act, the Circuit Criminal Courts shall have the same powers as those conferred by the Judiciary Act and the Rules of Court upon the regular Courts of First Instance, insofar as may be necessary to carry their jurisdiction into effect."}},{"id":"PH-H3982-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Whenever necessary to carry out the objectives of this Act, the Secretary of Justice may, with the approval of the Supreme Court and for a period of not more than three months, assign any Circuit Judge to hold sessions in, and try cases pertaining to, another judicial district to assist in the disposition of criminal cases therein. No judge so assigned shall take cognizance of any case where any of the parties thereto objects and the objection is sustained by the Supreme Court."}},{"id":"PH-H3982-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"For administrative purposes, the Circuit Criminal Courts shall be under the supervision of the Department of Justice."}},{"id":"PH-H3982-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Such sums as may be necessary to carry out the provisions of this Act during the fiscal year 1966-1967, including the salaries of complementary personnel and those needed for operating expenses and equipment, are hereby appropriated out of any funds in the National Treasury not otherwise appropriated. Henceforth, the same shall be included in the annual general appropriations Act."}},{"id":"PH-H3982-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Circuit Criminal Courts to Try and Decide Certain Criminal Cases and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3983"] = {"id":"PH-H3983","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5180_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规定由省、市检察官及其助理以及州检察官或其助理进行统一初步调查制度的法案","en":"An Act Prescribing a Uniform System of Preliminary Investigation by Provincial and City Fiscals and Their Assistants, and by State Attorneys or Their Assistants","orig":"An Act Prescribing a Uniform System of Preliminary Investigation by Provincial and City Fiscals and Their Assistants, and by State Attorneys or Their Assistants"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5180","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5180_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3983-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Notwithstanding any provision of law to the contrary and except when an investigation has been conducted by a judge of first instance, city or municipal judge or other officer in accordance with law and the Rules of Court of the Philippines, no information for an offense cognizable by the Court of First Instance shall be filed by the provincial or city fiscal or his assistants or by a state prosecutor, without first conducting a preliminary investigation in the following manner:\n(a) All complaints shall be accompanied by statements of the complainant and his witnesses as well as other supporting documents. The statements of the complainant and his witnesses shall be sworn to before any fiscal or state prosecutor or before any government official authorized to administer oath. The officer administering the oath must certify that he has personally examined the affiants and that he is satisfied that they voluntarily executed and understood their affidavits.\n(b) If on the basis of the complainant's sworn statements and documents submitted, the investigating fiscal or state prosecutor finds no probable cause to conduct a preliminary investigation, he shall dismiss the case. If, probable cause is established by complainant's evidence, he shall notify the respondent by issuing a subpoena requiring him to submit his counter-affidavit and the affidavits of his witnesses, if any, and other supporting documents, within ten (10) days from receipt of such subpoena. If respondent cannot be subpoenaed, or if subpoenaed he does not appear before the investigating fiscal or state prosecutor, the preliminary investigation shall proceed without him. To such subpoena shall be attached a copy of the complaint, the sworn statements and other documents submitted. Other evidence submitted shall be made available for examination of the respondent or his counsel. The statements of the respondent and his witnesses shall also be sworn to before any fiscal or state prosecutor or before any government official authorized to administer oath and with the same certificate as above-mentioned. The respondent shall furnish the complainant copies of his counter affidavits and other supporting documents.\n(c) If a prima facie case is established by the evidence, the investigating fiscal or state prosecutor shall immediately file the corresponding information in court. If he finds that there is no prima facie case, he shall dismiss the case unless he believes there are matters to be clarified in which case he may profound clarificatory questions to the parties or their witnesses affording both parties opportunity to be present but without right to examine or cross-examine. If the parties or their counsel so desire, they may submit questions to the fiscal which the latter may in his discretion propound to the parties concerned.\n(d) The preliminary investigation shall proceed without need of requiring the parties and their witnesses to reaffirm their respective statements before the investigating fiscal or state prosecutor. Thereafter, he shall resolve the case within ten (10) days from its termination, furnishings the parties copies of his resolution stating briefly the findings of facts and the law supporting his action.\nThe fiscal or state prosecutor shall certify under oath in the information to be filed by him that he has examined the complainant and his witnesses, that on the basis of the sworn statements and other evidence submitted before him there is reasonable ground to believe that a crime has been committed and that the accused is probably guilty thereof, that the accused was informed of the complaint and of the evidence submitted against him and that he was given an opportunity to submit controverting evidence; Provided , That no assistant fiscal or state prosecutor may file an information or dismiss a case except with the prior authority or approval of the provincial or city fiscal or Chief State Prosecutor; Provided, further , That where an assistant fiscal or state prosecutor who has investigated the case, recommends the dismissal of the case but his findings are reversed by the Provincial or City Fiscal or by the Chief State Prosecutor, as the case may be, on the ground that a prima facie case exists, the Provincial or City Fiscal or the Chief State Prosecutor may, by himself, and on the basis of the same sworn statements and evidence submitted, file the information against the respondent, or direct any other assistant fiscal or state prosecutor to do so, without conducting another preliminary investigation; Provided, finally , That where the resolution of the Provincial or City Fiscal or the Chief State Prosecutor is, upon review, reversed by the Secretary of Justice, the latter may, where he finds that no prima facie case exists, authorized and direct the investigating fiscal concerned or any other fiscal or state prosecutor to cause or move for the dismissal of the case, or, were he finds a prima facie case, to cause the filing of an information in court against the respondent, based on the same sworn statements or evidence submitted without the necessity of conducting another preliminary investigation."}},{"id":"PH-H3983-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The provisions of Section fifteen, Rule 112, of the New Rules of Court of the Philippines, shall be observed in the investigations of persons in custody."}},{"id":"PH-H3983-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws or parts thereof, provisions of city charters, rules and regulations contrary to the provisions of this Act are hereby repealed."}},{"id":"PH-H3983-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, September 8, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prescribing a Uniform System of Preliminary Investigation by Provincial and City Fiscals and Their Assistants, and by State Attorneys or Their Assistants","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3984"] = {"id":"PH-H3984","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5181_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定永久居留与互惠为在菲律宾从事任何专业考试或登记的资格条件的法案","en":"An Act Prescribing Permanent Residence and Reciprocity as Qualifications for Any Examination or Registration for the Practice of Any Profession in the Philippines","orig":"An Act Prescribing Permanent Residence and Reciprocity as Qualifications for Any Examination or Registration for the Practice of Any Profession in the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5181","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5181_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3984-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No person shall be allowed to practice any profession in the Philippines unless he has complied with the existing laws and regulations, is a permanent resident therein for at least three years, and, if he is an alien, the country of which he is a subject or citizen permits Filipinos to practice their respective professions within its territories: Provided , That the practice of said professions is not limited by law to citizens of the Philippines: Provided, further , That Filipinos who became American nationals by reason of service in the Armed Forces of the United States during the Second World War and aliens who were admitted into the practice of their profession before July 4, 1946 shall be exempted from the restriction provided herein."}},{"id":"PH-H3984-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prescribing Permanent Residence and Reciprocity as Qualifications for Any Examination or Registration for the Practice of Any Profession in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3985"] = {"id":"PH-H3985","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5182_1967.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订西班牙语强制教学法律，废止经第 1881 号共和国法修正的第 709 号共和国法并为其他目的","en":"An Act to Revise the Laws on Compulsory Teaching of Spanish, Repealing Republic Act Numbered Seven Hundred Nine, as Amended by Republic Act Numbered Eighteen Hundred Eighty-One, and for Other Purposes","orig":"An Act to Revise the Laws on Compulsory Teaching of Spanish, Repealing Republic Act Numbered Seven Hundred Nine, as Amended by Republic Act Numbered Eighteen Hundred Eighty-One, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5182","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5182_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3985-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The teaching of Spanish is hereby declared obligatory in all the universities and colleges, public and private, and all students shall be required to complete twelve units at least, in the said subject: Provided, That students enrolled in liberal arts and education majoring in Spanish shall be required to complete at least twenty-four units of Spanish without increasing the number of years required at present for the completion, of such courses: Provided, However, That this is without prejudice to the authority of the Board of National Education to require, in consideration of the particular relevance and importance of Spanish, additional units for such other courses as it may, in the exercise of its discretion, determine."}},{"id":"PH-H3985-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"After nine units of Spanish shall have been completed, the remaining units exceeding nine must include the teaching of selected writings in their original Spanish versions by renowned Filipino heroes, scholars, writers, and poets, especially Rizal and Mabini. Spanish shall be optional for foreign students."}},{"id":"PH-H3985-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall take immediate steps to carry out the provisions of this Act, including the selection upon recommendation of the Board of National Education of the writings mentioned in Section 2 hereof and shall promulgate such rules and regulations as may be necessary to put this Act into effect."}},{"id":"PH-H3985-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Republic Act Numbered seven hundred nine, as amended by Republic Act Numbered eighteen hundred eighty-one, as well as provisions of existing laws which are inconsistent with this Act, are hereby repealed."}},{"id":"PH-H3985-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect at the beginning of the school year next following its approval.\nApproved: September 8, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Revise the Laws on Compulsory Teaching of Spanish, Repealing Republic Act Numbered Seven Hundred Nine, as Amended by Republic Act Numbered Eighteen Hundred Eighty-One, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3986"] = {"id":"PH-H3986","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5183_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规范向政府拥有或控制的公司、企业、机构或市政公司供应或由其采购材料、设备、货物与商品的合同授予，并规定违反行为处罚的法案","en":"An Act Regulating the Award of Contracts for the Supply to, or Procurement By, Any Government-Owned or Controlled Corporation, Company, Agency or Municipal Corporation of Materials, Equipment, Goods and Commodities, and Providing Penalty for the Violation Thereof","orig":"An Act Regulating the Award of Contracts for the Supply to, or Procurement By, Any Government-Owned or Controlled Corporation, Company, Agency or Municipal Corporation of Materials, Equipment, Goods and Commodities, and Providing Penalty for the Violation Thereof"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 5183","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5183_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3986-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No contract either through a public bidding or negotiated contract for the supply to, or procurement by, any government-owned or controlled corporation, company, agency or municipal corporation of materials, equipment, goods and commodities shall be awarded to any contractor or bidder who is not a citizen of the Philippines or which is not a corporation or association at least sixty percent of the capital of which is owned by Filipino citizens, except, as to a citizen, corporation or association of a country the laws or regulations of which grant similar rights or privileges to citizens of the Philippines. In the latter case the Flag Law shall continue to be applicable."}},{"id":"PH-H3986-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any violation of this Act shall be punished with a fine of not less than five thousand pesos and not more than ten thousand pesos and imprisonment of not less than two years and not more than four years. If the violation is committed by a corporation or association, the penalty shall be imposed upon the president, director or directors, managers, managing partner, or other official thereof responsible for such violation. Any alien violating or responsible for the violation of this Act shall, upon completion of the service of sentence, be deported without any further proceedings on the part of the Deportation Board. Any government official or employee who violates this Act, shall, in addition to the penalty which may be imposed upon him as principal, be temporarily or perpetually disqualified from holding any public office."}},{"id":"PH-H3986-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any law or parts of laws inconsistent herewith are hereby repealed."}},{"id":"PH-H3986-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Regulating the Award of Contracts for the Supply to, or Procurement By, Any Government-Owned or Controlled Corporation, Company, Agency or Municipal Corporation of Materials, Equipment, Goods and Commodities, and Providing Penalty for the Violation Thereof","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3987"] = {"id":"PH-H3987","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5184_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为司法部检察司增设检察官，扩充并重组其检察人员编制并为其他目的法案","en":"An Act Providing for Additional Prosecutors in the Prosecution Division of the Department of Justice, Enlarging and Reorganizing its Prosecution Staff, and for Other Purposes","orig":"An Act Providing for Additional Prosecutors in the Prosecution Division of the Department of Justice, Enlarging and Reorganizing its Prosecution Staff, and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5184","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5184_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3987-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one, two, two-A and two-B of Republic Act Numbered Three thousand seven hundred eighty-three, as amended and/or inserted by Republic Act Numbered Four thousand one hundred and forty, are hereby repealed and in lieu thereof the following sections are enacted:\n\"Sec. 1. The state prosecutors and the prosecuting and other attorneys in the Prosecution Division and Deportation Board, as provided by existing laws, are hereby merged into one prosecution service which shall be known as the Prosecution Staff of the Department of Justice. The said staff, as enlarged by this Act, shall have one chief, to be known as Chief State Prosecutor, three Assistant Chief State Prosecutors, and the following:\n\"(a) Six senior state prosecutors, each of whom shall receive an annual salary of P800.00 less than that herein provided for the Assistant Chief State Prosecutor;\n\"(b) Six senior state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(c) Six state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(d) Six state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(e) Six state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(f) Ten state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(g) Ten state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph;\n\"(h) Sixteen district state prosecutors, each at P600.00 less than that provided for in the next preceding paragraph; and \"(i) Two prosecuting attorneys, each at 1,200.00 less than that provided for in the next preceding paragraph.\n\"Sec. 2. The Chief State Prosecutor, the Assistant Chief State prosecutors, the Senior State Prosecutors, the State Prosecutors, and the District State Prosecutors shall be appointed by the President of the Philippines with the consent of the Commission on Appointments: Provided , That each judicial district as organized under the provisions of Republic Act Numbered Two hundred ninety-six, otherwise known as the Judiciary Act of 1948, as amended, shall have one District State Prosecutor who shall be permanently appointed thereto: Provided, further , That the District State Prosecutors shall be under the supervision of the Chief of State Prosecutor.\n\"The qualifications of the Chief State Prosecutor and the Assistant Chief State Prosecutors shall be the same as those of a Judge of the Court of First Instance and their salaries are hereby fixed at P19,000.00 each per annum. The qualifications and rank of the Senior State Prosecutor, State Prosecutor or District State Prosecutor shall be the same as a provincial fiscal.\n\"Sec. 3. The Chief State Prosecutor, the Assistant Chief State Prosecutors, the Senior State Prosecutors, the State Prosecutors, the District State Prosecutors, as well as other prosecuting attorneys assigned in the interest of the public service to the Prosecution Staff, shall have the same powers as provincial or city fiscals as provided by law: Provided , That said prosecutors shall only assist or collaborate with the provincial or city fiscal, unless otherwise expressly directed and authorized by the Secretary of Justice.\n\"The Chief State Prosecutor, the Assistant Chief State Prosecutors, the Senior State Prosecutors, and the State Prosecutors shall also prosecute deportation cases, investigate administrative charges against fiscals, and perform such other duties as may be assigned to them by the Secretary of Justice in the interest of the Public Service.\n\"Sec. 4. The Prosecution Staff shall have the following complementary personnel:\n\"(a) One supervising administrative assistant at P8,400.00 per annum;\n\"(b) Three supervising senior stenographic reporters, each at P7,200.00 per annum;\n\"(c) Eight senior stenographic reporters, each at P6,600.00 per annum;\n\"(d) Twelve junior stenographic reporters, each at P6,000.00 per annum;\n\"(e) Sixteen district stenographic reporters, each at P5,400.00 per annum;\n\"(f) One secretary at P6,000.00 per annum;\n\"(g) One sheriff at P4,200.00 per annum;\n\"(h) One statistical aide at P4,800.00 per annum;\n\"(i) Two clerks each at P4,200.00 per annum; and \"(j) Two janitor-messengers, each at P3,600.00 per annum.\""}},{"id":"PH-H3987-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any provision of law to the contrary notwithstanding, the members of the Prosecution Staff and complementary personnel as hereinabove provided shall receive the salary rates provided for in this Act: Provided , That no prosecutor, attorney or employee of the merged prosecution services at the time of the approval of this Act shall, as a consequence of the operation of this Act, be removed or separated from the service except for cause as provided by law: Provided, further , That the Secretary of Justice shall determine and establish the respective positions, rank and salaries of the incumbent state prosecutors and personnel: Provided, further , That no incumbent prosecutor or personnel shall be demoted in rank and salary: Provided, finally , That the incumbent prosecutors, attorneys and personnel shall receive their salary adjustments without the need of any new appointment."}},{"id":"PH-H3987-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to such sums as may have been provided in the current Appropriations Act, there is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, such sums as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H3987-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Additional Prosecutors in the Prosecution Division of the Department of Justice, Enlarging and Reorganizing its Prosecution Staff, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3988"] = {"id":"PH-H3988","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5185_1967.html","fetchedAt":"2026-10-06","articleCount":26,"structureMode":"ARTICLE","title":{"zh":"授予地方政府更大自治权的法案","en":"An Act Granting Further Autonomous Powers to Local Governments","orig":"An Act Granting Further Autonomous Powers to Local Governments"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5185","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-12","completenessNote":"全文，共 26 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5185_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3988-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. This Act shall be known as the Decentralization Act of 1967."}},{"id":"PH-H3988-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. It is hereby declared to be the policy of the State to transform local governments gradually into effective instruments through which the people can in a most genuine fashion, govern themselves and work out their own destinies.\nIt is therefore, the purpose of this Act to grant to local governments greater freedom and ampler means to respond to the needs of their people and promote their prosperity and happiness and to effect a more equitable and systematic distribution of governmental powers and resources. To this end, local governments henceforth shall be entrusted with the performance of those functions that are more properly administered in the local level and shall be granted with as much autonomous powers and financial resources as are required in the more effective discharge of these responsibilities."}},{"id":"PH-H3988-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Additional Powers and Functions. The provincial and city governments are hereby empowered to undertake field agricultural extension work and rural health work whenever deemed to be necessary by the Provincial and Municipal Boards or City Councils to assist or supplement existing national programs or services in their respective areas of jurisdiction. These services shall be administered in accordance with the policies and programs formulated by the national offices concerned. The National Government shall render technical, financial and other assistance to local governments in connection with said services.\nTo enable the provincial and city governments to undertake the aforementioned functions, they shall retain the amounts heretofore contributed by provincial, city and municipal governments to the National Government for field agricultural extension and rural health work, which shall accrue to the general fund of the province.\nProvided , That upon the effectivity of this Act, all personnel performing the above services whose salaries are paid out of the amounts contributed by the provincial and municipal governments, shall be absorbed by the provinces or municipalities where they are regularly or presently assigned: Provided, however , That the personnel heretofore mentioned shall not be laid off as a consequence of the provision of this section, and shall forthwith be subject to civil service law, rules and regulations: And Provided, further , That in cases of subsequent vacancies the same shall be filled in accordance with the pertinent and applicable provisions of this Act.\nAs a result of the provisions of this section, the Budget Commissioner shall make the necessary and corresponding adjustments in the national budget."}},{"id":"PH-H3988-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appointment of Heads, Assistant Heads of Local Offices and Their Subordinates. The Provincial Assessor, Provincial Agriculturist and other heads of offices entirely paid out of provincial funds and their respective assistants shall, subject to civil service law, rules and regulations, be appointed by the Provincial Governor: Provided, however , That this section shall not apply to Judges, Auditors, Fiscals, Division Superintendents of Schools, Supervisors, Principals, Provincial Treasurers, Provincial Health Officers and District Engineers.\nThe City Assessor, City Agriculturist, City Chief of Police and City Chief of Fire Department and other heads of offices entirely paid out of city funds and their respective assistants or deputies shall, subject to civil service law, rules and regulations, be appointed by the City Mayor: Provided, however , That this section shall not apply to Judges, Auditors, Fiscals, City Superintendents of Schools, Supervisors, Principals, City Treasurers, City Health Officers and City Engineers.\nThe Municipal Chief of Police and Municipal Attorney and other heads of offices entirely paid out of municipal funds and their respective assistants or deputies shall, subject to civil service law, rules and regulations, be appointed by the Municipal Mayor: Provided, however , That this section shall not apply to Judges and Municipal Treasurers.\nIn cases of vacancies in the offices of heads and assistant heads of local offices, the governor or mayor shall fill them by appointment from a list of the five next ranking eligible and qualified persons as certified by the Civil Service Commissioner: Provided , That these five persons shall have stated beforehand that they will assume the position, if appointed.\nThe ranking shall be based on such factors as class of province, city or municipality where the vacancy occurs, seniority, efficiency rating, extraordinary qualifications and other supplementary criteria as may be prescribed by the Civil Service Commission.\nAll other employees, except teachers, paid out of provincial, city or municipal general funds, road and bridge funds, school funds, and other local funds shall, subject to civil service law, rules and regulations, be appointed by the Provincial Governor, City or Municipal Mayor upon recommendation of the office head concerned. Such recommendation shall be made within fifteen days after the existence of a vacancy, otherwise the recommendation of the office head concerned shall be deemed waived.\nUpon effectivity of this Act, all officials and other employees appointed by the local chief executive shall be paid entirely out of local funds.\nWithin thirty days after the existence of a vacancy, provided that funds are available as certified by the provincial, city or municipal treasurer concerned, the local chief executive concerned shall appoint a suitable person to fill such vacancy. In the case of a chief or assistant chief of a local office, appointments for such vacancies shall be submitted within the same period prescribed above.\nThe suspension, removal, transfer and other personnel action on the heads of offices and their other employees in provinces, cities and municipalities shall be subject to the provisions of civil service law, rules and regulations.\nThe maximum salary scales for officials and employees authorized under existing law for first class provinces, cities and municipalities may, subject to the proviso herein, also be applicable to officials and employees of all other lower class provinces, cities and municipalities, subject to availability of funds and observance of civil service law, rules and regulations: Provided, however , That an official or employee can be eligible for the salary scales of the next higher class province, city or municipality after every two years of continuous service."}},{"id":"PH-H3988-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Suspension and Removal of Elective Local Officials. Any provisions of law to the contrary notwithstanding, the suspension and removal of elective local officials shall be governed exclusively by the provisions of this section.\nThe grounds for suspension and removal of elective local officials are the following: (a) disloyalty to the Republic of the Philippines; (b) dishonesty; (c) oppression; and (d) misconduct in the office.\nWritten subscribed and sworn charges against any elective provincial and city official shall be preferred before the President of the Philippines, against any elective municipal official before the provincial governor or the secretary of the provincial board concerned; and against any elective barrio official before the municipal or city mayor or the municipal or city secretary concerned.\nWithin seven days after the charges are preferred, the President, Governor, or Mayor, as the case may be, or his duly authorized representative, as provided in the preceding paragraph, shall notify the respondent of such charges. The President, Provincial Board and City or Municipal Council, as the case may be, shall hear and investigate the truth or falsity of the charges within ten days after receipt of such notice: Provided , That no investigation shall commence or continue within ninety days immediately prior to an election. The preventive suspension of the respondent officer shall not extend beyond sixty days after the date of his suspension. At the expiration of sixty days, the suspended officer shall be reinstated in office without prejudice to the continuation of the proceedings against him until their completion, unless the delay in the decision of the case is due to the fault, neglect or request of the suspended officer, in which case, the time of delay shall not be counted in computing the time of suspension: Provided, however , That if the suspended officer shall have been found guilty as charged before the expiration of the thirty days, his suspension, in the case of municipal and barrio officials, may continue until the case is finally decided by the Provincial Board.\nThe respondent shall have full opportunity to appear and defend himself in person or by counsel, to confront and cross-examine the witnesses against him and to require the attendance of witnesses and the production of documentary evidence in his favor through the compulsory process of subpoena or subpoena duces tecum.\nWithin thirty days after the end of investigation, the President, Provincial Board, City or Municipal Council, as the case may be, shall render its decision in writing, stating clearly and distinctly the facts and the reasons for such decision and shall immediately furnish copies of the decision to the respondent and all interested parties: Provided , That the penalty of suspension shall not exceed the unexpired term of the respondent: Provided, further , That the penalty of suspension or removal shall not be a bar to the candidacy of the respondent so suspended or removed for any elective public office as long as he meets the qualifications so required for the office: And Provided, finally , That the decision shall not preclude the filing of criminal actions arising from the same charges as provided for under existing laws.\nIn case of appeals from decisions of suspension or removal, the provisions of existing laws shall continue to be applicable."}},{"id":"PH-H3988-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Prohibition Against Practice. A member of the Provincial Board or City or Municipal Council shall not appear as counsel before any court in any civil case wherein the province, city or municipality, as the case may be, is the adverse party: Provided, however , That no member of the Provincial Board shall so appear except in behalf of his province in any civil case wherein any city in the province is the adverse party whose voters are en-franchised to vote for provincial officials, nor shall such member of the Provincial Board or City or Municipal Council appear as counsel for the accused in any criminal case wherein an officer or employee of said province, city or municipality is accused of an offense committed in relation to the latter's office, nor shall he collect any fee for his appearance in any administrative proceedings before provincial, city or municipal agencies of the province, city or municipality, as the case may be, of which he is an elected official.\nThe provisions of this Section shall likewise apply to provincial governors and city and municipal mayors."}},{"id":"PH-H3988-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Succession to Office of Vice-Governor and Vice-Mayor. In case a vacancy occurs in the office of Vice- Governor or Vice-Mayor, the board or council member, as the case may be, who obtained the highest number of votes, or in cases of provinces, cities, or municipalities where the provincial, city or municipal board members are elected by districts, the highest percentage of total votes cast in the last election, shall succeed to the officer: Provided, however , That such member meets all the requirements for the position: Provided, further , That in case of a tie, the pertinent provisions of the Revised Election Code shall apply."}},{"id":"PH-H3988-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Filling of Special Vacancies in Local Legislative Bodies. Vacancy occurring in Board or Council as a consequence of the preceding Section shall be filled automatically by the Board or council member who obtained the second highest number of votes, or if the provincial, city or municipal board members are elected by districts, the second highest percentage of total votes cast in the last election. Succeeding vacancy or vacancies as a result of such succession shall be filled automatically by other members as ranked on the basis of the number of votes or percentage of votes received.\nVacancies occurring in the board or council created through death, resignation, permanent incapacity, removal from office or as a consequence of the preceding paragraph prior to sixty days of a presidential election shall be filled by special election coinciding with such presidential election. Any person so elected shall be last in the ranking of board or council members. If the vacancy occurs after such period, the President alone, in the case of elective provincial and city officials and the provincial governors in the case of elective municipal officials, shall appoint qualified person belonging to the political party or faction of the officer whom he is to replace, upon recommendation of the said political party or faction and who shall serve the unexpired term of the office: Provided , That in cities where councilors are elected by district, the qualified person shall come from the same district where the vacancy exists. Such appointment shall be made within fifteen days after the recommendation of the respective political party or faction has been received. In case of temporary vacancies, the provisions of existing laws shall continue to be applicable."}},{"id":"PH-H3988-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Filling of Elective Offices in Newly Created Provinces, Cities, Municipalities or Municipal Districts. Elective offices in any new province, city, or municipality or municipal district shall be filled by regular or special elections to coincide with the next regular presidential or local election: Provided , That if it is created within thirty days before a regular presidential or local election , the said vacancies shall be filled as hereinafter provided in the next succeeding section."}},{"id":"PH-H3988-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Filling of Elective Offices in Newly Classified Provinces, Cities, Municipalities or Municipal Districts. In the event of reclassification of provinces, cities or municipalities where additional members of the Provincial Board, and City or Municipal Board or Council are to be appointed, such additional members shall be appointed upon recommendation of the head of the Provincial, City or Municipal Chapter of the political party which obtained the largest total number of votes in the province, city or municipality, as the case may be, in the last preceding elections for local officials."}},{"id":"PH-H3988-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Actions of Provincial, Municipal and City Officials or Provincial Boards Declared Immediately Effective.\nI. The following actions of provincial officials or boards and councils, as provided for in the pertinent sections of the Revised Administrative Code shall take effect without the need of approval or direction from any official of the national government:\n(a) Permission for officials to absent themselves from the province under Section 2073;\n(b) Compensation for persons appointed to temporary services under Section 2077;\n(c) Payment of salary accruing pending suspension under Section 2079;\n(d) Functions of provincial treasurers, specifically as agent of the Philippine National Bank under Section 2089 (h);\n(e) Duties of elective members, specifically their performance of ministerial duties under Section 2096;\n(f) Minutes of meetings of provincial boards under Section 2100;\n(g) Purchase or maintenance of draft animals for breeding purpose under Section 2105 (b);\n(h) Powers enumerated in Section 2106, except letters (a) and (f);\n(i) Conventions of mayors under Section 2108;\n(j) Deposit of surplus funds under Section 2110;\n(k) Dis-establishment of the Exhibition Fund under Section 2112;\n(l) Providing and maintaining wharves, piers and docks under Section 2113 (b);\n(m) Subsidizing or acquiring, operating and maintaining means of water transportation under Sections 2113 (c) and 2115;\n(n) Expenditures from the Non-Christian Inhabitants' Fund under Section 2114;\n(o) Loans from municipal funds for permanent public works and school purposes under Section 2117;\n(p) Restriction upon limit of disbursement under Section 2122;\n(q) Designation of provincial toll roads, bridges and ferries and fixing their rates under Section 2131;\n(r) Collection and application of tolls under Section 2132;\n(s) Establishment of a subprovincial treasury under Section 2141;\n(t) Settling of municipal boundary disputes within the same province only under Section 2167;\n(u) Fixing of salaries of officials in capital of a province under Section 2184;\n(v) Additional compensation for treasurer under Section 2186;\n(w) Passing by provincial board on legality of municipal proceedings under Section 2233.\nII. The following actions by municipal officials or municipal councils, as provided for in the pertinent sections of the Revised Administrative Code shall take effect without the need of approval or direction from any official of the national government: Provided , That such actions shall be subject to approval or direction by the Provincial Board:\n(a) Authority to close thoroughfare under Section 2246;\n(b) Aid to national and provincial charitable institutions under Section 2248;\n(c) Appropriations for exhibition purposes under Section 2293;\n(d) Letting of municipal ferry, market or slaughterhouse to highest bidder under Section 2319.\nIII. The provincial, city and municipal budgets shall become effective upon the approval of the same by the respective provincial boards, city councils or municipal boards of municipalities, if the same were approved in compliance with the provisions of Republic Act Numbered Twenty-two hundred and sixty-four, and for this purpose the provisions of Republic Act Numbered Forty-four hundred and seventy-seven inconsistent with the provisions of this section or of Republic Act Numbered Twenty-two hundred and sixty four are hereby repealed or modified accordingly.\nAll special funds except the road and bridge fund and the public permanent improvement funds to the local governments are hereby abolished and all moneys accruing to the local treasuries by operation of existing laws which are hereby classified as local income shall be consolidated into one general fund and shall be available for local purposes upon appropriation by the local legislative bodies: Provided , That the appropriations for the operation and maintenance of schools, for health and sanitation, and for maintenance, repair and construction of roads and bridges shall not be less than the amounts received from tuition fees, municipal aids for health and sanitation purposes and the manufactured oils allotment and motor vehicle allotment, respectively: Provided, further , That national aids and proceeds from loans and bond issues and other contributions for specific purposes shall be appropriated and spent only for the purpose for which the same have been obtained.\nIV. The pertinent sections of the charters of cities are hereby amended so as to declare the actions of city officials, or city boards or councils similar to those actions enumerated above effective without the need of approval or direction from any official of the national government."}},{"id":"PH-H3988-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Duties and Powers of Local Chief Executives Not to be Subject to Direction or Review by any National Official. The following duties and powers of the provincial governors, city mayors, and other local chief executives, where they are authorized by law shall not be subject to direction or review by any national official:\n(a) Initiation of any appropriate criminal action or proceeding to draw the attention of the proper superior officer to the dereliction of the official or employee involved;\n(b) Approval of commutation of vacation, sick and maternity leaves and of trips outside the city or province of employee appointed by him, under Section 286 of the Revised Administrative Code;\n(c) Authorizing payment of medical attendance, necessary transportation, subsistence, hospital fees of injured employees appointed by him and absence in such cases shall not be charged against any leave credit, under Section 699 of the Revised Administrative Code;\n(d) Approval of the commutation of the transportation allowances of chiefs of offices upon authority of the board or councils as authorized by law; and\n(e) Attendance in national conventions or similar meetings of local chief executives as provided by law."}},{"id":"PH-H3988-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Increase in Regular Allotment. The allotment share of provinces and cities as provided for in the penultimate paragraph of Section eight, Commonwealth Act Numbered Five hundred eighty-six, as amended by Republic Act Numbered Seven hundred eighty-one, is hereby increased from ten to thirteen per centum and the allotment share of municipalities exclusive of cities as provided for in the same Code is hereby increased from two to four per centum, provisions of existing laws to the contrary notwithstanding. The basis of the allotment shall be the collections during the preceding fiscal year, to be distributed among provinces, cities and municipalities as follows: (a) seventy per centum on the basis of population as shown by the latest official census, and (b) thirty per centum in proportion to the land area."}},{"id":"PH-H3988-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Retention, Release and Adjustment of Regular Internal Revenue Allotment. Within five days after the end of each month, the treasury field cashiers to whom all collection agents shall remit all their collections in each province shall retain from the internal revenue collections accruing to the General Fund and remit to the Provincial Treasurer an amount equivalent to one-twelfth of the predetermined annual internal revenue regular allotment of the province and municipalities under it, and to the city treasurer an amount equivalent to one-twelfth of the pre-determined annual internal revenue regular allotment of the city: Provided , That in provinces where there are no treasury field cashiers, such personnel shall be appointed. In case collections are remitted directly to the National Treasurer, as in Manila and suburbs, he shall remit the corresponding share to the city or provincial treasurer concerned within the same period. The allotment of municipalities within each province shall be distributed by the Provincial Treasurer concerned within five days after receipt thereof.\nWithin ten days after the end of each month, the city or provincial treasurer shall render a report to the Commissioner of Internal Revenue showing the corresponding amount received by the City or the respective amounts retained by the province and released to the municipalities for the preceding month.\nIn cases where the monthly collections are not sufficient to cover the regular allotment of a province, city or municipality, the corresponding balances shall be released by the Bureau of Internal Revenue within thirty days after the expiration of every quarter to the Provincial Treasurer concerned in case of a province or municipality, and to the city treasurer, in case of a city. The corresponding balance for municipalities shall be released by the Provincial Treasurer concerned within five days after receipt thereof.\nThe Secretary of Finance shall promulgate the rules and regulations for the proper implementation of this section."}},{"id":"PH-H3988-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Apportionment of Income Tax Withheld from Wages. The net proceeds in every fiscal year representing the gross collection of income tax withheld from wages under Supplement (A) of Title two of the National Internal Revenue Code, as amended by Republic Act Numbered Five hundred ninety, minus the refund thereof authorized in the same fiscal year, shall, for purposes of the excess income tax allotments, be credited equally among municipalities."}},{"id":"PH-H3988-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Release of Share of Provinces, Cities and Municipalities from the Highway Special Fund. Within thirty days after the end of every quarter, all shares of provinces, cities and municipalities from the Highway Special Fund, to which they are entitled under Republic Act Numbered Nine hundred seventeen, shall be released by the Bureau of Public Highways to the respective local treasurers: Provided , That the provinces and cities shall continue to appropriate the counterpart funds and no releases shall be made unless counterpart funds are provided by the local government where required: Provided, further , That the same shall not be used for purposes other than those for which such funds were released: Provided , still further , That no road shall be declared as a national aid road by the provincial board and city or municipal board council unless it shall form part of the integrated national road system: Provided, finally , That the Secretary of Public Works and Communications shall prescribe standards in the construction and improvement of road and highway projects."}},{"id":"PH-H3988-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Release of Other Funds. Within ten days after the end of each month, the share of provinces and cities from the gross receipts of sweepstakes, horse races and lotteries, as provided in Republic Act Numbered Eleven hundred sixty-nine, shall be released to the provincial and city treasurers.\nIt shall be unlawful for any public officer or employee concerned to withhold, or cause the withholding of any fund apportionable under this section."}},{"id":"PH-H3988-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Creation of Position of Provincial Engineer and City Public Works Supervisor. To enable the provincial governments to administer directly public works and public highways projects which are financed out of local funds, the positions of Provincial Engineer and City Public Works Supervisor may be created and such officials shall be appointed in such manner as is provided for under Section four of this Act: Provided , That the present Public Works District Engineer and Highway District Engineer shall continue to undertake public works and public highways projects financed out of national funds: And Provided, further , That the functions hitherto performed by the District Engineer or District Highway Engineer, in undertaking public works and public highways projects financed out of local funds shall be transferred to local engineer."}},{"id":"PH-H3988-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Creation of positions of Provincial Attorney and City Legal Officer. To enable the provincial and city governments to avail themselves of the full time and trusted services of legal officers, the positions of provincial attorney and city legal officer may be created and such officials shall be appointed in such manner as is provided for under Section four of this Act. For this purpose the functions hitherto performed by the provincial and city fiscals in serving as legal adviser and legal officer for civil cases of the province and city shall be transferred to the provincial attorney and city legal officer, respectively."}},{"id":"PH-H3988-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Creation of Municipality or Municipal District. A Municipality or municipal district shall be created and its boundaries modified only by an Act of Congress. For this purpose, Section sixty-eight of the Revised Administrative Code, as amended is hereby repealed."}},{"id":"PH-H3988-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Joint Local Government Reform Commission. There is hereby created a Joint Local Government Reform Commission to be composed of three Senators, two should be from the majority party and one from the minority party, to be designated by the President of the Senate; three Congressmen, two should be from the majority party and one from the minority party, to be designated by the Speaker of the House of Representatives; and three other members to be appointed by the President of the Philippines. The members shall elect a chairman from among themselves.\nThe Commission shall have the following duties and responsibilities:\n(a) To conduct continuing studies on the appropriate role of local governments as autonomous agencies in the administration of governmental services; and\n(b) To prepare a local government code to consist of a Provincial Government Law, a Municipal Government Law, a Barrio Law and a uniform charter for Chartered Cities to be submitted to Congress.\nThe Commission shall be assisted by a Technical Staff which shall be headed by an Executive Director and an Assistant Executive Director. All personnel shall be appointed by the Chairman subject to Civil Service Law, rules and regulations.\nThe amount of two hundred and fifty thousand pesos or such amount thereof as may be necessary is hereby appropriated from any fund of the national treasury not otherwise appropriated for the operation of the Commission during the fiscal year ending June thirty, nineteen hundred sixty-eight. Such sums as may be necessary for the operating expenses of the commission in succeeding fiscal years shall be included in the annual general appropriations Act."}},{"id":"PH-H3988-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Penalties. (a) Any public officer committing any act or omission in violation of Sections six, eight, fourteen, sixteen, seventeen and twenty-three of this Act shall be punished with imprisonment of not less than six months nor more than one year or a fine of not less than one nor more than two thousand pesos or both at the discretion of the Court. (b) Any public officer violating any provision of Section four and Section twenty-three of this Act shall be punished with the same penalty prescribed above: Provided , That said violation proven in a proper administrative proceeding constitute misconduct in office and shall be sufficient cause for suspension or dismissal of a public officer even if no criminal prosecution is instituted against him: Provided, finally , That he shall also suffer perpetual disqualification to hold any public office."}},{"id":"PH-H3988-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Rights, Benefits and Privileges Maintained. Nothing in this Act, shall be construed as depriving any government official or employee of his right to continue to hold office or withdrawing or reducing his benefits and privileges as provided for under existing law.\nImplied power of a province, a city or municipality shall be liberally construed in its favor. Any fair and reasonable doubt as to the existence of the power should be interpreted in favor of local government and it shall be presumed to exist. The general welfare clause shall be liberally interpreted in case of doubt so as to give more power to local governments in promoting the economic condition, social welfare and material progress of the people in the community."}},{"id":"PH-H3988-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Separability Clause. If, for any reason, any section or provision of this Act shall be held to be unconstitutional or invalid, no other section or provision of this Act shall be affected thereby."}},{"id":"PH-H3988-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Repealing Clause. All laws and parts of law, including Republic Act Numbered Forty hundred and ninety-two and pertinent portions of city charters, which are inconsistent with the provisions of this Act are hereby repealed and/or modified accordingly: Provided , That rights already acquired and existing at the time of its passage shall not in any way be abridged, modified or affected: And Provided, further , That nothing herein contained shall be construed as depriving any province, city, municipality or municipal district of any power at present enjoyed or already exercised or done by it or as diminishing its autonomy.\nVested rights existing at the time of the promulgation of this law arising out of a contract between a province, city or municipality on one hand and a third party on the other, shall be governed by the original terms and provisions of the same, and in no case should this Act be interpreted to infringe existing rights."}},{"id":"PH-H3988-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Effectivity. This Act shall take effect upon its approval except Section four which shall take effect on January first, nineteen hundred sixty-eight, and Sections thirteen, fourteen, fifteen and sixteen which shall take effect on July first, nineteen hundred sixty-eight.\nApproved: September 12, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Further Autonomous Powers to Local Governments","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3989"] = {"id":"PH-H3989","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5186_1967.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"规定菲律宾投资激励与保障、设立投资委员会、为此拨付必要款项并为其他目的法案","en":"An Act Prescribing Incentives and Guarantees to Investments in the Philippines, Creating a Board of Investments, Appropriating the Necessary Funds Therefor and for Other Purposes","orig":"An Act Prescribing Incentives and Guarantees to Investments in the Philippines, Creating a Board of Investments, Appropriating the Necessary Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5186","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-16","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5186_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3989-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. This Act shall be known and cited as the Investment Incentives Act."}},{"id":"PH-H3989-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. To accelerate the sound development of the national economy in consonance with the principles and objectives of economic nationalism, and in pursuance of a planned, economically feasible and practicable dispersal of industries, under conditions which will encourage competition and discourage monopolies, it is hereby declared to be the policy of the state to encourage Filipino and foreign investments, as hereinafter set out, in projects to develop agricultural, mining and manufacturing industries which increase national income most at the least cost, increase exports, bring about greater economic stability, provide more opportunities for employment, raise the standards of living of the people, and provide for an equitable distribution of wealth. It is further declared to be the policy of the state to welcome and encourage foreign capital to establish pioneer enterprises that are capital intensive and would utilize a substantial amount of domestic raw materials, in joint venture with substantial Filipino capital, whenever available."}},{"id":"PH-H3989-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. For purposes of this Act:\n(a) \"Board\" shall mean the Board of Investments created under this Act.\n(b) \"Registered enterprise\" shall mean a corporation (1) incorporated, organized and existing under Philippine laws, (2) of which, except as provided in Section nineteen of this Act, at least sixty per cent of the capital stock outstanding and entitled to vote is owned and held by Philippine Nationals, and at least sixty per cent of the members of the Board of Directors are citizens of the Philippines, (3) engaged in a preferred area of investment, and (4) duly registered with the Board of investments, and (4) duly registered with the Board of Investments; Provided, however , That the term registered enterprise shall not include commercial banks, savings and mortgage banks, rural banks, savings and loan associations, building and loan associations, development banks, trust companies, investment banks, finance companies, brokers and dealers in securities, consumers cooperatives and credit unions, and other business organizations whose principal purpose or principal source of income is to receive deposits, lend or borrow money, buy and sell or otherwise deal, trade or invest in common or preferred stocks, debentures, bonds or other marketable instruments generally recognized as securities, or discharge other similar intermediary, trust or fiduciary functions; neither shall the term include business organizations whose exclusive or principal purpose is to provide services or buy goods and merchandise and resell the same in substantially the same form in which bought.\n(c) \"Technological assistance contracts\" shall mean contracts for: (1) the transfer, by license or otherwise, of patents, processes, formulas or other technological rights of foreign origin; and/or (2) foreign assistance concerning technical and factory management, design, planning, construction and similar matters.\n(d) \"Foreign loan\" shall mean any credit facility or financial assistance other than equity investment obtained by a registered enterprise from a source outside the Philippines and brought into the Philippines either in foreign exchange or in other assets, and registered with the Central Bank and the Board, which shall assess and appraise the assets other than foreign exchange representing the proceeds of the loan.\n(e) \"Foreign investments\" shall mean equity investment, owned by a non-Philippine National in a registered enterprise, made in the form of foreign exchange or other assets actually transferred to the Philippines and registered with the Central Bank and the Board, which shall assess and appraise the value of such assets other than foreign exchange.\n(f) \"Philippine National\" shall mean a citizen of the Philippines; or a partnership or association wholly owned by citizens of the Philippines; or a corporation organized under the laws of the Philippines of which at least sixty per cent of the capital stock outstanding and entitled to vote is owned and held by citizens of the Philippines; or a trustee of funds for pension or other employee retirement or separation benefits, where the trustee is a Philippine National and at least sixty per cent of the fund will accrue to the benefit of Philippine Nationals: Provided , That where a corporation and its non-Filipino stockholders own stock in a registered enterprise, at least sixty per cent of the capital stock outstanding and entitled to vote of both corporations must be owned and held by the citizens of the Philippines and at least sixty per cent of the members of the Board of Directors of both corporations must be citizens of the Philippines in order that the corporation shall be considered a Philippine National.\n(g) \"Preferred areas of investment\" shall mean the economic activities that the Board shall have declared as such in accordance with Section eighteen hereof.\n(h) \"Pioneer enterprise\" shall mean a registered enterprise (1) engaged in the manufacture, processing, or production, and not merely in the assembly or packaging, of goods, products, commodities or raw materials that have not been or are not being produced in the Philippines on a commercial scale or (2) which uses a design, formula, scheme, method, process or system of production or transformation of any element, substance or raw materials into another raw material or finished good which is new and untried in the Philippines: Provided , That the final product involves or will involve substantial use and processing of domestic raw materials, whenever available.\n(i) \"Measured capacity\" shall mean the estimated additional volume of production which the Board determines to be desirable in each preferred and pioneer area of investment, in order to supply the needs of the economy at reasonable prices, taking into account the export potential of the area. Measured capacity shall not be less than the amount by which the measurable market demand exceeds the existing productive capacity in said preferred and pioneer areas nor shall measured capacity be so much in excess of measurable market demand as to foster or encourage overcrowding in any such area. For export market industries, the Board shall base measured capacity on the availability of domestic raw materials after deducting the needs of the domestic market therefor. In no case shall measured capacity be construed so as to result in a monopoly in any preferred or pioneer area of investment.\n(j) \"Tax credit\" shall mean any of the credits against taxes extended to a registered enterprise by this Act, to evidence which a tax credit certificate shall be issued by the Bureau of Internal Revenue. Unless otherwise provided herein, the tax credit certificate may be used by the registered enterprise to pay taxes, duties, charges and fees due to the national government in connection with its registered operations. A tax credit certificate shall be non-transferable; it may be used by the registered enterprise only for as long as it enjoys the benefits and incentives provided for in this Act, but may not be used so as to result in a refund.\n(k) \"Investments Priorities Plan\" shall mean the plan prepared by the Board and approved by the President upon recommendation of the National Economic Council, which shall contain the analysis, synthesis, and projections of data collected by the Board from public and private sources, and which measures and indicates:\n(1) The existing and prospective demand for specific products and commodities, final and intermediate, in the light of the level and structure of income, production, trade, prices and relevant economic and technical factors;\n(2) The existing capacities for producing specific products and commodities;\n(3) The gaps between prospective demand and existing supply for specific products and commodities, and the additional production capacities that must be induced where such gaps exist;\n(4) The specific products and commodities, manufactured out of or with the use of domestic raw materials, the export of which should be encouraged;\n(5) The specific areas of economic activity to be declared preferred and pioneer areas of investment and the corresponding measured capacities thereof;\n(6) The capital investments necessary to bring such additional capacities into existence;\n(7) The raw material input requirements of the additional production capacities needed, and the sources thereof, whether domestic or imported;\n(8) The manpower requirements of existing and new industries;\n(9) The regions where such additional capacities can be located considering the presence of natural resources, labor, transport facilities, power, water supply, and the like;\n(10) The respective roles and responsibilities of the private sector and the government in bringing such additional capacities into existence;\n(11) The specific public works projects that need to be undertaken by the government and the capital investment required therefor, to make private investments in preferred and pioneer areas feasible;\n(12) The prospective impact of the projected investments on prices, the exchange rate and the balance of payments;\n(13) The changes in tariffs that would be required for the protection of industry during its infant state;\n(14) The minimum requirements for maintaining conditions of competition in any industry; and\n(15) Other similar or relevant factors which the Board considers desirable to include."}},{"id":"PH-H3989-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Basic Rights and Guarantees. All investors and enterprises are entitled to the basic rights and guarantees provided in the Constitution. Among other rights recognized by the Government of the Philippines are the following:\n(a) Repatriation of Investment. In the case of foreign investments, the right to repatriate the entire proceeds of the liquidation of the investment in the currency in which the investment was originally made and at the exchange rate prevailing at the time of repatriation, subject to the provisions of Section seventy-four of Republic Act Numbered Two hundred sixty-five.\n(b) Remittance of Earnings. In the case of foreign investments, the right to remit earnings from the investment in the currency in which the investment was originally made and at the exchange rate prevailing at the time of remittance, subject to the provisions of Section seventy- four of Republic Act Numbered Two hundred sixty-five.\n(c) Foreign Loans and Contracts. The right to remit at the exchange rate prevailing at the time of remittance such sums as may be necessary to meet the payments of interest and principal on foreign loans and foreign obligations arising from technological assistance contracts, subject to the provisions of Section seventy-four of Republic Act Numbered Two hundred sixty-five.\n(d) Freedom from Expropriation. There shall be no expropriation by the government of the property represented by investments or of the property of enterprises except for public use or in the interest of national welfare and defense and upon payment of just compensation. In such cases, foreign investors or enterprises shall have the right to remit sums received as compensation for the expropriated property in the currency in which the investment was originally made and at the exchange rate at the time of remittance, subject to the provisions of Section seventy-four of Republic Act Numbered Two hundred sixty-five.\n(e) Requisition of Investment. There shall be no requisition of the property represented by the investment or of the property of enterprises, except in the event of war or national emergency and only for the duration thereof. Just compensation shall be determined and paid either at the time of requisition or immediately after cessation of the state of war or national emergency. Payments received as compensation for the requisitioned property may be remitted in the currency in which the investment was originally made and at the exchange rate prevailing at the time of remittance, subject to the provisions of Section seventy-four of Republic act Numbered Two hundred sixty- five."}},{"id":"PH-H3989-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Incentives to Investors in a Registered Enterprise. An investor, with respect to his investment in a registered enterprise, shall be granted the following incentive benefits:\n(a) Protection of Patents and Other Proprietary Rights. The right to be protected from infringement of patents, trademarks, copyright, trade names, and other proprietary rights, where such patents, trade marks, copyright, trade names, and other proprietary rights have been registered with the Board and the appropriate agencies of the Government of the Philippines.\n(b) Capital Gains Tax Exemption. Exemption from income tax on that portion of the gains realized from the sale, disposition, or transfer of capital assets, as defined in Section thirty-four of the National Internal Revenue Code, that corresponds to the portion of the proceeds of the sale that is invested in new issues of capital stock of a registered enterprise within six months from the date the gains were realized: Provided , (1) that the said date, disposition or transfer and the investment of the proceeds thereof have been registered with the Board and the Bureau of Internal Revenue; and (2) that the shares of stock representing the investment are not disposed of, transferred, assigned, or conveyed for a period of five years from the date the investment was made. If such shares of stock are disposed of within the said person of five (5) years, all taxes due on the gains realized from the original transfer, sale or disposition of the capital assets shall immediately become due and payable."}},{"id":"PH-H3989-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Incentives to Philippine Nationals Investing in Pioneer Enterprises. In addition to the incentives provided in the preceding sections, Philippine Nationals investing in a pioneer enterprise shall be granted the following incentives benefits:\n(a) Tax Allowance for Investments. An investment allowance to the extent of his actual investment, paid in cash or property shall be allowed as a deduction from his taxable income but not to exceed ten per cent thereof: Provided , (1) That the investment is made in a subscription of shares in the original and/or increased capital stock of a pioneer enterprise within seven years from the date of registration; (2) that the shares are held for a period of not less than three years and; (3) that the investment is registered with the Board. If the shares are disposed of within the said three year period, the tax payer shall lose the benefit of this deduction, his income tax liability shall be computed, and he shall pay whatever additional sum be due plus interest thereon, within thirty days from the date of disposition.\n(b) Capital Gains Tax Exemption. Exemption from income tax on the portion of the gains realized from the sale, disposition, or transfer of capital assets, as defined in Section thirty-four of the National Internal Revenue Code, that corresponds to the portion of the proceeds of the sale that is invested in new issues of capital stock of, or in the purchase of stock owned by foreigners in, pioneer enterprises, within six months from the date the gains were realized: Provided , (1) That such sale, disposition or transfer and the investment of the proceeds thereof are registered with the Board and the Bureau of Internal Revenue; and (2) that the shares of stock representing the investment are not disposed of, transferred, assigned or conveyed for a period of three (3) years from the date the investment was made. If said shares of stock are disposed of within the said period of three (3) years, all taxes due on the gains realized from the original transfer, sale or disposition of the capital assets shall immediately become due and payable.\n(c) Tax Exemption on Sale of Stock Dividends. Exemption from income tax on all gains realized from the sale, disposition, or transfer of stock dividends received from a pioneer enterprise: Provided , That the sale, disposition or transfer occurs within seven years from the date of registration of the enterprise."}},{"id":"PH-H3989-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Incentives to a Registered Enterprise. A registered enterprise, to the extent engaged in a preferred area of investment, shall be granted the following incentive benefits:\n(a) Deduction of Organizational and Pre-Operating Expenses. All capitalized organizational and pre-operating expenses attributable to the establishment of a registered enterprise may be deducted from its taxable income over a period of not more than ten years beginning with the month the enterprise begins operations, provided the taxpayer indicates the desired amortization period at the time of the filing of the income tax returns for the first taxable year. For the purpose of this provision, organizational and pre-operating expenses shall include expenses for pre-investment studies, start up costs, costs of initial recruitment and training, and similar expenses.\n(b) Accelerated Depreciation. At the option of the taxpayer and in accordance with the procedure established by the Bureau of Internal Revenue, fixed assets may be (1) depreciated to the extent of not more than twice as fast as normal rate of depreciation or depreciated at normal rate of depreciation if expected life is ten years or less; or (2) depreciated over any number of years between five years and expected life if the latter is more than ten (10) years; and the depreciation thereon allowed as a deduction from taxable income: Provided , That the taxpayer notifies the Bureau of Internal Revenue at the beginning of the depreciation period which depreciation rate allowed by this section will be used by it.\n(c) Net Operating Loss Carry-over. A net operating loss incurred in any of the first ten years of operations may be carried over as a deduction from taxable income for the six years immediately following the year of such loss. The entire amount of the loss shall be carried over to the first of the six taxable years following the loss, and any portion of such loss which exceeds the taxable income of such first year shall be deducted in like manner from the taxable income of the next remaining five years. The net operating loss shall be computed in accordance with the provisions of the National Internal Revenue Code, any provision of this Act to the contrary notwithstanding, except that income not taxable either in whole or in part under this or other laws shall be included in gross income.\n(d) Tax Exemption on Imported Capital Equipment. Within seven years from the date of registration of the enterprise, importation of machinery and equipment, and spare parts shipped with such machinery and equipment, shall not be subject to tariff duties and compensating tax: Provided , That said machinery, equipment and spare parts: (1) are not manufactured domestically in reasonable quantity and quality as reasonable prices; (2) are directly and actually needed and will be used exclusively by the registered enterprise in the manufacture of its products; (3) are covered by shipping documents in the name of the registered enterprise to whom the shipment will be delivered direct by customs authorities; (4) the prior approval of the Board was obtained by the registered enterprise before the importation of such machinery, equipment and spare parts; and (5) the registered enterprise chooses not to avail of the privileges granted by Republic Act Numbered Thirty-one hundred twenty-seven, as amended. If the registered enterprise sells, transfers, or disposes of these machinery, equipment and spare parts without the prior approval of the Board within five (5) years from the date of acquisition, the registered enterprise shall pay twice the amount of the tax exemption given it. However, the Board shall allow and approve the sale, transfer, or disposition of the said items within the said period of five (5) years if made: (1) to another registered enterprise; (2) for reasons of proven technical obsolescence; of (3) for purposes of replacement to improve and/or expand the operations of the enterprise.\n(e) Tax Credit on Domestic Capital Equipment. A tax credit equivalent to one hundred per cent (100%) of the value of the compensating tax and customs duties that would have been paid on the machinery, equipment and spare parts had these items been imported shall be given to the registered enterprise who purchases machinery, equipment and spare parts from a domestic manufacturer, and another tax credit equivalent to fifty per cent (50%) thereof shall be given to the said manufacturer: Provided , (1) That the said machinery, equipment and spare parts are directly and actually needed and will be used exclusively by the registered enterprise in the manufacture of its products; (2) that the prior approval of the Board was obtained by the local manufacturer concerned; and (3) that the sale is made within seven years from the date of registration of the registered enterprise. If the registered enterprise sells, transfers or disposes of these machinery, equipment and spare parts without the prior approval of the Board within five years from the date of acquisition, then it shall pay twice the amount of the tax credit given it. However, the Board shall allow and approve the sale, transfer, or disposition of the said items within the said period of five years if made (1) to another registered enterprise; (2) for reasons of proven technical obsolescence; or (3) for purposes of replacement to improve and/or expand the operations of the enterprise.\n(f) Tax Credit of Withholding Tax on Interest. A tax credit for taxes withheld on interest payments on foreign loans shall be given a registered enterprise when (1) no such credit is enjoyed by the lender-remittee in his country and (2) the registered enterprise has assumed the liability for payment of the tax due from the lender-remittee.\n(g) Employment of Foreign Nationals. Subject to the provisions of Section twenty-nine of Commonwealth Act Numbered Six hundred thirteen, as amended, an enterprise may, within five years from registration, employ foreign nationals in supervisory, technical or advisory positions not in excess of five per centum of its total personnel in each such category: Provided , That in no case shall each employment exceed five years. The employment of foreign nationals after five years from registration, or within such five years but in excess of the proportion herein provided, shall be governed by Section twenty of Commonwealth Act Numbered Six hundred thirteen, as amended.\nForeign nationals under employment contract within the purview of this Act, their spouse and unmarried children under twenty-one years of age, who are not excluded by Section twenty-nine of Commonwealth Act Numbered Six hundred thirteen, shall be permitted to enter and reside in the Philippines during the period of employment of such foreign nationals.\nA registered enterprise shall train Filipinos in administrative, supervisory, and technical skills and shall submit annual reports on such training to the Board of Investments.\n(h) Deduction for Expansion Reinvestment. When a registered enterprise reinvests its undistributed profit or surplus by actual transfer thereof to the capital stock of the corporation for procurement of machinery, equipment and spare parts previously approved by the Board under Subsections \"d\" and \"e\" hereof or for the expansion of machinery and equipment used in production or for the construction of the buildings, improvements or other facilities for the installation of the said machinery and equipment, the amount so reinvested shall be allowed as a deduction from its taxable income in the year in which such reinvestment was made: Provided , (1) That prior approval by the Board of such reinvestment was obtained by the registered enterprise planning such reinvestment, and (2) that the registered enterprise does not reduce its capital stock represented by the reinvestment within seven years from the date such reinvestment was made. In the event the registered enterprise does not order the machinery and equipment within two (2) years from the date the reinvestment was made or reduces its capital stock represented by the reinvestment within a period of seven years from the date of reinvestment, a recomputation of the income tax liability therefor shall be made for the period when the deduction was made, and the proper taxes shall be assessed and paid with interest.\n(i) Anti-Dumping Protection. Upon recommendation of the Board, made after notice and hearing, the President shall issue a directive banning for a limited period the importation of goods or commodities which, as provided in Section three hundred one (a) of the Tariff and Customs Code of the Philippines, unfairly or unnecessarily complete with those produced by registered enterprises: Provided , (1) That the Board certifies to the satisfactory quality of the goods or commodities produced or manufactured by the registered enterprises; and (2) that the enterprises agree not to increase the price of these goods or commodities during this period, unless for good cause, the Board allows such an increase.\n(j) Protection from Government Competition. No agency or instrumentality of the government shall import, or allow the importation tax and duty free of products or items that are being produced or manufactured by registered enterprise, except when the President determines that the national interest so requires or when international commitments require international competitive bidding."}},{"id":"PH-H3989-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Incentives to a Pioneer Enterprise. In addition to the incentives provided in the preceding section, pioneer enterprises shall be granted the following incentives benefits:\n(a) Tax Exemptions. Exemptions from all taxes under the National Internal Revenue Code, except income tax, to the following extent:\n(1) One hundred per cent up to December 31, 1972;\n(2) Seventy-five per cent up to December 31, 1975;\n(3) Fifty per cent up to December 31, 1977;\n(4) Twenty per cent up to December 31, 1979;\n(5) Ten per cent up to December 31, 1981;\n(b) Employment of Foreign Nationals. Subject to the provisions of Section twenty nine of Commonwealth Act Numbered Six hundred thirteen, as amended, to employ and bring into the Philippines foreign nationals under the following conditions:\n(1) That all such foreign nationals shall register with the Board;\n(2) That the employment of all foreign nationals shall cease and they shall be repatriated five years after the registered enterprise has begun operating: Provided , That when the majority of the capital stock of the pioneer enterprise is owned by foreign investors, the positions of president, treasurer and general manager, or their equivalents, may be retained by foreign nationals. In exceptional cases, the Board may allow employment of foreign nationals in other positions that cannot be filled by the Philippine nationals, but in such cases the limitations of Section seven paragraph (g) of this Act shall apply.\nForeign nationals under employment contract within the purview of this Act, their spouse and unmarried children under twenty-one years of age, who are not excluded by Section twenty-nine of Commonwealth Act Numbered Six hundred thirteen, shall be permitted to enter and reside in the Philippines during the period of employment of such foreign nationals.\n(c) Post-Operative Tariff Protection. Upon recommendation of the Board, the President, with or without the recommendation of the Tariff Commission or the National Economic Council, shall issue a certification that a pioneer industry shall be entitled to post-operative tariff protection to an extent not exceeding fifty per cent of the dutiable value of imported items similar to those being manufactured or produced by a pioneer enterprise, unless a higher rate or amount is provided for in the Tariff Code or pertinent laws. Said tariff shall take effect automatically upon certification by the Board that the pioneer enterprise is operating on a commercial scale: Provided , That said tariff, once operative, may be modified in accordance with Section four hundred one of the Tariff and Customs Code."}},{"id":"PH-H3989-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Special Export Incentives for Registered Enterprises. Registered enterprises shall be entitled to the following special incentives for exports of their completely finished products and commodities:\n(a) Double Deduction of Promotional Expenses. To deduct from taxable income twice the amount of the ordinary and necessary expenses incurred for the purpose of promoting the sale of their products abroad;\n(b) Double Deduction of Shipping Costs. To deduct from taxable income twice the amount of shipping freight incurred in connection with the export of their products, if the shipments are made in vessels of Philippine registry to their regular ports of call; and to deduct one hundred fifty per cent (150%) of the freight when shipments are made in vessels of foreign registry to a port which is not a regular port of call of Philippine vessels;\n(c) Special Tax Credit on Raw Materials. A tax credit equivalent to seven per cent (7%) of the total cost of the raw materials and supplies purchased by registered enterprises or an amount equivalent to the taxes actually paid by registered enterprises on said raw materials, whichever is higher, to the extent used in manufacturing exported products and commodities.\nBefore registered enterprises may avail themselves of the foregoing exports incentives benefits, the shall apply first with the Board, which shall approve the application upon proof: (1) that the enterprise proposes to engage in good faith in creating a market for its products abroad; (2) that the product to be exported is one included in the investment priorities plan as suitable for export, or if not so included that its export will not adversely affect the needs of the domestic market for the finished product to be exported or for the domestic raw materials used in its manufacture; (3) that the enterprise has or will set up an adequate accounting system to segregate revenues, purchases and expenses of its export market operations from those of its domestic market operations; and (4) that the exported products and commodities meet the standards of quality established by the Bureau of Standards or, in default thereof, by the Board."}},{"id":"PH-H3989-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Preference in Grant of Government Loans. Government financial institutions such as the Development Bank of the Philippines, Philippine National Bank, Government Service Insurance System, Social Security System, Land Bank, and such other government institutions as are now engaged or may hereafter engage in financing or investment operations shall, in accordance with and to the extent allowed by the enabling provisions of their respective charters or applicable laws, accord high priority to applications for financial assistance submitted by pioneer and other registered enterprises, whether such financial assistance be in the form of equity participation in preferred, common, or preferred convertible shares of stock, or in loans and guarantees, and shall facilitate the processing thereof and the release of the funds therefor. However, no financial assistance shall be extended under this section to any investor or enterprise that is not a Philippine National.\nThe above-mentioned financial institutions, to the extent allowed by their respective charters or applicable laws, shall contribute to the capital of a registered enterprise whenever the said contribution would enable the formation of pioneer or other registered enterprise with at least sixty per cent control by Philippine Nationals: Provided , That the capital contribution of the said financial institutions shall be limited to the amount that cannot be contributed by private Filipino investors, and shall in no case exceed thirty per cent of the total capitalization of the pioneer or other registered enterprises. The shares representing the contribution of the said financial institutions shall be offered for public sale to Philippine Nationals through all the members of a registered Philippine stock exchange.\nTo facilitate the implementation of the provisions of this Section, all the said financial institutions shall coordinate their financial assistance programs with each other, exchange relevant information about applicants and applications, and submit a monthly report to the Board showing the amount of funds available for financial assistance to pioneer or other registered enterprises. The Board shall recommend to the Board of Directors of each such financial institution what order of priority shall be given the applications of pioneer and other registered enterprises, or of applicants that propose to seek registration as such."}},{"id":"PH-H3989-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Private Financial Assistance. Any provision of existing laws to the contrary notwithstanding, the Insurance Commissioner is hereby authorized to allow insurance companies, under such rules and regulations as he may issue, to invest in new issues of stock of registered enterprises, notwithstanding that said enterprises may not have paid regular dividends, to the extent set out in section two hundred, paragraphs (c) and (f) of the Insurance Act, as amended: Provided , that said investments are diversified."}},{"id":"PH-H3989-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Loans for Investment. The Government Service Insurance System and the Social Security System shall extend to their respective members five-year loans at a rate of interest not to exceed six per cent per annum for the purchase of shares of stock in any registered enterprise: Provided , That (1) the shares so purchased shall be deposited in escrow with the lending institution for the full five-year term of the loan; partial releases of the shares shall, however, be allowed to the extent of the payment of amortization made therefor; (2) such loans shall be amortized in sixty equal monthly installments which shall be withheld by the employer from the monthly salary of the employee concerned and remitted to the lending institution by the employer; but any and all dividends earned by shares of stock while they are held in escrow shall be delivered to the employee; and (3) the maximum loan available to each employee in any one calendar year shall not exceed fifty per centum of the employee's annual gross income: Provided, further , That the total investment of the government financial institution concerned, consisting of its direct investment in the registered enterprise and the loans it has extended to its respective members which have been invested by the members in a registered enterprise, shall not be more than forty-nine per cent (49%) of the total capitalization of the registered enterprise in which the investments have been made."}},{"id":"PH-H3989-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Board of Investments. To carry out the purposes of this Act, there is hereby created a Board of Investments which shall be organized within sixty days after the approval of this Act, composed of five full-time members to be appointed by the President of the Philippines with the consent of the Commission on Appointments, from a list of nominees submitted by the Chamber of Commerce of the Philippines, the Chamber of Industries, Base Metals Producers Association, Gold Producers Association, Chamber of Agriculture and Natural Resources of the Philippines, the Bankers Association of the Philippines and other similar business organizations as well as from duly organized and existing labor confederations, federations and other organizations of national standing in the Philippines from which the President may request nominees: Provided , That each association shall submit a list of not less than three (3) but not more than five (5) nominees and that no association shall have more than one member in the Board at any particular time: And Provided, further , That the President may appoint as members of the Board qualified persons who have not been so nominated. The Board shall elect a Chairman from among themselves. The tenure of office of each member shall be six, (6) years: Provided, however , That the members of the Board first appointed shall hold office for two (2) years, three (3) years, four (4) years, five (5) years and six (6) years as fixed in their respective appointments: Provided, further , That upon the expiration of his term, a member shall serve as such until his successor shall have been appointed and qualified: Provided, finally , That no vacancy shall be filled except for the unexpired portion of any term, and that no one may be designated to be a member of the Board in an acting capacity, but all appointments shall be ad interim or permanent.\nFor administrative purposes, the Board shall be under the Office of the President of the Philippines."}},{"id":"PH-H3989-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Qualifications of Members of the Board. The members of the Board shall be citizens of the Philippines, at least thirty (30) years old, of good moral character, and of recognized competence in the field of economics, finance, banking, commerce, industry, agriculture, engineering, management, law or labor, such competence to be certified by the association making the nomination or by the association whose members belong to the same profession, calling or occupation as the person appointed. No member of the Board may be a candidate for any elective office during his incumbency and within four (4) years from the date he ceases to be a member of the Board: nor shall he during his incumbency and for a period of seven (7) years thereafter invest or have any financial interest, direct or indirect, in any enterprise registered during his incumbency, except where such interest was acquired by intestate succession or as a compulsory heir in a testate succession."}},{"id":"PH-H3989-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Compensation of the Chairman and Members of the Board. The Chairman shall receive an annual salary of fifty thousand pesos (P50,000.00) and a monthly commutable allowance of two thousand pesos (P2,000.00), and each member shall receive an annual salary of forty thousand (P40,000.00) and a monthly commutable allowance of one thousand five hundred pesos (P1,500.00)."}},{"id":"PH-H3989-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Powers and Duties of the Board. The Board shall meet as often as may be necessary, but not less than once a week on such day as it may fix. Notice of special meetings shall be given all members of the Board and proof of such notice shall be spread upon the minutes. The presence of three (3) members shall constitute a quorum; and the affirmative vote of three (3) members in a meeting validly held shall be necessary to exercise its powers and perform its duties, which shall be as follows:\n(a) Draw up annually an investments priorities plan in the manner prescribed in Section eighteen which shall be the basis for the implementation of this Act;\n(b) Promulgate such rules and regulations as may be necessary to implement the intent and provisions of this Act, which rules and regulations shall take effect thirty (30) days after their publications in two (2) newspapers of general circulation in the Philippines;\n(c) Process and approve, imposing such terms and conditions as it may deem necessary to promote the objectives of this Act, applications for registration under this Act, and issue the proper certificate of registration upon payment of the necessary fees, which shall not exceed two hundred pesos;\n(d) After due hearing, decide controversies concerning the implementation of this Act that may arise between registered enterprises or investors therein and government agencies, within thirty (30) days after the controversy has been submitted for decision: Provided , That the investor or the registered enterprise may appeal from the decision of the Board within fifteen (15) days from receipt thereof to the Court of First Instance of the City of Manila or of the city or province where the principal office of the registered enterprise is located, in the manner provided for by the Rules of Court in cases of this nature;\n(e) Recommend to the Commissioner of Immigration the entry into the Philippines for employment of foreign nationals as permitted in Sections seven and eight of this Act;\n(f) Periodically check and verify, either by inspection of the books or by requiring regular reports, the proportion of the participation of Philippine Nationals in a registered enterprise to ascertain compliance with its qualification to retain registration under this Act;\n(g) Periodically check and verify the compliance by registered enterprises with the provisions of this Act, with the rules and regulations promulgated under this Act and with the terms and conditions of registration:\n(h) After notice and hearing, cancel the registration or suspend the enjoyment of incentive benefits of any registered enterprise for (1) failure to maintain the qualifications required by this Act for registration or (2) for willful or grossly negligent violation of any provision of this Act, of the rules and regulations issued under this Act, or the terms and conditions of registration, or of laws for the protection of labor or of the consuming public: Provided , That the registered enterprise affected by the order of cancellation or suspension may appeal within fifteen (15) days from the receipt of the order to the Court of First Instance of the City of Manila or of the city or province where the principal office of the registered enterprise is located;\n(i) Appoint, discipline and remove, and determine the compensation of, its technical staff and other personnel: Provided , That, except as to the technical staff and such other positions as the Board may declare to be highly technical or primarily confidential, all positions in the Board are subject to the provisions of the Civil Service Law and Rules, but are exempt from the regulations of the Wage and Position Classification Office;\n(j) Prepare or contract for the preparation of feasibility and other pre-investment studies for pioneer areas either upon its own initiative or upon the request of Philippine Nationals who commit themselves to invest therein and show the capability of doing so, and upon condition that in no case shall the expenditure of the Board exceed one hundred twenty-five thousand pesos (P125,00) per study: Provided , That if the venture is implemented, then the amount advanced by the Board should be repaired within five (5) years from the date the commercial operation of said enterprise starts;\n(k) Within four (4) months after the close of the fiscal year, submit annual reports to the President and Congress, with copies to each member thereof, which shall cover its activities in the administration of this Act, including recommendations on investment policies; and\n(l) Generally, exercise all the powers necessary or incidental to attain the purposes of this Act."}},{"id":"PH-H3989-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Powers and Duties of the Chairman. The Chairman shall also be the Managing Head of the Board, and shall have the following powers and duties:\n(a) Prepare the agenda for the meetings of the Board and submit for its consideration and approval the policies and measures which he deems necessary and proper to carry out the provisions of this Act;\n(b) Manage the affairs of the Board subject to the policies of the Board;\n(c) Gather and compile statistical data required for the effective implementation of this Act;\n(d) Provide, through Philippine diplomatic missions, such information as may be of interest to prospective foreign investors;\n(e) Collate, analyze and compile pertinent information and studies concerning areas that have been or may be declared preferred or pioneer areas of investment;\n(f) Assist registered enterprises and prospective investors to have their papers processed with dispatch by all government offices, agencies, instrumentalities and financial institutions;\n(g) Act as liaison between investors seeking joint venture arrangements in particular areas of investment; and\n(h) Perform such other duties as may be assigned to him by the Board."}},{"id":"PH-H3989-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Preferred and Pioneer Areas of Investment. Within one hundred twenty (120) days after its organization and not later than the end of January of every year thereafter, the Board of Investments shall submit to the President, through the National Economic Council, an Investment Priorities Plan as defined in Section three, paragraph (k) of this Act.\nIn determining the preferred and pioneer areas of investment and their corresponding measured capacities, the Board shall determine which areas of investment best accomplish the policy declared in this Act, including those which will economically produce goods for domestic use in substitution for goods being imported in large quantities, and especially those which will process further and thereby increase the value of agricultural, mining and timber products already being produced for export or which will make products at costs low enough to be sold competitively in export markets. Any area of investment where an enterprise: (1) is engaged in the exportation of finished products completely processed and manufactured in the Philippines with at least seventy (70%) per cent of the peso value of its total raw material content being Philippine raw material; (2) is exporting more than fifty (50%) per cent of its total production; and (3) does not enjoy any preferential treatment arising from any agreement or arrangement between the Philippine government and the importing country; shall be considered a preferred area of investment and included in the Investment Priorities Plan.\nThe Board shall take into account all the following criteria:\n(a) The gaps between prospective demand and existing supply for specific products, commodities and services, and the additional production capacities that must be induced where such gaps exist;\n(b) The potential of such areas of investments for creating new markets both domestic and foreign, for domestic suppliers of raw materials and/or intermediate goods, or new sources of supply for domestic consumers of the products;\n(c) The potential of such areas of investment for creating productive employment, considering the necessity for the dispersal of industries in the country on a planned and balanced basis to the extent that is economically feasible and practicable;\n(d) The extent to which investment in such areas will integrate existing production facilities;\n(e) The amounts of import substitution or of new exports such areas of investment will promote;\n(f) The amount of capital normally needed thereby;\n(g) The nature of the risks, commercial or otherwise, which may be entailed;\n(h) The proportion of the required capital, raw material and labor inputs of indigenous origin;\n(i) The rate of profitability;\n(j) The rate of return to the economy;\n(k) The maintenance of competition; and\n(l) Such other criteria as the Board may adopt.\nConsidering the amount of investment capital which the Board may estimate to be available during any given year, the Board shall give priority to projects with the highest rates of return to the national economy. No project shall be included in the Investment Priorities Plan, nor declared a preferred area of investment, nor designated a pioneer area, unless it is shown to be economically, technically and financially sound after thorough investigation and analysis by the Board. If any of the areas declared preferred areas of investment, the Board may designate as pioneer areas the specific products and commodities that meet the requirements of Section three, paragraph (h) of this Act.\nThe National Economic Council, within sixty (60) days from receipt of the plan from the Board, shall evaluate and submit the same, with its recommendation on the entire plan or portions of it, to the President for his approval. If the National Economic Council fails to act on the plan within the said period of sixty (60) days, it shall automatically be submitted to the President for approval.\nUpon approval, the President shall proclaim the whole or part of such plan as in effect; or alternatively, return the whole or part of the plan to the Board of Investments for revision. Portions not returned to the Board of Investments shall be proclaimed in effect.\nUpon the effectivity of the plan or portions thereof, the President shall issue all necessary directives to all departments, bureaus, agencies, and instrumentalities of the government to ensure the implementation of the plan by the agencies concerned in a synchronized and integrated manner. No government body shall adopt any policy or take any course of action contrary to or inconsistent with the plan.\nThe Board of Investments may, after notice and public hearing, amend the whole or any part of the plan, alter any of the terms, of the declaration of an investment area, or the designation of measured capacities, or terminate the status of preference or pioneer: Provided , That in all such cases the procedures outlined in this section are observed to the extent that they are applicable. In no case, however, shall any amendment of the plan impair whatever rights may have already been legally vested in qualified enterprises which shall continue to enjoy such rights to the full extent allowed under this Act. The Board shall not accept applications in an area of investment prior to the approval of the same as a preferred or pioneer area by the President nor after approval of its deletion as a preferred or pioneer area of investment. Upon approval of the plan, in whole or in part, or upon approval of an amendment thereof, the plan or the amendment, specifying and declaring the preferred and pioneer areas of investment and their corresponding measured capacity shall be published in the Official Gazette and in at least two newspapers of general circulation, and all such areas shall be open for application until publication of an amendment or deletion thereof, or until the Board approves registration of enterprises which fill the measured capacity."}},{"id":"PH-H3989-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Qualification of Applicants. To be entitled to registration, an applicant must satisfy the Board that:\n(a) It possesses the qualifications prescribed for registered enterprises in Section three, paragraph (b) of this Act; or if it does not possess the required degree of ownership by Philippine Nationals, the following circumstances must be satisfactorily established:\n(1) That it is otherwise qualified under Section three, paragraph (b) of this Act;\n(2) That it proposes to engage in a pioneer project as defined in Section three, paragraph (h) of this Act which, considering the nature and extent of capital requirements, processes, technical skills and relative business risks involved, is in the opinion of the Board of such a nature that the available measured capacity thereof cannot be readily and adequately filled by Philippine Nationals;\n(3) That it obligates itself to attain the status of a Philippine National as defined in Section three, paragraph (f) of this Act by; (1) having its shares of stock listed with a Philippine stock exchange within ten (10) years from the date of registration; and (2) actually offering for sale the said shares to Philippine Nationals not later than the beginning of the eleventh year from the date of its registration. In any event, a sufficient number of shares must be disposed of within a period of twenty (20) years from the date of its registration to enable Philippine Nationals to hold and own at least sixty per cent (60%) of the capital stock outstanding and entitled to vote of said enterprise: Provided, however , That the Board may extend this period for another period not to exceed twenty years, subject to such conditions as it may impose in the national interest, and upon proof by the registered enterprise (1) that it has made a bona fide offer to sell the required number of shares to Philippine Nationals as required by this Section but Philippine Nationals have not bought the same; and (2) that it has not offered to buy and has not bought shares of stock from Philippine Nationals; or (3) that such other cause exists as the Board may deem sufficient to justify the extension of the period.\n(4) That the pioneer area it will engage in is one that is not within the activities reserved by the Constitution or other laws of the Philippines to Filipino citizens or corporations owned and controlled by Filipino citizens.\n(b) The enterprise is proposing to start and operate a preferred or pioneer project, or only a pioneer project in the case of non-Philippine enterprises, within a reasonable time to be fixed by the Board;\n(c) The enterprise is capable of operating on a sound and efficient basis and of contributing to the national development of the preferred or pioneer area in particular and of the national economy in general;\n(d) If the enterprise is engaged or proposes to engage in undertakings or activities other than preferred or pioneer projects in addition to the project mentioned in subsection (b) hereof, it has installed or undertake to install an accounting system adequate to identify the investments, revenues, costs, and profits or losses of each preferred or pioneer project undertaken by the enterprise separately from the aggregate investment, revenues, costs, and profits or losses of the whole enterprise or to establish a separate corporation for each preferred or pioneer project if the Board should so require to facilitate proper implementation of this Act.\nNotwithstanding the provisions of paragraphs (a) and (b) of this Section, if the measured capacity of any preferred, non-pioneer area is not filled within three years from the date of its declaration as a preferred, non-pioneer area, the Board shall allow enterprises not possessing the required percentage of Philippine ownership and control, but otherwise qualified, to be registered in such areas, under the conditions prescribed above for pioneer areas."}},{"id":"PH-H3989-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Application. Applications shall be recorded in a registration book and shall be processed in the order in which they are filed; and for this purpose the date appearing on the registration book and stamped on the application shall be considered the date of filing. The Board shall cease to register any enterprise in a preferred or pioneer area of investment when the measured capacity therein has been filled; but all enterprises registered within the measured capacity shall enjoy the status or preferred or pioneer enterprises, as the case may be. Where several qualified enterprises apply for registration with the Board but the total of their proposed combined production capacities exceeds the available measured capacity of the preferred or pioneer area of investment in which they are proposing to engage, the Board shall approve and register only those that can be accommodated within the available measured capacity and are better suited to achieve the objectives of this Act The Board shall base its choice on the following criteria:\n(a) The extent of ownership and control by Philippine Nationals of the enterprises;\n(b) The manner in which the enterprises are integrated, and the length of their experience in the preferred area of investment or in areas closely related to it;\n(c) The cost of factors and the economies of scale involved in their processes;\n(d) The amount of foreign exchange earned, used, or save in their operations;\n(e) The extent to which they employ labor, materials and other resources obtained from indigenous sources;\n(f) The amount of their equity, and the degree to which the ownership of such equity is spread out and diversified;\n(g) The extent to which they shall insure the maintenance of competition within the industry; and\n(h) The extent of public participation in the enterprise.\nIn making a choice between two or more enterprises applying for registration and proposing to produce identical or substantially identical products or commodities, both possessing the required degree of Filipino ownership and control, the Board shall give preference to projects that constitute an expansion of, or addition to or integration of existing facilities whenever these enjoy the advantages of lower costs and economies of scale over projects undertaken in isolation from technically related facilities; and other things being equal, the Board shall give preference to enterprises where the degree of ownership and control by Philippine Nationals is greater.\nNothing in this Section shall be construed to exclude any non-registered enterprises from freely engaging, within existing constitutional and statutory limitations, and without enjoying the incentives benefits provided in this Act, in any line of economic activity or endeavor that has been declared a preferred area of investment: Provided , that a non-Philippine National may engage, without incentives, in preferred areas of investment where the Philippine Nationals are already engaged only after three (3) years from the date of declaration of the area as preferred if the measured capacity has not been filled within the said period, except where such non-Philippine National shall engage, without incentives, in the manufacture of finished products primarily for export. The Board shall fix the percentage of production that must be exported by a non-Philippine National in order to be deemed to be engaged in manufacture primarily for export, which percentage shall not be less than seventy per cent (70%) of its total production.\nAny order or decision of the Board under this Section may be appealed within thirty (30) days from receipt of said order or decision to the National Economic Council. Upon failure on the part of the National Economic Council to act within the said period of ninety (90) days, the decision of the Board shall be deemed upheld. The Board or the enterprise applying for registration under this Act may appeal the decision of the National Economic Council to the President within thirty (30) days from its promulgation."}},{"id":"PH-H3989-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Certification of Registration. All enterprises registered under this Act shall be issued a certificate of registration under the seal of the Board of Investments and the signature of its chairman and/or such other officer or employee of the Board as it may empower and designate for the purpose. The certificate shall be in such form and style as the Board may determine, and shall state, among other matters:\n(a) The name of the registered enterprise;\n(b) The preferred area of investment in which the registered enterprise is proposing to engage;\n(c) The nature of the activity it is undertaking or proposing to undertake, whether preferred or pioneer, and the registered capacity of the enterprise; and\n(d) The other terms and conditions to be observed by the registered enterprise by virtue of the registration."}},{"id":"PH-H3989-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"General Provisions. Notwithstanding any provision of law to the contrary:\n(a) Number of Directors. Registered enterprises may fix the number of their Directors at any number not in excess of fifteen;\n(b) Types of Stock. For purposes of transferability, registered enterprises shall issue two types of voting shares of capital stock: one type which may be transferable only to Philippine Nationals and which shall at all times be not less than sixty per cent of the stock entitled to vote; and another which may be transferred to Philippine or foreign nationals, and which shall at no time be more than forty per cent of the voting stock. Each share shall have its type clearly designated on the face of the certificate.\n(c) Marketing Affiliate. Philippine Nationals who are stockholders in a registered enterprise in which non-Philippine Nationals hold stock may establish a marketing corporation to handle and distribute exclusively the product of the registered enterprise in its preferred area of investment: Provided , (1) That the said marketing company is wholly owned by, with entire beneficial ownership and control vested in, Philippine citizens; (2) That the stock of said marketing company is available for acquisition by other citizens of the Philippines who may desire to invest therein; (3) That Philippine Nationals hold at least twenty-one per cent of the voting stock of the registered enterprise; and (4) That the board approves the creation of the marketing corporation for reasons of economy and practicability."}},{"id":"PH-H3989-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Other Incentives Acts. After the promulgation and designation of the preferred areas of investments and/or pioneer industries under this Act, the Board of Industries created by Republic Act Numbered Three thousand one hundred twenty-seven, as amended, shall not accept any application for the exemptions provided for in the said Act, except (1) from persons, firms, or corporations that had been granted tax exemptions under the said Act prior to the effective date of this Act; (2) from persons, firms or corporations whose applications where pending approval at the time of the approval of this Act; (3) from persons, firms or corporations with applications which are necessary implementations or necessary consequences of Nos. 1 and 2; and (4) from persons, firms or corporations who are engaged in industries entitled to the benefits of said Republic act Numbered Three thousand one hundred twenty-seven, which are not within the preferred areas of investments under this Act.\n(b) A registered enterprise under this Act which is entitled to benefits under other laws shall be entitled, to the extent of its registered capacity, to such of the benefits granted under this Act as are not granted by said other laws and to such benefits granted under the latter as are not granted under the former."}},{"id":"PH-H3989-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Penal Clause. (a) Any violation of the provisions of this Act or of the terms or conditions of registration shall be punished by a fine not to exceed fifty thousand pesos (P50,000.00) or imprisonment for not more than three (3) years or both, at the discretion of the Court. If the offender is not a citizen of the Philippines, he shall be deported without further proceedings on the part of the Deportation Board in addition to the penalty prescribed herein and after service of the sentence therefor.\n(b) No official or employee of the government, its subdivisions or instrumentalities shall appear as counsel for or act as agent or representative of, or in any manner intervene or intercede, directly or indirectly, in behalf of any party in any transaction with the Board regarding the availment of incentives benefits under this Act. Violation of this subsection shall be subject to the same penalty provided for in subsection (a) hereof. If the guilty party is an appointive official or employee, he shall, in addition, be dismissed form the service with prejudice to reinstatement and subsequent appointment to any public office. If the violation is committed by a member of the Board, such member shall be punished with double the penalty herein provided."}},{"id":"PH-H3989-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Applicability and Interpretation. In interpreting and applying the provisions of this Act, the following rules shall be observed:\n(a) Applicability to Existing Enterprises. An enterprise which satisfies the definition of a \"Philippine National,\" engaged at the time of passage of this Act in an area of investment declared by the Board as a preferred area of investment, shall be entitled to registration as to its present capacity, as well as to such an expansion or enlargement thereof requiring new or additional machinery and equipment as shall be within the unfilled measured capacity of the area; so also, an investor in such an existing enterprise shall be entitled to benefits and incentives to the extent of his present as well as new or additional investment therein; Provided , That the benefits of this Act, so far as may be applicable to such existing enterprises and investors in such existing enterprises, shall be given prospective effect only from the date of registration.\n(b) Benefits of Multiple Area Enterprises. When a registered enterprise engages in activities or endeavors that have not been declared preferred or pioneer areas of investment, the benefits and incentives accruing under this Act to registered enterprises and investors therein shall be limited to the portion of the activities of such registered enterprise as is a preferred or pioneer area of investment.\n(c) Resolving Doubts. All doubts concerning the benefits and incentives granted enterprises and investors by this Act shall be resolved in favor of investors and registered enterprises."}},{"id":"PH-H3989-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Separability Clause. The provisions of this Act are hereby declared to be separable, and in the event one or more of such provisions are held unconstitutional, the validity of other provisions shall not be affected."}},{"id":"PH-H3989-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Appropriation. To carry out the purposes of this Act, there is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of Two million pesos for the fiscal year nineteen hundred sixty-seven-nineteen hundred sixty-eight. Thereafter, the appropriations for the Board of Investments shall be included in the annual General Appropriations Act."}},{"id":"PH-H3989-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Repealing Clause. All Acts, parts of Acts, executive orders and regulations inconsistent herewith, are hereby repealed or modified accordingly."}},{"id":"PH-H3989-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: September 16, 1967"}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Prescribing Incentives and Guarantees to Investments in the Philippines, Creating a Board of Investments, Appropriating the Necessary Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3990"] = {"id":"PH-H3990","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5187_1967.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for Public Works, Synchronizing the Same with Previous Public Works Appropriations","orig":"An Act Appropriating Funds for Public Works, Synchronizing the Same with Previous Public Works Appropriations"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5187","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-16","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5187_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3990-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Capital Improvements from General Funds. — For the purpose of implementing the Long Range Program of Capital Improvements of the Administration, the following sums, or so much thereof as may be necessary, are hereby appropriated out of the general funds in the National Treasury not otherwise appropriated, subject to the provisions hereinafter set forth, for the purposes mentioned hereunder:\n\"Sec. 24. This Act shall take effect upon its approval, except Section 2 hereof which shall take effect only upon certification of the Commissioner of the Budget and Auditor General of the availability of sufficient funds for the release and expenditure of the whole or part of all various sums appropriated.\"\nApproved: September 16, 1967."}}],"pack":"ph-p56"};
  FT["PH-H3991"] = {"id":"PH-H3991","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5188_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第4700号共和国法并为其他目的法案","en":"An Act Amending Republic Act Numbered Four Thousand Seven Hundred and for Other Purposes","orig":"An Act Amending Republic Act Numbered Four Thousand Seven Hundred and for Other Purposes","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 4700, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 4700 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Undang-Undang Republik No. 4700, dan untuk tujuan lain","ms":"Akta meminda Akta Republik No. 4700, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5188","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5188_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3991-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections 1, 2, 3, 4 and 5 of Republic Act Numbered four thousand seven hundred are hereby amended to read as follows:\n\"Sec. 1. To safeguard the printing of government official receipts, postage stamps, internal revenue stamps, strip stamps, stocks and bonds, bank notes, and other security printing jobs, the National Treasurer shall acquire, within ninety days and operate as soon as possible but not later than three years after approval of this Act, a complete security printing plant equipped with the most modern security printing presses which are not available to ordinary commercial printers, specifically those that allow for the simultaneous printing of front and back faces, of super-imposed tints and backgrounds, and the single or multi-color intaglio printing of major designs.\"\n\"Sec. 2. All government offices, agencies, instrumentalities and government-owned and/or controlled corporations required or allowed by laws, rules and regulations to print and/or issue any of the security papers enumerated in Section one hereof shall, upon approval of this Act, forward a projection of their printing requirements, thru the General Auditing Office, to the National Treasurer which shall print as soon as possible, with security printing presses, such requisitions as are approved by the Auditor General, and at costs, allowing only for a minimal margin to cover administration and operational expenses.\"\n\"Sec. 3. When not in use, all original designs, engravings and other printing materials involving the security of the printing shall be kept in a secured vault under the joint custody of a committee composed of the Auditor General as chairman, and the Governor of the Central Bank and the National Treasurer as members, and no design, engraving or other printing material shall be removed therefrom except in the presence of the head of the requisitioning office requiring the same. In the event of the temporary absence or inability of any member of the committee, his duties shall devolve upon the Deputy Auditor General, Assistant National Treasurer, or Deputy Governor of the Central Bank, as the case may be. The committee is hereby authorized to issue rules and regulations governing the custody and removal of materials from the vault: Provided, That in cases of front and back engravings one of these shall be under the custody of the head of the requisitioning office, in such manner that no security printing may be executed by the National Treasurer without the knowledge and approval of such official\".\n\"Sec. 4. To carry out the purposes of this Act, such sums as may be necessary, but in no case to exceed thirty million pesos (₱30M) are hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the purchase of a complete brand new printing equipment of long proven excellence which provide maximum security features and are most widely used by the leading Central Banks and/or government security printing agencies of the world, for the construction of a building, acquisition of a vault, other security measures, office equipment, air-conditioning, salaries and wages, and for setting up a revolving fund of not more than two million pesos for the purchase of special printing paper and other printing supplies and materials: Provided, That the printing equipment shall first be purchased before entering into any contract for the construction of the building or the acquisition of the vault and other accessories mentioned above: Provided, further, That the purchase of all the equipment, the construction of the buildings, and the acquisition of all other accessories mentioned herein shall be made through public bidding, under existing laws, rules and regulations governing the same, by a committee composed of the Secretary of Finance, as chairman, and the National Treasurer and the Governor of the Central Bank, as members; and a report of the results of each bidding shall be made to the Congress of the Philippines within thirty days after the award to the successful bidders: Provided, finally, That if the finances of the government do not permit the utilization of the funds in the treasury, the National Treasurer with the approval of the President, is hereby authorized to borrow funds from any local or foreign institution in an amount not exceeding thirty million pesos for the purposes provided for herein. From the time said printing plant is fully operational, such sums as may be necessary for the yearly operations of the same shall be provided for in the annual appropriations Act. The National Treasurer shall make an annual report of all loans and/or expenditures authorized under this Act to the Congress of the Philippines not later than the 31st day of January of each calendar year.\n\"All loans obtained under this Act shall be fully guaranteed by the Republic of the Philippines both as to principal and interest. In the event that the income from the operation of the printing plant shall not be sufficient to pay said principal and interest and the sum appropriated herein is not yet available for such payment, the Central Bank shall advance the amounts thereof out of its surplus funds, not otherwise appropriated. Thereupon the amounts so advanced shall be reimbursed by the National Treasurer from whatever payments he shall received for security printing jobs undertaken and from the fund appropriated herein, and such reimbursements shall automatically accrue to the surplus funds of the Central Bank.\"\n\"Sec. 5. Subject to the approval of the President, the National Treasurer shall issue such rules and regulations as may be necessary to carry out the implementation of this Act. Rules and regulations which effect other government offices and the general public, shall take effect thirty days after publication in the official gazette\"."}},{"id":"PH-H3991-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 16, 1967."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Four Thousand Seven Hundred and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3992"] = {"id":"PH-H3992","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5189_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Providing for the Appropriation of Funds for the Adjustment of the Salaries of the Members of the Faculty and Officials of the Philippine Normal College","orig":"An Act Providing for the Appropriation of Funds for the Adjustment of the Salaries of the Members of the Faculty and Officials of the Philippine Normal College"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5189","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-09-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5189_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3992-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"To enable the Board of Trustees of the Philippine Normal College to effect an adjustment of the salaries and compensation of the members of its faculty and administration officials, the sum of four hundred thousand pesos, or so much, thereof as may be necessary, is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated."}},{"id":"PH-H3992-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 17, 1967."}}],"pack":"ph-p56"};
  FT["PH-H3994"] = {"id":"PH-H3994","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5191_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Batac市","en":"An Act Converting Batac Emergency Hospital in the Municipality of Batac, Province of Ilocos Norte, into a General Hospital to be Known as Batac General Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting Batac Emergency Hospital in the Municipality of Batac, Province of Ilocos Norte, into a General Hospital to be Known as Batac General Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Bệnh viện Cấp cứu Batac thành Bệnh viện Đa khoa Batac tại Đô thị Batac, Tỉnh Ilocos Norte, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเปลี่ยนสถานะโรงพยาบาลฉุกเฉิน Batac เป็น โรงพยาบาลทั่วไป Batac ในเทศบาล Batac จังหวัด Ilocos Norte และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang mengubah status Rumah Sakit Gawat Darurat Batac menjadi Rumah Sakit Umum Batac di Kotamadya Batac, Provinsi Ilocos Norte, dan mengalokasikan dana untuk itu","ms":"Akta menukar status Hospital Kecemasan Batac kepada Hospital Besar Batac di Perbandaran Batac, Wilayah Ilocos Norte, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5191","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5191_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3994-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Batac Emergency Hospital in the Municipality of Batac Province of Ilocos Norte, is hereby converted into a general hospital to be known as Batac General Hospital."}},{"id":"PH-H3994-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act for the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3994-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 18, 1968."}}],"pack":"ph-p56"};
  FT["PH-H3995"] = {"id":"PH-H3995","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5192_1968.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予 Cagayan Valley Utilities Corporation 在卡加延、伊莎贝拉与新比斯开省安装、运营和维护电话系统的特许经营权法案","en":"An Act Granting the Cagayan Valley Utilities Corporation a Franchise to Install, Operate and Maintain a Telephone System in the Provinces of Cagayan, Isabela and Nueva Vizcaya","orig":"An Act Granting the Cagayan Valley Utilities Corporation a Franchise to Install, Operate and Maintain a Telephone System in the Provinces of Cagayan, Isabela and Nueva Vizcaya","vi":"Đạo luật cấp quyền khai thác cho Cagayan Valley Utilities Corporation để xây dựng, lắp đặt, vận hành và duy trì hệ thống viễn thông tại tỉnh Cagayan","th":"พระราชบัญญัติให้สัมปทานแก่ Cagayan Valley Utilities Corporation เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบโทรคมนาคมในจังหวัด Cagayan","id":"Undang-Undang memberikan waralaba kepada Cagayan Valley Utilities Corporation untuk membangun, memasang, mengoperasikan, dan memelihara sistem telekomunikasi di Provinsi Cagayan","ms":"Akta memberikan francais kepada Cagayan Valley Utilities Corporation untuk membina, memasang, mengendalikan dan menyelenggara sistem telekomunikasi di Wilayah Cagayan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5192","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5192_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3995-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act and the provisions of Commonwealth Act Numbered One hundred and forty-six, as amended, and of the Constitution, applicable thereto, there is hereby granted to the Cagayan Valley Utilities Corporation, hereinafter called the grantee, its successors or assigns, for a period of twenty-five years from the approval of this Act, the right and privilege to construct operate and maintain in the Provinces of Cagayan, Isabela and Nueva Vizcaya a telephone system to carry on the business of electrical transmission of conversations and signals in the said provinces. For this purpose the grantee is hereby authorized to use all streets and public thoroughfares in the said provinces for the construction, operation and maintenance of all apparatus, conductors, and appliances necessary for the electrical transmission or conduction in, on, over, or under the public roads, highways, lands, bridges, streets, lanes, and sidewalks in said provinces and overhead or underground lines or on the surface of the ground as may be necessary and best adapted to said transmission."}},{"id":"PH-H3995-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All poles erected and all conduits constructed or used by the grantee shall be located in places designated by the grantee: Provided, That all poles erected and used by the grantee or its successors or assigns shall be of such appearance as not to disfigure the streets, and the wires and cables carried by said poles and the underground cables shall be strung and laid in accordance with professional standards approved by the Public Service Commission; and said poles shall be of such height as to maintain the wires and cables stretched on the same at a height of at least fifteen feet above the level of the ground, and said wires and cables shall be so placed as not to imperil the public safety in accordance with a plan approved by the Public Service Commission: Provided, further, That whenever twenty-five or more pairs of wires or other conductors are carried on one line of poles in the poblacion of the said provinces, said wires or conductors shall be placed in one cable, and that whenever more than eight hundred pairs of wires or other conducts are carried on one line of poles said wires or conductors shall be placed underground by the grantee, its successors or assigns, whenever ordered to do so by the Public Service Commission."}},{"id":"PH-H3995-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"For the purpose of erecting and placing the poles or other supports of such wires or other conductors or of laying and maintaining underground said wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, to make excavations or lay conduits in any of the public places, highways, streets, alleys, lanes, avenues, sidewalks or bridges in the Provinces of Cagayan, Isabela and Nueva Vizcaya: Provided, However, That any public place, highway, street, alley, lane, avenue, sidewalk or bridge disturbed, altered of changed by reason of the erection of poles or other supports, or the laying of underground wires or other conductors, or of conduits shall be replaced and restored to the satisfaction of the district engineer of the province, and removing from the same all rubbish, dirt, refuse, or other material which may have been placed there or taken up in the erection of said poles or the laying of said underground conduits, leaving them in as good conditions as they were before the work was done."}},{"id":"PH-H3995-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Whenever any person has obtained permission to use any of the streets of a municipality in said provinces for the purpose of removing any building or in the prosecution of any municipal work or for any other cause whatsoever, making it necessary to raise or remove any of said wires or conduits which may obstruct or hinder the prosecution of said work, the said grantee, upon notice by the municipal council of the municipality, served upon said grantee at least forty-eight hours in advance, shall raise or remove any of said wires or conduits which may hinder the prosecution of such work or obstruct the removal of said buildings, so as to allow the free and unobstructed passage of said buildings and the free and unobstructed prosecution of said work, and the person or entity at whose request the wires or poles or other structures have been removed, shall pay one-half of the actual cost of replacing the poles or raising the wires and other conductors or structures. The notice shall be in the form of a resolution duly adopted by the municipal council of the municipality and served upon the grantee or its duly authorized representative or agent by a person competent to testify as witness in a civil action, and in case of refusal or failure of the grantee to comply with such notice, the municipal mayor of the municipality, with the approval of the municipal council first had, shall order such wires or conduits to be raised or removed at the expense of the grantee, for the purposes aforesaid."}},{"id":"PH-H3995-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All apparatus and appurtenances to be used by the grantee, its successors or assigns, shall be modern and first class in every respect and all telephone lines or installations used, operated and maintained in connection with this franchise by the grantee, its successors or assigns, shall be kept and maintained at all times in a satisfactory manner, so as to render an efficient and adequate telephone service, and it shall be further the duty of said grantee, its successors or assigns, whenever required to do so by the Public Service Commission to modify, improve, and charge such telephone system for the electrical transmission of conversations and signals by means of electricity in such manner and to such extent as the progress of science and improvements in the methods of electrical transmission of conversations and signals by means of electricity may make reasonable and proper."}},{"id":"PH-H3995-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall keep a separate account of the gross receipts of its telephone business, and shall furnish the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first of July of each year for the twelve months preceding the first day of July."}},{"id":"PH-H3995-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition, the grantee, its successors or assigns, shall pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts as prescribed in Section six of this Act, three per centum of all gross receipts of the telephone business transacted under this franchise by the grantee, its successors or assigns."}},{"id":"PH-H3995-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Within sixty days from the approval of this Act, the grantee shall file with the Public Service Commission its application for a certificate of public necessity and convenience. In case of failure to make said application within the period established, this franchise shall become null and void."}},{"id":"PH-H3995-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not commence any construction whatever pursuant to this franchise without first obtaining a certificate of public necessity and convenience from the Public Service Commission of the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended, especially authorizing such construction. The grantee shall not exercise any right or privilege under this franchise without first having obtained such certificate of public necessity and convenience from the Public Service Commission. The Public Service Commission shall have the power to issue such certificate of public necessity and convenience whenever it shall after due hearing, determine that such construction or such exercise of the rights and privileges under this franchise is necessary and proper for the public convenience, and the Commission shall have the power in issuing such certificate to impose such conditions, as to construction, equipment, maintenance, service or operation as the public convenience and interest may reasonably require, and such certificate shall state the date on which the grantee shall commence construction and the period within which the work shall be completed. In order to avail itself of the right granted by such certificate of public necessity and convenience, the grantee shall file with the Public Service Commission, within such period as said Commission shall fix, its written acceptance of the terms and conditions of this franchise and of the certificate, together with the document evidencing the fact that the deposit required in Section ten has been made. In the event that the grantee shall not commence the telephone service referred to in the certificate obtained and filed herein provided within such period as the Public Service Commission shall have fixed, said Commission may declare said certificate null and void and the deposit made pursuant to Section ten of this Act forfeited to the National Government unless the grantee shall have been prevented from doing so by fortuitous cause or force majeure, usurpation by military power, martial law, riot, uprising, or other inevitable cause: Provided, However, That if the grantee shall have been prevented by one or more of all such causes from commencing the telephone service within the period specified, the time during which it shall have been so prevented shall be added to said period: Provided, further, That failure on the part of the grantee to accept the conditions of franchise and those imposed in the certificate of public necessity and convenience shall automatically void this franchise."}},{"id":"PH-H3995-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Upon the written acceptance of the terms and conditions of this franchise, the grantee shall deposit in the National Treasury five thousand pesos, or negotiable bonds of the Government of the Philippines, or other securities approved by the Secretary of Public Works and Communications of the face value of five thousand pesos, as an earnest of good faith in accepting this franchise and a guaranty that, within one year from the date of the granting by the Public Service Commission of a certificate of public necessity and convenience authorizing the construction and operation by the grantee of a telephone service in the Province of Cagayan, Isabela and Nueva Vizcaya, the grantee, its successors or assigns, will be completely provided with the necessary equipment and ready to begin operation in accordance with the terms of this franchise: Provided, That if the deposit is made in money, the same shall be deposited at interest in some interest-paying bank approved by the Secretary of Public Works and Communications, and all interest accruing and due on such deposit shall be collected by the Treasurer of the Philippines and paid to the grantee, its successors or assigns, on demand: And, Provided, further, That if the deposit made to the Treasurer of the Philippines be in negotiable bonds of the Government of the Philippines or other interest-bearing securities approved by the Secretary of Public Works and Communications, the interest on such bonds or securities shall be collected by the Treasurer of the Philippines and paid over to the grantee, its successors or assigns on demand.\nShould the said grantee, its successors or assigns, for any other cause than an act of God, public enemy, usurpation by military power, martial law, riot, civil commotion, or inevitable cause, fail, refuse, or neglect to begin, within two years from the date of the granting of said certificate of public necessity and convenience, the business of transmitting messages by telephone, or fail, refuse, or neglect to be fully equipped and ready to operate, within two years from the date of the granting of said certificate of public necessity and convenience, the telephone service in the Provinces of Cagayan, Isabela and Nueva Vizcaya applied for by the grantee according to the terms of this franchise, then the deposit prescribed by this section to be made to the Treasurer of the Philippines, whether in money, bonds, or other securities, shall become the property of the National Government as liquidated damages caused to such Government by such failure, refusal, or neglect, and thereafter no interest on said bonds or other securities deposited shall be paid to the grantee, its successors or assigns. Should the grantee, its successors or assigns, begin operating business of transmitting messages by telephone and be ready to operate according to the terms of this franchise, the telephone service in the Province of Cagayan, Isabela and Nueva Vizcaya, within two years from the date of the granting of said certificate of public necessity and convenience, then and in that event the deposit prescribed by this section shall be returned by the National Government to the grantee, its successors or assigns, upon recommendation of the Public Service Commission, as soon as the telephone service in said provinces applied for the grantee has been installed according to the terms of this franchise: Provided, further, That all the time during which the grantee, its successors or assigns, may be prevented from carrying out the terms and conditions of this franchise by any of said causes shall be added to the time allowed by this franchise for compliance with its provisions."}},{"id":"PH-H3995-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The books and accounts of the grantee, its successors or assigns shall always be open to the inspection of the provincial auditor or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports for the quarter past and the general condition of the business."}},{"id":"PH-H3995-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The rights herein granted shall not be exclusive and the rights and powers to grant any corporation, association, or person other than the grantee, franchise for the telephone or electrical transmission of messages or signals shall not be impaired or affected by the granting of this franchise: Provided, that the poles erected, wires strung or cables or conduits laid by virtue of any franchise for telephone, or other electrical transmission of messages and signals granted subsequent to this franchise shall be so placed as not to impair the efficient and effective transmission of conversations or signals under this franchise by means of poles erected, wires strung, or cables or conduits actually laid and in existence at the time of the granting of said subsequent franchise: Provided, further, That the Public Service Commission, after hearing both parties interested, may compel the grantee of this franchise or its successors or assigns to remove, relocate, or replace its poles, wires, or conduits; but in such case the reasonable cost of the removal, relocation, or replacement shall be paid by the grantee of the subsequent franchise or its successors or assigns."}},{"id":"PH-H3995-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial and municipal governments harmless from all claims, accounts, demands, and/or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the telephone, or other electrical transmission system of the said grantee, its successors or assigns."}},{"id":"PH-H3995-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The rates for the telephone service, flat rates as well as measured rates, shall be subject to the approval of the Public Service Commission.\nThe monthly rates for telephone having metallic circuit within the limits of the said provinces shall also be approved by the Public Service Commission."}},{"id":"PH-H3995-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee shall not, without the previous and explicit approval of the Public Service Commission, directly or indirectly transfer, sell or assign this franchise to any person, association, company or corporation or other mercantile or legal entity."}},{"id":"PH-H3995-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee may install, operate, maintain, purchase or lease such telephone stations, lines, cables or systems as are convenient or essential to efficiently carry out the purpose of this franchise: Provided, However, That the grantee, its successors or assigns, shall not, without the permission of the Public Service Commission first had, install, operate, maintain, purchase or lease such stations, lines, cables or systems."}},{"id":"PH-H3995-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The Philippine Government shall have the privilege, without compensation, of using the poles of the grantee to attach one ten-pin crossarms, and to install, operate and maintain wires of its telegraph system thereon: Provided, However, That the Bureau of Telecommunications, shall have the right to place additional crossarms and wires on the poles of the grantee by paying a compensation the rate of which is to be agreed upon by the Director of Telecommunications and the grantee: Provided, further, That in case of disagreement as to the rate of contract rental such shall be fixed by the Public Service Commission."}},{"id":"PH-H3995-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"It is expressly provided that in the event the Government should desire to operate and maintain for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and shall turn over to the Government said system and all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3995-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Cagayan Valley Utilities Corporation a Franchise to Install, Operate and Maintain a Telephone System in the Provinces of Cagayan, Isabela and Nueva Vizcaya","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3996"] = {"id":"PH-H3996","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5193_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在萨马省设立 Victoria 市镇的法案","en":"An Act Creating the Municipality of Victoria in the Province of Samar","orig":"An Act Creating the Municipality of Victoria in the Province of Samar","vi":"Đạo luật thành lập Thị trấn Victoria tại Tỉnh Samar","th":"พระราชบัญญัติจัดตั้งเทศบาล Victoria ในจังหวัด Samar","id":"Undang-Undang membentuk Kotamadya Victoria di Provinsi Samar","ms":"Akta mewujudkan Perbandaran Victoria di Wilayah Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5193","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5193_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3996-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created in the Province of Samar a municipality to be known as the Municipality of Victoria, which shall consist of the portion of the Municipality of Allen of the same province, comprising barrios Mawo, Colab-of, San Lazaro, Buenos Aires, Maxvilla, Buena Suerte and San Miguel; and that portion of the Municipality of San Isidro, also of the same province, comprising barrios Erenas, Acedillo and San Ramon."}},{"id":"PH-H3996-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of Victoria shall have its seat of government in Barrio Mawo."}},{"id":"PH-H3996-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Municipalities of Allen and San Isidro shall retain their present territories minus the portion included in the Municipality of Victoria."}},{"id":"PH-H3996-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first mayor, vice-mayor, and councilors of the Municipality of Victoria, shall be elected in the next general elections for local officials."}},{"id":"PH-H3996-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Victoria in the Province of Samar","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3997"] = {"id":"PH-H3997","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5194_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将莱特省第三众议员选区划为独立工程区并授权为此拨款的法案","en":"An Act Constituting the Third Representative District of the Province of Leyte into a Separate Engineering District and Authorizing the Appropriation of Funds Therefor","orig":"An Act Constituting the Third Representative District of the Province of Leyte into a Separate Engineering District and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5194","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5194_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3997-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Third Representative District of the Province of Leyte is hereby constituted into a separate engineering district, with its office at the Municipality of Villaba. Provided, That the existing engineering district in the Subprovince of Biliran which is also situated in the Third Representative District, shall remain a distinct and separate entity.\nThe district engineer for said engineering district shall be appointed in accordance with existing laws."}},{"id":"PH-H3997-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3997-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Third Representative District of the Province of Leyte into a Separate Engineering District and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3998"] = {"id":"PH-H3998","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5195_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Claveria市","en":"An Act Establishing the Claveria Station Hospital in the Municipality of Claveria, Province of Masbate and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Claveria Station Hospital in the Municipality of Claveria, Province of Masbate and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Trạm Claveria tại Đô thị Claveria, Tỉnh Masbate, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลสถานี Claveria ในเทศบาล Claveria จังหวัด Masbate และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Stasiun Claveria di Kotamadya Claveria, Provinsi Masbate, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Stesen Claveria di Perbandaran Claveria, Wilayah Masbate, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5195","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5195_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3998-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five bed capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H3998-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Claveria, Province of Masbate, a station hospital to be known as the Claveria Station Hospital with a bed capacity of not less than ten nor more than twenty-five beds."}},{"id":"PH-H3998-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of the hospital, provide a suitable table of organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands, merge this hospital with local health units in the Municipality of Claveria, Province of Masbate, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H3998-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A sum not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital, during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3998-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56"};
  FT["PH-H3999"] = {"id":"PH-H3999","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5196_1968.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"授予 Flora Consing 在武端市建设、运营和维护制冰厂与冷藏库并在该市及阿古桑省 Cabadbaran、Nasipit 等市镇销售冰和供应冷藏的特许权法案","en":"An Act Granting Flora Consing a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Butuan, and to Sell Ice and Supply Cold Storage Within the City and the Municipalities of Cabadbaran, Nasipit, Buenavista and Carmen, All in the Province of Agusan","orig":"An Act Granting Flora Consing a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Butuan, and to Sell Ice and Supply Cold Storage Within the City and the Municipalities of Cabadbaran, Nasipit, Buenavista and Carmen, All in the Province of Agusan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5196","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5196_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3999-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted to Flora Consing, hereinafter referred to as the grantee, a franchise to construct, operate and maintain an ice plant and cold storage in the City of Butuan, for the purpose of manufacturing and distributing ice and supplying cold storage within the city and in the municipalities of Cabadbaran, Nasipit, Buenavista and Carmen, all in the Province of Agusan, and to charge and collect a schedule of prices and rates for the ice and cold storage furnished, which shall not exceed seven centavos a kilo."}},{"id":"PH-H3999-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of her plant and/or plants."}},{"id":"PH-H3999-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect and the grantee, whenever the Congress shall determine that public interest reasonably requires it, shall change or alter any of the apparatus and appurtenances at her expense."}},{"id":"PH-H3999-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The franchise shall continue for a period of twenty-five years from the date said plant and cold storage is placed in operation and/or commences the manufacture and distribution of ice in the City of Butuan and municipalities of Cabadbaran, Nasipit, Buenavista and Carmen, all in the Province of Agusan, subject to the express condition that the franchise shall be null and void unless the construction of at least one plant and cold storage be begun within four years from the date of the approval of this Act and completed within six years from said date, except when prevented by an act of God, or force majeure, martial law, riot, civil commotion, usurpation by military power or any other cause beyond the grantee’s control."}},{"id":"PH-H3999-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The books records and accounts of the grantee shall always be opened to inspection by the City Treasurer and/or his authorized representatives, and it shall be the duty of the grantee to submit to the City Treasurer quarterly report in duplicate showing the gross receipts for the past quarter, one of which shall be forwarded by the City Treasurer to the Auditor General, who shall keep the same on file."}},{"id":"PH-H3999-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred and forty-six as amended only with respect to the fixing of rates. In consideration of the franchise hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings for ice and cold storage sold under this franchise, three per centum of which shall accrue to the national government, and two per centum to the municipality or city where it is operating."}},{"id":"PH-H3999-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not commence any construction nor exercise the rights and privileges herein granted without first communicating to the Secretary of Public Works and Communications its accordance and conformity to the terms and conditions of the franchise within two years from the date of the approval of this Act."}},{"id":"PH-H3999-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons or corporation."}},{"id":"PH-H3999-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Flora Consing a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the City of Butuan, and to Sell Ice and Supply Cold Storage Within the City and the Municipalities of Cabadbaran, Nasipit, Buenavista and Carmen, All in the Province of Agusan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4000"] = {"id":"PH-H4000","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5197_1968.html","fetchedAt":"2026-10-06","articleCount":28,"structureMode":"ARTICLE","title":{"zh":"规范菲律宾糖业技术执业的法案","en":"An Act Regulating the Practice of Sugar Technology in the Philippines","orig":"An Act Regulating the Practice of Sugar Technology in the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5197","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 28 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5197_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 29 条，缺 14）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4000-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Definitions. — Unless otherwise specified the following terms used in this Act shall mean:\n(a) Sugar. — Sugar in any of its recognized commercial forms derived from sugar cane or sugar plant, including syrups, edible and fancy molasses, and any other form of liquid sugar and their by-products; bagasse, molasses, and filter cake.\n(b) Scope of the practice of sugar technology. — The agronomy of sugar cane plants; analysis, synthesis and preparation of sugar; the manufacture, processing and refining of sugar; the industrial utilization of sugar and its by-products; consultation work on problems involving the processing, manufacture, refining, or industrial utilization of sugar; and the teaching of professional courses in sugar technology.\n(c) Sugar technologists. — Any person who, for fee, salary or other compensation or reward to himself or to another person, renders professional service requiring the knowledge of sugar technology.\n(d) Board. — The Board of Examiners for Sugar Technologists created by this Act.\n(e) Registration. — The authority given by the Board to practice sugar technology.\n(f) License. — The authority given by the Board to a sugar mill, refinery, or factory engaged in the processing, manufacture, or refining of sugar or its by-products."}},{"id":"PH-H4000-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Creation and composition of the Board. — Within thirty days after the approval of this Act, there shall be created a Board of Examiners for Sugar Technologists to be composed of a Chairman and two members who shall be appointed by the President of the Philippines, upon the recommendation of the Commissioner of Civil Service from among registered sugar technologists of recognized standing in the Philippines as may be certified by the bona fide national professional organization or association of sugar technologists in the Philippines and possessing the qualifications prescribed in Section three of this Act: Provided, That the first Board of Examiners for Sugar Technologists to be created pursuant to this Act shall each be issued a certificate of registration as sugar technologist without prior examination in accordance with the provisions of this Act."}},{"id":"PH-H4000-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Qualifications of Board Members. — Each member of the Board shall at the time of his appointment be:\n(1) A citizen of the Philippines and a resident thereof.\n(2) At least thirty years of age.\n(3) A duly registered sugar technologists in the Philippines, who has at least ten years experience in the practice of sugar technology previous to his appointment.\n(4) Not a member of the faculty of any school, college or university where courses in sugar technology, sugar chemistry or sugar engineering is taught, not have pecuniary interest in such institution. The members of the first Board of Examiners for Sugar Technologists appointed under this Act shall be considered registered or licensed for the purpose hereof, and shall be issued upon payment of fifty pesos a certificate of registration in accordance with the provisions of this Act."}},{"id":"PH-H4000-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Term of Office. — The members of the Board shall hold office for a term of three years after their respective appointments, or until their successors shall have been appointed and have duly qualified. The members of the first Board appointed under this Act shall hold office for the following terms; one member for one year, one member for two years and one member for three years. Vacancies shall be filled for the unexpired term only.\nEach member of the Board shall qualify by taking the proper oath of office prior to entering upon the performance of his duties."}},{"id":"PH-H4000-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Removal of Board Members. — The President of the Philippines may remove any member of the Board for continued neglect of duty or incompetency or for unprofessional or dishonorable conduct, after giving the member concerned an opportunity to defend himself in the proper administrative investigation."}},{"id":"PH-H4000-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers vested in the Board. — The Board of Examiners for Sugar Technologists is vested with authority conformably with the provisions of this Act, to administer the provisions hereof, to issue, suspend and revoke certificates of registration for the practice of sugar technology and to administer oaths.\n(a) In carrying into effect the provisions of this Act, the Board may, under the hand of the Chairman and the seal of the Board, subpoena, witnesses and compel their attendance, and also may require the production of books, documents, and papers, in a case involving the revocation of registration or the practice of sugar technology without registration. Any member of the Board may administer oaths or affirmations to witnesses appearing before the Board. If any person shall refuse to obey a subpoena so issued or shall refuse to testify or produce any books documents, or other papers, the Board may present a petition to the Court of First Instance, setting forth the facts and thereupon such Court shall, in proper case, issue its subpoena to such person, requiring his attendance before such court and thereto testify or produce such books, documents, or papers, as may be deemed necessary and pertinent by the Board. Any person failing or refusing to obey testify or produce such books, documents, or papers, as may be deemed necessary and pertinent by the Board. Any person failing or refusing to obey the subpoena or order of said court may be prosecuted against in the same manner as for refusal to obey other subpoena or order of the court.\n(b) The Board shall exercise the powers conferred upon it by this Act, evaluate academic courses or practical training in sugar technology, sugar chemistry and/or sugar engineering and shall make recommendation to the Secretary of Education who shall take appropriate action thereon to improve the education standards in sugar technology; to inspect centrifugal sugar mills, refineries, or factories, schools and other educational institutions and, in general, to study conditions affecting the practice of sugar technology in the Philippines.\n(c) Unless authorized by the other Board of Examiners concerned in the exercise of the powers vested in them by law, no sugar laboratory, centrifugal sugar mill, sugar refinery, or factory engaged in the processing, manufacture, or refining of sugar and its by-products shall operate without first obtaining a license from the Board of Examiners for Sugar Technologists."}},{"id":"PH-H4000-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Meetings of the Board. — The Board shall hold at least one regular executive meeting but not more than four meetings every month to act on matters before it."}},{"id":"PH-H4000-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Compensation of Members of the Board. — The members of the Board shall each receive a compensation of not exceeding fifteen pesos for each applicant examined, and twenty pesos for each applicant granted a certificate of registration without examination. The members of the Board shall also receive a per diem of fifty pesos for every executive meeting of the Board and actual and necessary expenses incurred in the inspection of educational institutions and sugar establishments provided in paragraph b, Section six hereof. Any sugar technologist in the employ of the Republic of the Philippines appointed as member of the Board shall also receive the compensation herein provided, as well as per diems for executive meetings of the Board and actual and necessary expenses for inspections of educational institutions and sugar factories. All fees shall be received by the officer designated by competent authority as collecting officer for the Civil Service Commission and such officer shall pay all authorized expenses provided by this Act to the members of the Board."}},{"id":"PH-H4000-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Executive Officer and Secretary of the Board. — (Superseded by PD 223)"}},{"id":"PH-H4000-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Annual Reports. — The Board shall after the close of each fiscal year submit an annual report, through the Commissioner of Civil Service to the President of the Philippines, giving detailed account of its proceedings during the year and making such recommendations as it may deem proper.\nRegistration and Examination"}},{"id":"PH-H4000-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Inhibition against the practice of sugar technology. — Unless exempt from registration or not subject to the requirements of this Act as provided in Section Twenty-six hereof, no person shall practice or offer to practice sugar technology in the Philippines, without having previously obtained a certificate of registration from the Board."}},{"id":"PH-H4000-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Exemption from registration. — Registration shall not be required of the following classes of persons;\n(a) Sugar technologists from other countries called in for consultations or for a project not requiring more than six months’ residence in the Philippines in any twelve months’ period: Provided, That such sugar technologists are legally qualified to practice as sugar technologists in their own state or country in which the requirement and qualifications for obtaining a certificate of registration are not lower than those specified in this Act.\n(b) Foreigners employed as technical officers, professors, or consultants in such special branches of sugar technology as may, in the judgment of the Board, be necessary and indispensable for the Country: Provided, That they are internationally recognized experts, that the work is confined to the specified employment and they do not engage in private practice."}},{"id":"PH-H4000-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Examination required. — Except as otherwise specifically allowed under the provisions of this Act, all applicants for registration as sugar technologists shall be required to undergo the examinations provided in this Act.\nSection 14. Qualification for examination.— Any person applying for examination and for a certificate of registration shall, prior to admission to examination, establish to the satisfaction of the Board that:\n(a) He is a citizen of the Philippines and at least twenty-one years of age;\n(b) He is of good reputation and moral character; and\n(c) He has graduated in sugar technology from a school, college or university recognized by the Government after completing a resident collegiate course leading to the degree of Bachelor of Science in Sugar Technology of not less than five years, or its equivalent baccalaureate degree. Three years of practical experience in sugar technology may be considered as sufficient equivalent for every year of college education which experience must be acquired before the application for examination.\n(d) Applicants below twenty-one years of age may be allowed to take the examination, but the certificate of registration shall be withheld until the candidate has reached the age of twenty-one years."}},{"id":"PH-H4000-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Holding of examination. — Examination shall be given once a year and on such working days and place as the Board may fix upon the recommendation of the Commissioner of Civil Service. Written or printed notice of such examination shall be published in newspapers and copies mailed to each candidate who has filed his name and address with the Secretary of the Board, at least thirty days prior to the date of the first day of examination."}},{"id":"PH-H4000-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Scope of Examination. — The Sugar Technologists examination shall cover the following minimum requirements:\nI. Sugar cane agronomy.\nII. Sugar Chemistry and chemical control III. Sugar engineering and instrumentation IV. Sugar manufacture and refining\nV. By-products utilization VI. Professional ethics for sugar technologists."}},{"id":"PH-H4000-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Rules and Regulations. — The Board shall, with the approval of the President of the Philippines and with the advice of the Commissioner of Civil Service adopt rules and regulations governing the examinations and the standards to be attained in them, and shall promulgate such rules and regulations and a Code of Ethics for Sugar Technologists as may be necessary to effectively carry out the provisions of this Act."}},{"id":"PH-H4000-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Reports of rating. — The Board shall, within one hundred twenty days after the date of the completion of the examination, report the rating obtained by each candidate through the Commissioner of Civil Service to the President of the Philippines for approval."}},{"id":"PH-H4000-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Issuance of certificate. — Upon payment of the registration fee provided in this Act, the Board shall issue to examinees who obtained an average of seventy per cent in the subjects listed in Section sixteen hereof and who have also satisfactorily met all the requirements specified in this Act the corresponding certificates of registration as sugar technologists.\nWithin two years after the approval of this Act, the Board shall, upon application, issue a certificate of registration as sugar technologists without examination to persons who have graduated with baccalaureate degree in sugar technology of not less than five years and have been in the practice as such graduate for at least five years prior to the enactment of this Act, or having graduated with an equivalent baccalaureate degree and have been in the practice of sugar technology for at least ten years prior to the enactment of this Act.\nAll certificates of registration issued under this Act shall show the full name of the registrants; shall have consecutive serial numbers; shall be signed by all the members of the board; shall be attested by the Secretary of the Board and shall be authenticated by the official seal of the Board."}},{"id":"PH-H4000-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Fee for examination and registration. — Every applicant for examination shall pay an application fee of fifty pesos and every applicant for registration shall pay a registration fee of ten pesos: Provided, That any applicant for registration without examination as sugar technologist shall pay a fee of sixty pesos: Provided, further, that any applicant for exemption from registration shall pay a fee of fifty pesos."}},{"id":"PH-H4000-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Suspension and revocation of certificate. — The Board shall have the power, upon proper notice and hearing, to suspend or revoke any certificate of registration or exemption from registration of any registrant in any case involving the use or perpetration of any fraud or deceit in having obtained a certificate of registration, or for violation of any of the provisions of the rules and regulations, or of the Code of Ethics for Sugar Technologists, or for gross negligence or incompetency, or for unprofessional or dishonorable conduct."}},{"id":"PH-H4000-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Reissue of revoked certificate or replacement of lost certificate. — After the expiration of one year from the date revocation of a certificate of registration and after the payment of twenty pesos the Board may, for good and sufficient reasons, entertain an application for a new certificate of registration and, in its discretion exempt the applicant from undergoing another examination.\nSundry Provisions Relative to Practice of Sugar Technology"}},{"id":"PH-H4000-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Penal Provisions. — Any person who shall practice sugar technology in the Philippines without being registered or exempted from registration in accordance with the provisions of this Act, or person presenting or attempting to use as his own, the certificate of registration of another, or any person who shall give any false or fraudulent evidence of any kind to the Board or to any member thereof in obtaining a certificate of registration, or any person who shall attempt to use a revoked or suspended certificate of registration, or any person who shall in connection with his name or otherwise, assume, use or advertise any title or description tending to convey the impression that he is a sugar technologist without holding a valid certificate of registration, or any person who shall violate any provisions of this Act, or any person or corporate body who shall violate any of the rules and regulations or orders promulgated by the Board for the purpose of carrying out the provisions of this Act, shall upon conviction, be sentenced to pay a fine of not less than two hundred pesos nor more than two thousand pesos or to suffer imprisonment for a period of not exceeding six months, or both, in the discretion of the court."}},{"id":"PH-H4000-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Application to firms or corporations. — A firm, co-partnership, corporation, or association, may engage in the practice of sugar technology in the Philippines; Provided, That such practice is carried on by sugar technologists in their employ having valid certificates of registration issued by the Board.\nIn case of a firm, co-partnership, corporation, or association, the manager administrator or the person who has charge of the management or administration of the business shall be held personally liable for any violation of any provision of this Act."}},{"id":"PH-H4000-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Posting of certificate of registration. — The owner, manager, or other person in charge of any sugar laboratory, centrifugal sugar mill, sugar refinery, or factory engaged in the processing or manufacture of sugar and its by-products shall post or cause to be posted in a conspicuous place within such laboratory, mill, refinery, or factory, the certificates of registration of the sugar technologists employed therein."}},{"id":"PH-H4000-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Act not affecting other professions. — Any person who has passed the corresponding Board examination for the practice of a profession already regulated by existing law shall not be subject to the provisions of this Act if in the practice thereof he has to perform work or services regulated by this Act.\nFinal Provisions"}},{"id":"PH-H4000-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Reciprocity requirements. — A foreign sugar technologists who is a permanent resident shall be admitted to examination, or be given a certificate of registration, or be entitled to any of the rights and privileges granted under this Act, if the country or state of which he is subject or citizen does not prohibit Filipino sugar technologists to practice within its territorial limits."}},{"id":"PH-H4000-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Repeal of laws. — All laws, orders or regulations in conflict with the provisions of this Act are hereby repealed."}},{"id":"PH-H4000-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Effectivity. — This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Regulating the Practice of Sugar Technology in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4001"] = {"id":"PH-H4001","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5198_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加黎刹省Morong急诊医院床位（由25张增至50张）并授权为此拨款的法案","en":"An Act Increasing the Bed Capacity of Morong Emergency Hospital in the Province of Rizal, from Twenty-Five to Fifty Beds, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Increasing the Bed Capacity of Morong Emergency Hospital in the Province of Rizal, from Twenty-Five to Fifty Beds, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật tăng sức chứa giường bệnh của Bệnh viện Cấp cứu Morong tại Tỉnh Rizal từ 25 lên 50 giường, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของโรงพยาบาลฉุกเฉิน Morong ในจังหวัด Rizal จาก 25 เป็น 50 เตียง และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang meningkatkan kapasitas tempat tidur Rumah Sakit Gawat Darurat Morong di Provinsi Rizal dari 25 menjadi 50 tempat tidur, dan mengalokasikan dana untuk itu","ms":"Akta meningkatkan kapasiti katil Hospital Kecemasan Morong di Wilayah Rizal daripada 25 kepada 50 katil, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5198","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5198_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4001-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Morong Emergency Hospital in the Province of Rizal, is hereby increased from twenty-five to fifty beds."}},{"id":"PH-H4001-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds, in the National Treasury not otherwise appropriated, to carry out the purposes of this Act for fiscal year nineteen hundred and sixty-eight. Thereafter, such sums as may be needed for the operation and maintenance of said hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H4001-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of Morong Emergency Hospital in the Province of Rizal, from Twenty-Five to Fifty Beds, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4002"] = {"id":"PH-H4002","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5199_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省卡班卡兰市镇Kabankalan妇产医院的名称变更为Dr. Gumersindo Garcia，Sr.纪念医院的法案","en":"An Act Changing the Name of the Kabankalan Maternity Hospital in the Municipality of Kabankalan, Province of Negros Occidental, to Dr. Gumersindo Garcia, Sr. Memorial Hospital","orig":"An Act Changing the Name of the Kabankalan Maternity Hospital in the Municipality of Kabankalan, Province of Negros Occidental, to Dr. Gumersindo Garcia, Sr. Memorial Hospital","vi":"Đạo luật đổi tên Kabankalan Maternity Hospital tại Thị trấn Kabankalan, Tỉnh Negros Occidental thành Bệnh viện tưởng niệm Dr. Gumersindo Garcia, Sr.","th":"พระราชบัญญัติเปลี่ยนชื่อ Kabankalan Maternity Hospital ในเทศบาล Kabankalan, จังหวัด Negros Occidental เป็นโรงพยาบาลอนุสรณ์ Dr. Gumersindo Garcia, Sr.","id":"Undang-Undang mengubah nama Kabankalan Maternity Hospital di Kotamadya Kabankalan, Provinsi Negros Occidental menjadi Rumah Sakit Peringatan Dr. Gumersindo Garcia, Sr.","ms":"Akta menukar nama Kabankalan Maternity Hospital di Perbandaran Kabankalan, Wilayah Negros Occidental menjadi Hospital Peringatan Dr. Gumersindo Garcia, Sr."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5199","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5199_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4002-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Kabankalan Maternity Hospital, in the Municipality of Kabankalan, Province of Negros Occidental, is hereby changed to Dr. Gumersindo Garcia, Sr. Memorial Hospital."}},{"id":"PH-H4002-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Kabankalan Maternity Hospital in the Municipality of Kabankalan, Province of Negros Occidental, to Dr. Gumersindo Garcia, Sr. Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4003"] = {"id":"PH-H4003","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5200_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北伊罗戈省索尔索纳市镇利帕伊小学的名称授予纳利帕桑小学的法案","en":"An Act Granting the Name of Lipay Elementary School in the Municipality of Solsona, Province of Ilocos Norte, to Nalipasan Elementary School","orig":"An Act Granting the Name of Lipay Elementary School in the Municipality of Solsona, Province of Ilocos Norte, to Nalipasan Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5200","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5200_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4003-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Lipay Elementary School in the Municipality of Solsona, Province of Ilocos Norte, is hereby changed to Nalipasan Elementary School."}},{"id":"PH-H4003-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Name of Lipay Elementary School in the Municipality of Solsona, Province of Ilocos Norte, to Nalipasan Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4004"] = {"id":"PH-H4004","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5201_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北伊罗戈省 Espiritu市镇 Binacag 小学的名称变更为Quiaoit 纪念小学的法案","en":"An Act Changing the Name of Binacag Elementary School in the Municipality of Espiritu, Province of Ilocos Norte, to Quiaoit Memorial Elementary School","orig":"An Act Changing the Name of Binacag Elementary School in the Municipality of Espiritu, Province of Ilocos Norte, to Quiaoit Memorial Elementary School","vi":"Đạo luật đổi tên Trường tiểu học Binacag tại Thị trấn Espiritu, Tỉnh Ilocos Norte thành Trường tiểu học Quiaoit Memorial","th":"พระราชบัญญัติเปลี่ยนชื่อโรงเรียนประถมศึกษา Binacag ในเทศบาล Espiritu, จังหวัด Ilocos Norte เป็นโรงเรียนประถมศึกษา Quiaoit Memorial","id":"Undang-Undang mengubah nama Sekolah Dasar Binacag di Kotamadya Espiritu, Provinsi Ilocos Norte menjadi Sekolah Dasar Quiaoit Memorial","ms":"Akta menukar nama Sekolah Rendah Binacag di Perbandaran Espiritu, Wilayah Ilocos Norte menjadi Sekolah Rendah Quiaoit Memorial"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5201","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5201_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4004-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Binacag Elementary School in the Municipality of Espiritu, Province of Ilocos Norte, is hereby changed to Quiaoit Memorial Elementary School."}},{"id":"PH-H4004-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Binacag Elementary School in the Municipality of Espiritu, Province of Ilocos Norte, to Quiaoit Memorial Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4005"] = {"id":"PH-H4005","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5202_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在南达沃省设立畜牧场及繁育站并为此拨付所需经费的法案","en":"An Act Establishing a Stock Farm and/or Breeding Station in the Province of Davao del Sur, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Establishing a Stock Farm and/or Breeding Station in the Province of Davao del Sur, and Authorizing the Appropriation of the Necessary Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5202","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-05-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5202_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4005-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Animal Industry, a stock farm and/or breeding station in the Province of Davao del Sur, to be known as the Davao del Sur Stock Farm and Breeding Station."}},{"id":"PH-H4005-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Animal Industry shall establish said stock farm and breeding station on a suitable public or private land of not less than fifty hectares that may be reserved or acquired for the purpose."}},{"id":"PH-H4005-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment of the said stock farm and breeding station and for the purchaser of breeding animals, supplies and materials and such other expenses as may be necessary to carry out the purposes of this Act. Thereafter, such sum as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4005-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 13, 1968."}}],"pack":"ph-p56","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Stock Farm and/or Breeding Station in the Province of Davao del Sur, and Authorizing the Appropriation of the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
